<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>UUID 生成器</span>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="12">
          <el-form label-width="120px">
            <el-form-item label="生成数量">
              <el-input-number v-model="count" :min="1" :max="100" :step="1" />
            </el-form-item>
            
            <el-form-item label="UUID 版本">
              <el-radio-group v-model="version">
                <el-radio-button label="v4">V4 (随机)</el-radio-button>
                <el-radio-button label="v1">V1 (时间戳)</el-radio-button>
              </el-radio-group>
            </el-form-item>
            
            <el-form-item label="格式选项">
              <el-checkbox v-model="uppercase">大写</el-checkbox>
              <el-checkbox v-model="noDashes">去除横线</el-checkbox>
              <el-checkbox v-model="withBraces">带花括号</el-checkbox>
            </el-form-item>
            
            <el-form-item>
              <el-button type="primary" @click="generate">生成</el-button>
              <el-button @click="clear">清空</el-button>
            </el-form-item>
          </el-form>
        </el-col>
        
        <el-col :span="12">
          <div class="result-section">
            <div class="section-header">
              <span>生成结果</span>
              <el-button type="text" size="mini" @click="copyAll">复制全部</el-button>
            </div>
            <el-input
              v-model="result"
              type="textarea"
              :rows="12"
              readonly
              placeholder="生成的 UUID 将显示在这里"
            />
          </div>
        </el-col>
      </el-row>

      <el-row v-if="uuids.length > 0" style="margin-top: 20px">
        <el-col :span="24">
          <el-table :data="uuids" border size="small">
            <el-table-column type="index" width="60" align="center" />
            <el-table-column prop="uuid" label="UUID">
              <template slot-scope="scope">
                <code>{{ scope.row.uuid }}</code>
              </template>
            </el-table-column>
            <el-table-column width="100" align="center">
              <template slot-scope="scope">
                <el-button type="text" size="mini" @click="copy(scope.row.uuid)">复制</el-button>
              </template>
            </el-table-column>
          </el-table>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'UuidTool',
  data() {
    return {
      count: 5,
      version: 'v4',
      uppercase: false,
      noDashes: false,
      withBraces: false,
      result: '',
      uuids: []
    }
  },
  methods: {
    generate() {
      this.uuids = []
      const results = []
      
      for (let i = 0; i < this.count; i++) {
        let uuid = this.version === 'v4' ? this.generateV4() : this.generateV1()
        
        if (this.uppercase) {
          uuid = uuid.toUpperCase()
        }
        
        if (this.noDashes) {
          uuid = uuid.replace(/-/g, '')
        }
        
        if (this.withBraces) {
          uuid = `{${uuid}}`
        }
        
        this.uuids.push({ uuid })
        results.push(uuid)
      }
      
      this.result = results.join('\n')
    },
    generateV4() {
      return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        const r = Math.random() * 16 | 0
        const v = c === 'x' ? r : (r & 0x3 | 0x8)
        return v.toString(16)
      })
    },
    generateV1() {
      // 简化的 V1 实现
      const now = new Date().getTime()
      const uuid = 'xxxxxxxx-xxxx-1xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        const r = Math.random() * 16 | 0
        const v = c === 'x' ? r : (r & 0x3 | 0x8)
        return v.toString(16)
      })
      return uuid
    },
    clear() {
      this.result = ''
      this.uuids = []
    },
    copy(text) {
      navigator.clipboard.writeText(text).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    copyAll() {
      if (!this.result) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.result).then(() => {
        this.$message.success('已复制全部到剪贴板')
      })
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .result-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }
  }

  code {
    font-family: monospace;
    font-size: 12px;
  }
}
</style>
