<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header" class="card-header">
        <span class="card-title">大模型调试工具</span>
        <el-button-group class="header-actions">
          <el-button size="small" icon="el-icon-menu" @click="showSessionPanel = !showSessionPanel">
            {{ showSessionPanel ? '隐藏会话' : '会话列表' }}
          </el-button>
          <el-button size="small" @click="showConfig = !showConfig">
            {{ showConfig ? '隐藏配置' : '显示配置' }}
          </el-button>
          <el-button size="small" @click="clearChat">清空对话</el-button>
          <el-button size="small" @click="exportChat">导出对话</el-button>
        </el-button-group>
      </div>

      <el-row :gutter="20">
        <el-col :span="24">
          <el-collapse-transition>
            <div v-show="showConfig" class="config-panel">
              <el-form :model="config" :label-width="formLabelWidth" size="small">
                <el-row :gutter="20">
                  <el-col :xs="24" :sm="12">
                    <el-form-item label="API 地址">
                      <el-input v-model="config.apiUrl" placeholder="https://api.openai.com/v1/chat/completions">
                        <el-button slot="append" @click="showApiPresets">预设</el-button>
                      </el-input>
                    </el-form-item>
                  </el-col>
                  <el-col :xs="24" :sm="12">
                    <el-form-item label="API Key">
                      <el-input v-model="config.apiKey" type="password" show-password placeholder="sk-..." />
                    </el-form-item>
                  </el-col>
                </el-row>
                <el-row :gutter="20">
                  <el-col :xs="24" :sm="12">
                    <el-form-item label="协议">
                      <el-radio-group v-model="config.protocol" @change="onProtocolChange">
                        <el-radio-button label="openai">OpenAI</el-radio-button>
                        <el-radio-button label="anthropic">Anthropic</el-radio-button>
                      </el-radio-group>
                    </el-form-item>
                  </el-col>
                  <el-col :xs="24" :sm="12">
                    <el-form-item label="配置模式">
                      <el-radio-group v-model="configMode" @change="onConfigModeChange">
                        <el-radio label="form">表单配置</el-radio>
                        <el-radio label="json">JSON 配置</el-radio>
                      </el-radio-group>
                    </el-form-item>
                  </el-col>
                </el-row>
                <template v-if="configMode === 'form'">
                  <el-row :gutter="20" v-if="config.protocol === 'anthropic'">
                    <el-col :span="24">
                      <el-form-item label="API 版本">
                        <el-input v-model="config.anthropicVersion" placeholder="2023-06-01" style="max-width: 240px" />
                        <el-tooltip content="Anthropic 的 anthropic-version 请求头，默认 2023-06-01" placement="top">
                          <i class="el-icon-question" slot="reference" style="margin-left: 8px"></i>
                        </el-tooltip>
                      </el-form-item>
                    </el-col>
                  </el-row>
                  <el-row :gutter="20">
                    <el-col :span="24">
                      <el-form-item label="模型">
                        <el-select v-model="config.model" filterable allow-create default-first-option placeholder="选择或输入模型">
                          <el-option v-for="m in modelOptions" :key="m" :label="m" :value="m" />
                        </el-select>
                        <el-tooltip content="可以直接输入自定义模型名称" placement="top">
                          <i class="el-icon-question" slot="reference"></i>
                        </el-tooltip>
                      </el-form-item>
                    </el-col>
                  </el-row>
                  <el-row :gutter="20">
                    <el-col :xs="24" :sm="8">
                      <el-form-item label="Temperature">
                        <el-slider v-model="config.temperature" :min="0" :max="2" :step="0.1" show-input />
                      </el-form-item>
                    </el-col>
                    <el-col :xs="24" :sm="8">
                      <el-form-item label="Max Tokens">
                        <el-input-number v-model="config.maxTokens" :min="1" :max="128000" />
                      </el-form-item>
                    </el-col>
                    <el-col :xs="24" :sm="8">
                      <el-form-item label="流式输出">
                        <el-switch v-model="config.stream" />
                      </el-form-item>
                    </el-col>
                  </el-row>
                  <el-row :gutter="20">
                    <el-col :span="24">
                      <el-form-item label="系统提示词">
                        <el-input
                          v-model="config.systemPrompt"
                          type="textarea"
                          :autosize="{ minRows: 3, maxRows: 10 }"
                          placeholder="你是一个有帮助的助手..."
                          resize="vertical"
                        />
                      </el-form-item>
                    </el-col>
                  </el-row>
                  <el-row :gutter="20">
                    <el-col :span="24">
                      <el-form-item label="自定义请求头">
                        <div class="custom-headers">
                          <div v-for="(header, index) in config.customHeaders" :key="index" class="header-row">
                            <el-input v-model="header.key" placeholder="Header Name" style="width: 35%" />
                            <el-input v-model="header.value" placeholder="Header Value" style="width: 55%" />
                            <el-button type="danger" icon="el-icon-delete" circle size="mini" @click="removeCustomHeader(index)" />
                          </div>
                          <el-button size="mini" @click="addCustomHeader">添加请求头</el-button>
                        </div>
                      </el-form-item>
                    </el-col>
                  </el-row>
                </template>
                <template v-else>
                  <el-row :gutter="20">
                    <el-col :span="24">
                      <el-form-item label="请求参数">
                        <div class="json-config">
                          <el-input
                            v-model="customJsonParams"
                            type="textarea"
                            :rows="12"
                            placeholder='输入完整的请求参数 JSON，例如：
{
  "model": "gpt-3.5-turbo",
  "temperature": 0.7,
  "max_tokens": 2000,
  "stream": true,
  "top_p": 1,
  "frequency_penalty": 0,
  "presence_penalty": 0,
  "response_format": { "type": "text" }
}'
                          />
                          <div class="json-actions">
                            <el-button size="mini" @click="formatJson">格式化 JSON</el-button>
                            <el-button size="mini" @click="resetJson">重置为默认</el-button>
                            <span v-if="jsonError" class="json-error">{{ jsonError }}</span>
                          </div>
                        </div>
                      </el-form-item>
                    </el-col>
                  </el-row>
                  <el-row :gutter="20">
                    <el-col :span="24">
                      <el-form-item label="自定义请求头">
                        <el-input
                          v-model="customHeadersJson"
                          type="textarea"
                          :rows="4"
                          placeholder='输入请求头 JSON，例如：
{
  "Authorization": "Bearer YOUR_API_KEY",
  "Content-Type": "application/json"
}'
                        />
                      </el-form-item>
                    </el-col>
                  </el-row>
                </template>
              </el-form>
            </div>
          </el-collapse-transition>
        </el-col>
      </el-row>

      <div class="chat-stats-bar">
        <el-tag size="mini" type="info">会话: {{ activeSession ? activeSession.title : '无' }}</el-tag>
        <el-tag size="mini">消息数: {{ messageCount }}</el-tag>
        <el-tag size="mini" type="success" v-if="totalTokens > 0">累计 Token: {{ totalTokens }}</el-tag>
      </div>

      <div class="chat-layout">
        <!-- 会话列表面板 -->
        <div v-show="showSessionPanel" class="session-panel">
          <div class="session-panel-header">
            <span>会话列表</span>
            <el-button type="primary" size="mini" icon="el-icon-plus" @click="newSession">新建</el-button>
          </div>
          <div class="session-list">
            <div
              v-for="session in sessions"
              :key="session.id"
              :class="['session-item', { active: session.id === activeSessionId }]"
              @click="switchSession(session.id)"
            >
              <i class="el-icon-chat-line-square"></i>
              <span class="session-title" :title="session.title">{{ session.title }}</span>
              <span class="session-count">{{ session.messages.length }}</span>
              <span class="session-ops">
                <i class="el-icon-edit" title="重命名" @click.stop="renameSession(session)"></i>
                <i class="el-icon-delete" title="删除" @click.stop="deleteSession(session.id)"></i>
              </span>
            </div>
          </div>
        </div>

        <!-- 对话区 -->
        <div class="chat-main">
          <div class="chat-container" ref="chatContainer">
            <div v-if="messages.length === 0" class="empty-chat">
              <i class="el-icon-chat-dot-round"></i>
              <p>开始与大模型对话吧！</p>
            </div>
            <div v-for="msg in messages" :key="msg.id" :class="['message', msg.role]">
              <div class="message-avatar">
                <i :class="msg.role === 'user' ? 'el-icon-user' : 'el-icon-cpu'"></i>
              </div>
              <div class="message-content">
                <div class="message-header">
                  <span class="role-name">{{ msg.role === 'user' ? '用户' : '助手' }}</span>
                  <span class="message-time">{{ msg.time }}</span>
                  <div class="message-ops">
                    <el-button type="text" size="mini" @click="copyMessage(msg.content)">
                      <i class="el-icon-document-copy"></i> 复制
                    </el-button>
                    <el-button v-if="msg.role === 'user'" type="text" size="mini" :disabled="isLoading" @click="editMessage(msg.id)">
                      <i class="el-icon-edit-outline"></i> 编辑
                    </el-button>
                    <el-button v-if="msg.role === 'assistant'" type="text" size="mini" :disabled="isLoading" @click="regenerate(msg.id)">
                      <i class="el-icon-refresh-right"></i> 重新生成
                    </el-button>
                    <el-button type="text" size="mini" :disabled="isLoading" @click="deleteMessage(msg.id)">
                      <i class="el-icon-delete"></i> 删除
                    </el-button>
                  </div>
                </div>
                <div class="message-text" v-html="formatMessage(msg.content)"></div>
                <div v-if="msg.role === 'assistant' && msg.tokens" class="message-stats">
                  <el-tag size="mini" type="info">Token: {{ msg.tokens }}</el-tag>
                </div>
              </div>
            </div>
            <div v-if="isLoading" class="message assistant">
              <div class="message-avatar">
                <i class="el-icon-cpu"></i>
              </div>
              <div class="message-content">
                <div class="message-header">
                  <span class="role-name">助手</span>
                </div>
                <div class="message-text loading">
                  <span class="typing-indicator">
                    <span></span><span></span><span></span>
                  </span>
                  <span v-if="streamingContent">{{ streamingContent }}</span>
                </div>
              </div>
            </div>
          </div>

          <div class="input-area">
            <el-input
              v-model="userInput"
              type="textarea"
              :rows="3"
              placeholder="输入你的问题... (Ctrl+Enter 发送)"
              @keydown.ctrl.enter.native="sendMessage"
            />
            <div class="input-actions">
              <el-button type="primary" :loading="isLoading" @click="sendMessage">
                {{ isLoading ? '生成中...' : '发送' }}
              </el-button>
              <el-button v-if="isLoading" type="danger" @click="stopGeneration">停止</el-button>
            </div>
          </div>
        </div>
      </div>
    </el-card>

    <el-dialog title="API 预设" :visible.sync="presetDialogVisible" width="500px">
      <div class="preset-list">
        <div v-for="preset in getAvailablePresets()" :key="preset.name" class="preset-item" @click="applyPreset(preset)">
          <div class="preset-name">{{ preset.name }}</div>
          <div class="preset-url">{{ preset.url }}</div>
        </div>
      </div>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: 'LLMTool',
  data() {
    return {
      showConfig: true,
      backendAvailable: false,
      checkingBackend: true,
      configMode: 'form',
      customJsonParams: '',
      customHeadersJson: '',
      jsonError: '',
      config: {
        apiUrl: 'https://api.openai.com/v1/chat/completions',
        apiKey: '',
        protocol: 'openai',
        anthropicVersion: '2023-06-01',
        model: 'gpt-5.5',
        temperature: 0.7,
        maxTokens: 2000,
        stream: true,
        systemPrompt: '你是一个有帮助的AI助手。',
        customHeaders: []
      },
      modelOptions: [
        'gpt-5.5',
        'gpt-5.4',
        'gpt-4o',
        'gpt-4o-mini',
        'gpt-4-turbo',
        'gpt-4',
        'gpt-3.5-turbo',
        'claude-fable-5',
        'claude-opus-4-8',
        'claude-opus-4-7',
        'claude-opus-4-6',
        'claude-sonnet-4-6',
        'claude-haiku-4-5-20251001',
        'claude-3-5-sonnet-20241022',
        'claude-3-5-haiku-20241022',
        'claude-3-opus-20240229',
        'claude-3-sonnet-20240229',
        'claude-3-haiku-20240307',
        'deepseek-chat',
        'deepseek-coder',
        'qwen-turbo',
        'qwen-plus',
        'qwen-max',
        'glm-4',
        'glm-4-flash',
        'moonshot-v1-8k',
        'moonshot-v1-32k',
        'moonshot-v1-128k'
      ],
      sessions: [],
      activeSessionId: '',
      sessionCounter: 0,
      showSessionPanel: true,
      isNarrow: false,
      userInput: '',
      isLoading: false,
      streamingContent: '',
      eventSource: null,
      presetDialogVisible: false,
      apiPresets: [
        { name: 'OpenAI', url: 'https://api.openai.com/v1/chat/completions', model: 'gpt-5.5', protocol: 'openai' },
        { name: 'Azure OpenAI', url: 'https://YOUR_RESOURCE.openai.azure.com/openai/deployments/YOUR_DEPLOYMENT/chat/completions?api-version=2024-02-15-preview', model: 'gpt-35-turbo', protocol: 'openai' },
        { name: 'Claude (Anthropic)', url: 'https://api.anthropic.com/v1/messages', model: 'claude-opus-4-8', protocol: 'anthropic' },
        { name: 'DeepSeek', url: 'https://api.deepseek.com/v1/chat/completions', model: 'deepseek-chat', protocol: 'openai' },
        { name: '通义千问', url: 'https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions', model: 'qwen-turbo', protocol: 'openai' },
        { name: '智谱 GLM', url: 'https://open.bigmodel.cn/api/paas/v4/chat/completions', model: 'glm-4', protocol: 'openai' },
        { name: 'Moonshot', url: 'https://api.moonshot.cn/v1/chat/completions', model: 'moonshot-v1-8k', protocol: 'openai' },
        { name: '本地后端代理', url: 'http://localhost:8080/api/llm/chat', model: 'gpt-3.5-turbo', protocol: 'openai', needBackend: true }
      ]
    }
  },
  computed: {
    activeSession() {
      return this.sessions.find(s => s.id === this.activeSessionId) || null
    },
    messages() {
      return this.activeSession ? this.activeSession.messages : []
    },
    messageCount() {
      return this.messages.length
    },
    totalTokens() {
      return this.messages.reduce((sum, m) => sum + (m.tokens || 0), 0)
    },
    formLabelWidth() {
      return this.isNarrow ? '80px' : '100px'
    }
  },
  async mounted() {
    this.loadConfig()
    this.loadSessions()
    this.handleResize()
    window.addEventListener('resize', this.handleResize)
    await this.checkBackendAvailability()
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.handleResize)
  },
  methods: {
    generateMessageId() {
      return 'msg-' + Date.now() + '-' + Math.random().toString(36).slice(2, 9)
    },
    handleResize() {
      this.isNarrow = window.innerWidth < 768
      // 窄屏默认收起会话面板，避免挤占聊天区
      if (this.isNarrow) {
        this.showSessionPanel = false
      }
    },
    async checkBackendAvailability() {
      try {
        const response = await fetch('http://localhost:8080/api/ping', {
          method: 'GET',
          headers: { 'Content-Type': 'application/json' }
        })
        this.backendAvailable = response.ok
      } catch (e) {
        this.backendAvailable = false
      } finally {
        this.checkingBackend = false
      }
    },
    onConfigModeChange(mode) {
      if (mode === 'json') {
        if (this.config.protocol === 'anthropic') {
          const body = {
            model: this.config.model,
            max_tokens: this.config.maxTokens,
            temperature: this.config.temperature,
            stream: this.config.stream
          }
          if (this.config.systemPrompt) {
            body.system = this.config.systemPrompt
          }
          this.customJsonParams = JSON.stringify(body, null, 2)

          const headers = {
            'Content-Type': 'application/json',
            'anthropic-version': this.config.anthropicVersion || '2023-06-01',
            'anthropic-dangerous-direct-browser-access': 'true'
          }
          if (this.config.apiKey) {
            headers['x-api-key'] = this.config.apiKey
          }
          this.customHeadersJson = JSON.stringify(headers, null, 2)
          return
        }

        this.customJsonParams = JSON.stringify({
          model: this.config.model,
          temperature: this.config.temperature,
          max_tokens: this.config.maxTokens,
          stream: this.config.stream,
          top_p: 1,
          frequency_penalty: 0,
          presence_penalty: 0
        }, null, 2)

        const headers = {
          'Content-Type': 'application/json'
        }
        if (this.config.apiKey) {
          headers['Authorization'] = `Bearer ${this.config.apiKey}`
        }
        this.customHeadersJson = JSON.stringify(headers, null, 2)
      }
    },
    formatJson() {
      try {
        const parsed = JSON.parse(this.customJsonParams)
        this.customJsonParams = JSON.stringify(parsed, null, 2)
        this.jsonError = ''
      } catch (e) {
        this.jsonError = 'JSON 格式错误: ' + e.message
      }
    },
    resetJson() {
      this.customJsonParams = JSON.stringify({
        model: 'gpt-3.5-turbo',
        temperature: 0.7,
        max_tokens: 2000,
        stream: true,
        top_p: 1,
        frequency_penalty: 0,
        presence_penalty: 0
      }, null, 2)
      this.jsonError = ''
    },
    async sendMessage() {
      if (!this.userInput.trim() || this.isLoading) return

      if (this.configMode === 'json') {
        try {
          JSON.parse(this.customJsonParams)
        } catch (e) {
          this.$message.error('请求参数 JSON 格式错误')
          return
        }
      }

      if (!this.config.apiKey && !this.config.apiUrl.includes('localhost')) {
        this.$message.warning('请先配置 API Key')
        return
      }

      if (!this.activeSession) {
        this.newSession()
      }

      const userMessage = {
        id: this.generateMessageId(),
        role: 'user',
        content: this.userInput,
        time: new Date().toLocaleTimeString()
      }
      this.activeSession.messages.push(userMessage)
      this.maybeAutoTitle()
      this.userInput = ''

      await this.requestCompletion()
    },
    async requestCompletion() {
      this.isLoading = true
      this.streamingContent = ''

      this.$nextTick(() => {
        this.scrollToBottom()
      })

      try {
        const messages = this.buildMessages()

        if (this.config.apiUrl.includes('localhost')) {
          await this.sendViaBackend(messages)
        } else {
          await this.sendDirectly(messages)
        }
      } catch (error) {
        this.$message.error('请求失败: ' + error.message)
        this.activeSession.messages.push({
          id: this.generateMessageId(),
          role: 'assistant',
          content: '错误: ' + error.message,
          time: new Date().toLocaleTimeString()
        })
      } finally {
        this.isLoading = false
      }
    },
    buildMessages() {
      const messages = []
      
      if (this.configMode === 'form' && this.config.systemPrompt) {
        messages.push({
          role: 'system',
          content: this.config.systemPrompt
        })
      }
      
      this.messages.forEach(msg => {
        messages.push({
          role: msg.role,
          content: msg.content
        })
      })
      
      return messages
    },
    async sendViaBackend(messages) {
      const response = await fetch(this.config.apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          apiUrl: this.config.apiUrl === 'http://localhost:8080/api/llm/chat' 
            ? 'https://api.openai.com/v1/chat/completions' 
            : this.config.apiUrl,
          apiKey: this.config.apiKey,
          model: this.config.model,
          messages: messages,
          temperature: this.config.temperature,
          maxTokens: this.config.maxTokens,
          stream: this.config.stream,
          headers: this.config.customHeaders.reduce((acc, h) => {
            if (h.key) acc[h.key] = h.value
            return acc
          }, {})
        })
      })

      const reader = response.body.getReader()
      const decoder = new TextDecoder()
      let fullContent = ''

      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        const chunk = decoder.decode(value)
        const lines = chunk.split('\n')

        for (const line of lines) {
          if (line.startsWith('data:')) {
            const data = line.substring(5).trim()
            if (data) {
              try {
                const json = JSON.parse(data)
                if (json.event === 'message' && json.data) {
                  fullContent += json.data
                  this.streamingContent = fullContent
                  this.scrollToBottom()
                } else if (json.event === 'done') {
                  this.activeSession.messages.push({
                    id: this.generateMessageId(),
                    role: 'assistant',
                    content: fullContent,
                    time: new Date().toLocaleTimeString()
                  })
                  this.streamingContent = ''
                } else if (json.event === 'error') {
                  throw new Error(json.data)
                }
              } catch (e) {
                // 忽略解析错误
              }
            }
          }
        }
      }
    },
    async sendDirectly(messages) {
      if (this.configMode !== 'json' && this.config.protocol === 'anthropic') {
        await this.sendAnthropic(messages)
        return
      }

      let headers = {}
      let bodyParams = {}

      if (this.configMode === 'json') {
        try {
          headers = JSON.parse(this.customHeadersJson || '{}')
          bodyParams = JSON.parse(this.customJsonParams)
        } catch (e) {
          throw new Error('JSON 解析错误: ' + e.message)
        }
        bodyParams.messages = messages
      } else {
        headers = {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.config.apiKey}`
        }

        this.config.customHeaders.forEach(h => {
          if (h.key) headers[h.key] = h.value
        })

        bodyParams = {
          model: this.config.model,
          messages: messages,
          temperature: this.config.temperature,
          max_tokens: this.config.maxTokens,
          stream: this.config.stream
        }
      }

      const isStream = bodyParams.stream === true

      if (isStream) {
        const response = await fetch(this.config.apiUrl, {
          method: 'POST',
          headers: headers,
          body: JSON.stringify(bodyParams)
        })

        if (!response.ok) {
          const error = await response.json()
          throw new Error(error.error?.message || '请求失败')
        }

        const reader = response.body.getReader()
        const decoder = new TextDecoder()
        let fullContent = ''

        while (true) {
          const { done, value } = await reader.read()
          if (done) break

          const chunk = decoder.decode(value)
          const lines = chunk.split('\n')

          for (const line of lines) {
            if (line.startsWith('data: ')) {
              const data = line.substring(6)
              if (data === '[DONE]') continue

              try {
                const json = JSON.parse(data)
                const content = json.choices?.[0]?.delta?.content
                if (content) {
                  fullContent += content
                  this.streamingContent = fullContent
                  this.scrollToBottom()
                }
              } catch (e) {
                // 忽略解析错误
              }
            }
          }
        }

        this.activeSession.messages.push({
          id: this.generateMessageId(),
          role: 'assistant',
          content: fullContent,
          time: new Date().toLocaleTimeString()
        })
        this.streamingContent = ''
      } else {
        const response = await fetch(this.config.apiUrl, {
          method: 'POST',
          headers: headers,
          body: JSON.stringify(bodyParams)
        })

        if (!response.ok) {
          const error = await response.json()
          throw new Error(error.error?.message || '请求失败')
        }

        const data = await response.json()
        const content = data.choices?.[0]?.message?.content || ''

        this.activeSession.messages.push({
          role: 'assistant',
          content: content,
          time: new Date().toLocaleTimeString(),
          tokens: data.usage?.total_tokens
        })
      }
    },
    async sendAnthropic(messages) {
      // Anthropic 协议：system 独立字段，messages 仅含 user/assistant
      const systemPrompt = this.config.systemPrompt
      const chatMessages = messages
        .filter(m => m.role !== 'system')
        .map(m => ({ role: m.role, content: m.content }))

      const headers = {
        'Content-Type': 'application/json',
        'x-api-key': this.config.apiKey,
        'anthropic-version': this.config.anthropicVersion || '2023-06-01',
        // 允许浏览器直连 Anthropic API（否则会被 CORS 拦截）
        'anthropic-dangerous-direct-browser-access': 'true'
      }
      this.config.customHeaders.forEach(h => {
        if (h.key) headers[h.key] = h.value
      })

      const bodyParams = {
        model: this.config.model,
        max_tokens: this.config.maxTokens,
        messages: chatMessages,
        temperature: this.config.temperature,
        stream: this.config.stream
      }
      if (systemPrompt) {
        bodyParams.system = systemPrompt
      }

      const response = await fetch(this.config.apiUrl, {
        method: 'POST',
        headers: headers,
        body: JSON.stringify(bodyParams)
      })

      if (!response.ok) {
        let msg = '请求失败'
        try {
          const error = await response.json()
          msg = error.error?.message || error.message || msg
        } catch (e) { /* 非 JSON 错误体 */ }
        throw new Error(msg)
      }

      if (this.config.stream) {
        const reader = response.body.getReader()
        const decoder = new TextDecoder()
        let fullContent = ''
        let buffer = ''

        while (true) {
          const { done, value } = await reader.read()
          if (done) break

          buffer += decoder.decode(value, { stream: true })
          const lines = buffer.split('\n')
          buffer = lines.pop() || ''

          for (const line of lines) {
            const trimmed = line.trim()
            if (!trimmed.startsWith('data:')) continue
            const data = trimmed.substring(5).trim()
            if (!data) continue

            try {
              const json = JSON.parse(data)
              // 文本增量事件
              if (json.type === 'content_block_delta' && json.delta?.text) {
                fullContent += json.delta.text
                this.streamingContent = fullContent
                this.scrollToBottom()
              } else if (json.type === 'error') {
                throw new Error(json.error?.message || 'Anthropic 流式错误')
              }
            } catch (e) {
              if (e.message && e.message.includes('Anthropic')) throw e
              // 其他解析错误忽略
            }
          }
        }

        this.activeSession.messages.push({
          id: this.generateMessageId(),
          role: 'assistant',
          content: fullContent,
          time: new Date().toLocaleTimeString()
        })
        this.streamingContent = ''
      } else {
        const data = await response.json()
        const content = (data.content || [])
          .filter(block => block.type === 'text')
          .map(block => block.text)
          .join('')
        const usage = data.usage || {}
        const totalTokens = (usage.input_tokens || 0) + (usage.output_tokens || 0)

        this.activeSession.messages.push({
          role: 'assistant',
          content: content,
          time: new Date().toLocaleTimeString(),
          tokens: totalTokens || undefined
        })
      }
    },
    stopGeneration() {
      this.isLoading = false
      if (this.streamingContent) {
        this.activeSession.messages.push({
          role: 'assistant',
          content: this.streamingContent + ' [已停止]',
          time: new Date().toLocaleTimeString()
        })
        this.streamingContent = ''
      }
    },
    formatMessage(content) {
      if (!content) return ''
      
      let formatted = content
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
      
      formatted = formatted.replace(/```(\w*)\n?([\s\S]*?)```/g, (match, lang, code) => {
        return `<pre class="code-block"><code class="language-${lang}">${code.trim()}</code></pre>`
      })
      
      formatted = formatted.replace(/`([^`]+)`/g, '<code class="inline-code">$1</code>')
      
      formatted = formatted.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
      formatted = formatted.replace(/\*([^*]+)\*/g, '<em>$1</em>')
      
      formatted = formatted.replace(/\n/g, '<br>')
      
      return formatted
    },
    scrollToBottom() {
      this.$nextTick(() => {
        const container = this.$refs.chatContainer
        if (container) {
          container.scrollTop = container.scrollHeight
        }
      })
    },
    clearChat() {
      if (!this.activeSession || this.messages.length === 0) {
        this.$message.info('当前会话没有内容')
        return
      }
      this.$confirm('确定要清空当前会话的全部对话吗？此操作不可恢复。', '清空确认', {
        confirmButtonText: '清空',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        this.activeSession.messages = []
        this.streamingContent = ''
        this.$message.success('已清空当前会话')
      }).catch(() => {})
    },
    copyMessage(content) {
      navigator.clipboard.writeText(content).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    exportChat() {
      const content = this.messages.map(m => {
        const role = m.role === 'user' ? '用户' : '助手'
        return `【${role}】${m.time}\n${m.content}\n`
      }).join('\n---\n')
      
      const blob = new Blob([content], { type: 'text/plain;charset=utf-8' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `chat_${new Date().toISOString().slice(0, 10)}.txt`
      a.click()
      URL.revokeObjectURL(url)
    },
    showApiPresets() {
      this.presetDialogVisible = true
    },
    applyPreset(preset) {
      this.config.apiUrl = preset.url
      this.config.model = preset.model
      if (preset.protocol) {
        this.config.protocol = preset.protocol
      }
      this.presetDialogVisible = false
    },
    onProtocolChange() {
      // 切换协议时，若仍是 JSON 配置模式，则重新生成对应协议的默认 JSON
      if (this.configMode === 'json') {
        this.onConfigModeChange('json')
      }
    },
    getAvailablePresets() {
      if (this.backendAvailable) {
        return this.apiPresets
      } else {
        return this.apiPresets.filter(preset => !preset.needBackend)
      }
    },
    addCustomHeader() {
      this.config.customHeaders.push({ key: '', value: '' })
    },
    removeCustomHeader(index) {
      this.config.customHeaders.splice(index, 1)
    },
    // ===== 会话管理 =====
    newSession() {
      this.sessionCounter++
      const session = {
        id: 's-' + this.sessionCounter + '-' + Date.now(),
        title: '新对话 ' + this.sessionCounter,
        autoTitled: false,
        messages: []
      }
      this.sessions.unshift(session)
      this.activeSessionId = session.id
      this.streamingContent = ''
      return session
    },
    switchSession(id) {
      if (this.isLoading) {
        this.$message.warning('生成中，请稍候再切换会话')
        return
      }
      this.activeSessionId = id
      this.streamingContent = ''
      this.$nextTick(() => this.scrollToBottom())
    },
    renameSession(session) {
      this.$prompt('请输入新的会话名称', '重命名会话', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        inputValue: session.title,
        inputValidator: v => (v && v.trim() ? true : '名称不能为空')
      }).then(({ value }) => {
        session.title = value.trim()
        session.autoTitled = true
      }).catch(() => {})
    },
    deleteSession(id) {
      this.$confirm('确定删除这个会话吗？此操作不可恢复。', '删除会话', {
        confirmButtonText: '删除',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        const index = this.sessions.findIndex(s => s.id === id)
        if (index === -1) return
        this.sessions.splice(index, 1)
        if (this.activeSessionId === id) {
          if (this.sessions.length === 0) {
            this.newSession()
          } else {
            this.activeSessionId = this.sessions[Math.max(0, index - 1)].id
          }
        }
        this.$message.success('已删除会话')
      }).catch(() => {})
    },
    maybeAutoTitle() {
      const session = this.activeSession
      if (!session || session.autoTitled) return
      const firstUser = session.messages.find(m => m.role === 'user')
      if (firstUser) {
        session.title = firstUser.content.slice(0, 20).replace(/\n/g, ' ') || session.title
        session.autoTitled = true
      }
    },
    // ===== 消息级操作 =====
    deleteMessage(msgId) {
      const index = this.activeSession.messages.findIndex(m => m.id === msgId)
      if (index !== -1) {
        this.activeSession.messages.splice(index, 1)
      }
    },
    editMessage(msgId) {
      if (this.isLoading) return
      const index = this.activeSession.messages.findIndex(m => m.id === msgId)
      if (index === -1) return
      const msg = this.activeSession.messages[index]
      if (msg.role !== 'user') return
      this.userInput = msg.content
      // 移除该用户消息及其之后的所有消息，便于编辑后重新发送
      this.activeSession.messages.splice(index)
    },
    async regenerate(msgId) {
      if (this.isLoading) return
      // 删除该助手消息及其之后的内容，基于之前的上下文重新生成
      const index = this.activeSession.messages.findIndex(m => m.id === msgId)
      if (index === -1) return
      this.activeSession.messages.splice(index)
      if (this.activeSession.messages.length === 0) {
        this.$message.warning('没有可用于重新生成的上文')
        return
      }
      await this.requestCompletion()
    },
    loadSessions() {
      const saved = localStorage.getItem('llm_sessions')
      if (saved) {
        try {
          const data = JSON.parse(saved)
          this.sessions = data.sessions || []
          this.sessionCounter = data.sessionCounter || this.sessions.length
          this.activeSessionId = data.activeSessionId || (this.sessions[0] && this.sessions[0].id) || ''
        } catch (e) {
          // 忽略解析错误
        }
      }
      if (this.sessions.length === 0) {
        this.newSession()
      } else if (!this.activeSession) {
        this.activeSessionId = this.sessions[0].id
      }
    },
    saveSessions() {
      localStorage.setItem('llm_sessions', JSON.stringify({
        sessions: this.sessions,
        sessionCounter: this.sessionCounter,
        activeSessionId: this.activeSessionId
      }))
    },
    loadConfig() {
      const saved = localStorage.getItem('llm_config')
      if (saved) {
        try {
          const config = JSON.parse(saved)
          this.config = { ...this.config, ...config }
        } catch (e) {
          // 忽略解析错误
        }
      }
    },
    saveConfig() {
      localStorage.setItem('llm_config', JSON.stringify(this.config))
    }
  },
  watch: {
    config: {
      handler() {
        this.saveConfig()
      },
      deep: true
    },
    sessions: {
      handler() {
        this.saveSessions()
      },
      deep: true
    },
    activeSessionId() {
      this.saveSessions()
    }
  }
}
</script>

