<template>
  <div class="file-preview-tool">
    <el-card>
      <div slot="header">
        <span>文件预览工具</span>
      </div>

      <el-tabs v-model="activeTab">
        <el-tab-pane label="PDF预览" name="pdf">
          <el-upload
            class="upload-area"
            drag
            action=""
            :auto-upload="false"
            :on-change="handlePdfChange"
            :show-file-list="false"
            accept=".pdf"
          >
            <i class="el-icon-upload"></i>
            <div class="el-upload__text">将PDF文件拖到此处，或<em>点击上传</em></div>
          </el-upload>

          <div v-if="pdfUrl" class="preview-container">
            <div class="preview-toolbar">
              <el-button-group>
                <el-button size="small" @click="prevPdfPage" :disabled="pdfPage <= 1">
                  <i class="el-icon-arrow-left"></i>
                </el-button>
                <el-button size="small" disabled>{{ pdfPage }} / {{ pdfTotalPages }}</el-button>
                <el-button size="small" @click="nextPdfPage" :disabled="pdfPage >= pdfTotalPages">
                  <i class="el-icon-arrow-right"></i>
                </el-button>
              </el-button-group>
              <el-slider v-model="pdfScale" :min="50" :max="200" style="width: 150px; margin: 0 15px;" />
              <el-button size="small" @click="downloadPdf">下载</el-button>
            </div>
            <div class="pdf-viewer">
              <canvas ref="pdfCanvas"></canvas>
            </div>
          </div>
        </el-tab-pane>

        <el-tab-pane label="Excel/CSV预览" name="excel">
          <el-upload
            class="upload-area"
            drag
            action=""
            :auto-upload="false"
            :on-change="handleExcelChange"
            :show-file-list="false"
            accept=".xlsx,.xls,.csv"
          >
            <i class="el-icon-upload"></i>
            <div class="el-upload__text">将Excel或CSV文件拖到此处，或<em>点击上传</em></div>
          </el-upload>

          <div v-if="excelData.length > 0" class="preview-container">
            <div class="preview-toolbar">
              <span class="file-info">共 {{ excelData.length }} 行数据</span>
              <el-button size="small" @click="downloadExcel">导出CSV</el-button>
            </div>
            <el-table
              :data="excelData"
              border
              height="500"
              style="width: 100%"
            >
              <el-table-column
                v-for="(header, index) in excelHeaders"
                :key="index"
                :prop="header"
                :label="header"
                min-width="120"
                show-overflow-tooltip
              />
            </el-table>
          </div>
        </el-tab-pane>

        <el-tab-pane label="文本文件" name="text">
          <el-upload
            class="upload-area"
            drag
            action=""
            :auto-upload="false"
            :on-change="handleTextChange"
            :show-file-list="false"
            accept=".txt,.json,.xml,.md,.js,.css,.html,.java,.py,.sql"
          >
            <i class="el-icon-upload"></i>
            <div class="el-upload__text">将文本文件拖到此处，或<em>点击上传</em></div>
          </el-upload>

          <div v-if="textContent" class="preview-container">
            <div class="preview-toolbar">
              <span class="file-info">{{ textFileName }} - {{ formatFileSize(textFileSize) }}</span>
              <el-button size="small" @click="copyTextContent">复制</el-button>
              <el-button size="small" @click="downloadText">下载</el-button>
            </div>
            <pre class="text-preview"><code>{{ textContent }}</code></pre>
          </div>
        </el-tab-pane>

        <el-tab-pane label="Markdown" name="markdown">
          <el-upload
            class="upload-area"
            drag
            action=""
            :auto-upload="false"
            :on-change="handleMarkdownChange"
            :show-file-list="false"
            accept=".md,.markdown"
          >
            <i class="el-icon-upload"></i>
            <div class="el-upload__text">将Markdown文件拖到此处，或<em>点击上传</em></div>
          </el-upload>

          <div v-if="markdownContent" class="preview-container">
            <div class="preview-toolbar">
              <span class="file-info">{{ markdownFileName }}</span>
              <el-button size="small" @click="downloadMarkdown">下载</el-button>
            </div>
            <div class="markdown-preview" v-html="renderedMarkdown"></div>
          </div>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
import * as XLSX from 'xlsx'
import { marked } from 'marked'

export default {
  name: 'FilePreviewTool',
  data() {
    return {
      activeTab: 'pdf',
      
      // PDF
      pdfUrl: null,
      pdfPage: 1,
      pdfTotalPages: 0,
      pdfScale: 100,
      pdfDoc: null,
      
      // Excel
      excelData: [],
      excelHeaders: [],
      excelFileName: '',
      
      // Text
      textContent: '',
      textFileName: '',
      textFileSize: 0,
      
      // Markdown
      markdownContent: '',
      markdownFileName: ''
    }
  },
  computed: {
    renderedMarkdown() {
      if (!this.markdownContent) return ''
      return marked(this.markdownContent)
    }
  },
  methods: {
    // PDF methods
    async handlePdfChange(file) {
      if (!file.raw) return
      
      const arrayBuffer = await file.raw.arrayBuffer()
      this.pdfUrl = URL.createObjectURL(file.raw)
      
      // Load PDF using pdf.js (would need to be imported)
      this.$message.info('PDF预览需要pdf.js库支持，当前为演示模式')
      this.pdfTotalPages = 1
      this.pdfPage = 1
    },
    prevPdfPage() {
      if (this.pdfPage > 1) {
        this.pdfPage--
      }
    },
    nextPdfPage() {
      if (this.pdfPage < this.pdfTotalPages) {
        this.pdfPage++
      }
    },
    downloadPdf() {
      if (this.pdfUrl) {
        const link = document.createElement('a')
        link.href = this.pdfUrl
        link.download = 'document.pdf'
        link.click()
      }
    },
    
    // Excel methods
    handleExcelChange(file) {
      if (!file.raw) return
      
      this.excelFileName = file.name
      const reader = new FileReader()
      
      reader.onload = (e) => {
        try {
          const data = new Uint8Array(e.target.result)
          const workbook = XLSX.read(data, { type: 'array' })
          const firstSheet = workbook.Sheets[workbook.SheetNames[0]]
          const jsonData = XLSX.utils.sheet_to_json(firstSheet, { header: 1 })
          
          if (jsonData.length > 0) {
            this.excelHeaders = jsonData[0].map((h, i) => h || `Column${i + 1}`)
            this.excelData = jsonData.slice(1).map(row => {
              const obj = {}
              this.excelHeaders.forEach((header, index) => {
                obj[header] = row[index] || ''
              })
              return obj
            })
          }
        } catch (error) {
          this.$message.error('解析文件失败: ' + error.message)
        }
      }
      
      reader.readAsArrayBuffer(file.raw)
    },
    downloadExcel() {
      if (this.excelData.length === 0) return
      
      const csv = [
        this.excelHeaders.join(','),
        ...this.excelData.map(row => 
          this.excelHeaders.map(h => {
            const val = row[h]
            // Escape quotes and wrap in quotes if contains comma
            if (typeof val === 'string' && (val.includes(',') || val.includes('"'))) {
              return `"${val.replace(/"/g, '""')}"`
            }
            return val
          }).join(',')
        )
      ].join('\n')
      
      const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' })
      const link = document.createElement('a')
      link.href = URL.createObjectURL(blob)
      link.download = 'export.csv'
      link.click()
    },
    
    // Text methods
    handleTextChange(file) {
      if (!file.raw) return
      
      this.textFileName = file.name
      this.textFileSize = file.size
      
      const reader = new FileReader()
      reader.onload = (e) => {
        this.textContent = e.target.result
      }
      reader.readAsText(file.raw)
    },
    copyTextContent() {
      navigator.clipboard.writeText(this.textContent).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    downloadText() {
      const blob = new Blob([this.textContent], { type: 'text/plain' })
      const link = document.createElement('a')
      link.href = URL.createObjectURL(blob)
      link.download = this.textFileName
      link.click()
    },
    
    // Markdown methods
    handleMarkdownChange(file) {
      if (!file.raw) return
      
      this.markdownFileName = file.name
      
      const reader = new FileReader()
      reader.onload = (e) => {
        this.markdownContent = e.target.result
      }
      reader.readAsText(file.raw)
    },
    downloadMarkdown() {
      const blob = new Blob([this.markdownContent], { type: 'text/markdown' })
      const link = document.createElement('a')
      link.href = URL.createObjectURL(blob)
      link.download = this.markdownFileName
      link.click()
    },
    
    formatFileSize(bytes) {
      if (bytes === 0) return '0 B'
      const k = 1024
      const sizes = ['B', 'KB', 'MB']
      const i = Math.floor(Math.log(bytes) / Math.log(k))
      return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
    }
  }
}
</script>

<style scoped>
.file-preview-tool {
  padding: 20px;
}

.upload-area {
  text-align: center;
  margin-bottom: 20px;
}

.preview-container {
  margin-top: 20px;
}

.preview-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 15px;
  padding: 10px;
  background: #f5f7fa;
  border-radius: 4px;
}

.file-info {
  color: #606266;
  font-size: 14px;
}

.pdf-viewer {
  border: 1px solid #dcdfe6;
  border-radius: 4px;
  overflow: auto;
  max-height: 600px;
  text-align: center;
  padding: 20px;
}

.text-preview {
  background: #f5f7fa;
  padding: 20px;
  border-radius: 4px;
  max-height: 500px;
  overflow: auto;
  font-family: 'Courier New', monospace;
  font-size: 14px;
  line-height: 1.6;
  white-space: pre-wrap;
  word-wrap: break-word;
}

.markdown-preview {
  border: 1px solid #dcdfe6;
  border-radius: 4px;
  padding: 20px;
  max-height: 500px;
  overflow: auto;
  background: #fff;
}

.markdown-preview :deep(h1),
.markdown-preview :deep(h2),
.markdown-preview :deep(h3),
.markdown-preview :deep(h4),
.markdown-preview :deep(h5),
.markdown-preview :deep(h6) {
  margin-top: 0;
  margin-bottom: 16px;
  font-weight: 600;
  line-height: 1.25;
}

.markdown-preview :deep(p) {
  margin-bottom: 16px;
}

.markdown-preview :deep(code) {
  background: #f5f7fa;
  padding: 2px 6px;
  border-radius: 3px;
  font-family: monospace;
}

.markdown-preview :deep(pre) {
  background: #f5f7fa;
  padding: 16px;
  border-radius: 4px;
  overflow: auto;
}

.markdown-preview :deep(pre code) {
  background: none;
  padding: 0;
}

.markdown-preview :deep(table) {
  border-collapse: collapse;
  width: 100%;
  margin-bottom: 16px;
}

.markdown-preview :deep(th),
.markdown-preview :deep(td) {
  border: 1px solid #dcdfe6;
  padding: 8px 12px;
}

.markdown-preview :deep(th) {
  background: #f5f7fa;
}

.markdown-preview :deep(ul),
.markdown-preview :deep(ol) {
  margin-bottom: 16px;
  padding-left: 2em;
}

.markdown-preview :deep(blockquote) {
  border-left: 4px solid #409eff;
  padding-left: 16px;
  margin-left: 0;
  color: #606266;
}
</style>
