<template>
  <div class="json-diff-tool">
    <el-card>
      <div slot="header">
        <span>JSON 对比工具</span>
        <el-button size="small" @click="clearCurrent">清空当前</el-button>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ getTabTitle(tab) }}
          </span>

          <el-row :gutter="20">
            <el-col :span="11">
              <div class="section-header">
                <span>JSON A</span>
                <el-button type="text" @click="formatJsonA(tab)">格式化</el-button>
              </div>
              <el-input
                v-model="tab.jsonA"
                type="textarea"
                :rows="15"
                placeholder="输入第一个 JSON..."
              />
            </el-col>

            <el-col :span="2" class="compare-buttons">
              <el-button type="primary" @click="compare(tab)">对比</el-button>
              <el-button @click="swap(tab)">交换</el-button>
              <el-button @click="clear(tab)">清空</el-button>
            </el-col>

            <el-col :span="11">
              <div class="section-header">
                <span>JSON B</span>
                <el-button type="text" @click="formatJsonB(tab)">格式化</el-button>
              </div>
              <el-input
                v-model="tab.jsonB"
                type="textarea"
                :rows="15"
                placeholder="输入第二个 JSON..."
              />
            </el-col>
          </el-row>

          <el-divider>对比结果</el-divider>

          <el-tabs v-model="tab.resultTab">
            <el-tab-pane label="差异列表" name="list">
              <el-table :data="tab.differences" border size="small" v-if="tab.differences.length > 0">
                <el-table-column prop="path" label="路径" width="300" />
                <el-table-column prop="type" label="类型" width="100">
                  <template slot-scope="scope">
                    <el-tag :type="getDiffTypeTag(scope.row.type)">{{ scope.row.type }}</el-tag>
                  </template>
                </el-table-column>
                <el-table-column prop="oldValue" label="旧值">
                  <template slot-scope="scope">
                    <div class="value-cell old">{{ formatValue(scope.row.oldValue) }}</div>
                  </template>
                </el-table-column>
                <el-table-column prop="newValue" label="新值">
                  <template slot-scope="scope">
                    <div class="value-cell new">{{ formatValue(scope.row.newValue) }}</div>
                  </template>
                </el-table-column>
              </el-table>
              <el-empty v-else description="没有发现差异" />
            </el-tab-pane>

            <el-tab-pane label="并排对比" name="side">
              <el-row :gutter="10">
                <el-col :span="12">
                  <div class="side-panel">
                    <div class="panel-header">JSON A</div>
                    <pre class="json-content" v-html="tab.highlightedA"></pre>
                  </div>
                </el-col>
                <el-col :span="12">
                  <div class="side-panel">
                    <div class="panel-header">JSON B</div>
                    <pre class="json-content" v-html="tab.highlightedB"></pre>
                  </div>
                </el-col>
              </el-row>
            </el-tab-pane>

            <el-tab-pane label="统计" name="stats">
              <el-row :gutter="20">
                <el-col :span="6">
                  <el-statistic title="总差异" :value="tab.stats.total" />
                </el-col>
                <el-col :span="6">
                  <el-statistic title="新增" :value="tab.stats.added">
                    <template slot="suffix">
                      <span style="color: #67c23a">项</span>
                    </template>
                  </el-statistic>
                </el-col>
                <el-col :span="6">
                  <el-statistic title="删除" :value="tab.stats.removed">
                    <template slot="suffix">
                      <span style="color: #f56c6c">项</span>
                    </template>
                  </el-statistic>
                </el-col>
                <el-col :span="6">
                  <el-statistic title="修改" :value="tab.stats.modified">
                    <template slot="suffix">
                      <span style="color: #e6a23c">项</span>
                    </template>
                  </el-statistic>
                </el-col>
              </el-row>
            </el-tab-pane>
          </el-tabs>

          <el-divider>示例</el-divider>
          <el-button @click="loadExample(tab)">加载示例</el-button>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'JsonDiffTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: 'Diff ' + seq,
        jsonA: '',
        jsonB: '',
        differences: [],
        resultTab: 'list',
        highlightedA: '',
        highlightedB: '',
        stats: { total: 0, added: 0, removed: 0, modified: 0 }  // 缓存统计，避免重复计算
      }
    },
    getTabTitle(tab) {
      const content = tab.jsonA || ''
      const preview = content.trim().split('\n')[0].slice(0, 15)
      return preview ? `${tab.title}: ${preview}...` : tab.title
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clear(this.currentTab())
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },
    clearCurrent() {
      this.clear(this.currentTab())
    },
    compare(tab) {
      if (!tab.jsonA || !tab.jsonB) {
        this.$message.warning('请输入两个 JSON 进行对比')
        return
      }

      try {
        const objA = JSON.parse(tab.jsonA)
        const objB = JSON.parse(tab.jsonB)

        tab.differences = []
        this.findDifferences(tab, objA, objB, '')

        // 计算统计并缓存，避免模板多次遍历
        tab.stats = {
          total: tab.differences.length,
          added: tab.differences.filter(d => d.type === '新增').length,
          removed: tab.differences.filter(d => d.type === '删除').length,
          modified: tab.differences.filter(d => d.type === '修改').length
        }

        tab.highlightedA = this.highlightJson(tab, tab.jsonA, 'old')
        tab.highlightedB = this.highlightJson(tab, tab.jsonB, 'new')

        this.$message.success(`对比完成，发现 ${tab.differences.length} 处差异`)
      } catch (e) {
        this.$message.error('JSON 解析错误: ' + e.message)
      }
    },
    findDifferences(tab, objA, objB, path) {
      if (typeof objA !== typeof objB) {
        tab.differences.push({
          path: path || '根',
          type: '修改',
          oldValue: objA,
          newValue: objB
        })
        return
      }

      if (objA === null || objB === null) {
        if (objA !== objB) {
          tab.differences.push({
            path: path || '根',
            type: '修改',
            oldValue: objA,
            newValue: objB
          })
        }
        return
      }

      if (Array.isArray(objA) && Array.isArray(objB)) {
        const maxLen = Math.max(objA.length, objB.length)
        for (let i = 0; i < maxLen; i++) {
          const newPath = `${path}[${i}]`
          if (i >= objA.length) {
            tab.differences.push({
              path: newPath,
              type: '新增',
              oldValue: undefined,
              newValue: objB[i]
            })
          } else if (i >= objB.length) {
            tab.differences.push({
              path: newPath,
              type: '删除',
              oldValue: objA[i],
              newValue: undefined
            })
          } else {
            this.findDifferences(tab, objA[i], objB[i], newPath)
          }
        }
        return
      }

      if (typeof objA === 'object' && typeof objB === 'object') {
        const keysA = Object.keys(objA)
        const keysB = Object.keys(objB)
        const allKeys = new Set([...keysA, ...keysB])

        for (const key of allKeys) {
          const newPath = path ? `${path}.${key}` : key
          if (!keysA.includes(key)) {
            tab.differences.push({
              path: newPath,
              type: '新增',
              oldValue: undefined,
              newValue: objB[key]
            })
          } else if (!keysB.includes(key)) {
            tab.differences.push({
              path: newPath,
              type: '删除',
              oldValue: objA[key],
              newValue: undefined
            })
          } else {
            this.findDifferences(tab, objA[key], objB[key], newPath)
          }
        }
        return
      }

      if (objA !== objB) {
        tab.differences.push({
          path: path || '根',
          type: '修改',
          oldValue: objA,
          newValue: objB
        })
      }
    },
    formatValue(value) {
      if (value === undefined) return '(不存在)'
      if (value === null) return 'null'
      if (typeof value === 'object') return JSON.stringify(value)
      return String(value)
    },
    getDiffTypeTag(type) {
      const map = {
        '新增': 'success',
        '删除': 'danger',
        '修改': 'warning'
      }
      return map[type] || 'info'
    },
    highlightJson(tab, jsonStr, type) {
      const MAX_HIGHLIGHT_LENGTH = 10000  // 限制高亮长度，避免大 JSON 卡顿
      try {
        const json = JSON.parse(jsonStr)
        let formatted = JSON.stringify(json, null, 2)

        // 大 JSON 截断提示
        if (formatted.length > MAX_HIGHLIGHT_LENGTH) {
          return formatted.substring(0, MAX_HIGHLIGHT_LENGTH) + '\n\n... (已截断，完整内容请查看差异列表)'
        }

        // 只高亮前 50 个差异，避免正则替换过多卡顿
        const diffsToHighlight = tab.differences.slice(0, 50)
        for (const diff of diffsToHighlight) {
          const value = type === 'old' ? diff.oldValue : diff.newValue
          const valueStr = this.formatValue(value)
          if (valueStr.length > 100) continue  // 跳过过长的值
          if (formatted.includes(valueStr)) {
            const color = diff.type === '新增' ? '#f0f9eb' :
                         diff.type === '删除' ? '#fef0f0' : '#fdf6ec'
            // 只替换第一个匹配，避免全局替换性能差
            formatted = formatted.replace(
              this.escapeRegex(valueStr),
              `<span style="background: ${color}; padding: 2px 4px; border-radius: 3px;">${valueStr}</span>`
            )
          }
        }

        // 语法高亮
        formatted = formatted
          .replace(/"([^"]+)":/g, '<span style="color: #c678dd;">"$1"</span>:')
          .replace(/: "([^"]+)"/g, ': <span style="color: #98c379;">"$1"</span>')
          .replace(/: (\d+)/g, ': <span style="color: #d19a66;">$1</span>')
          .replace(/: (true|false)/g, ': <span style="color: #56b6c2;">$1</span>')
          .replace(/: (null)/g, ': <span style="color: #e06c75;">$1</span>')

        return formatted
      } catch (e) {
        return jsonStr
      }
    },
    escapeRegex(str) {
      return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    },
    formatJsonA(tab) {
      try {
        tab.jsonA = JSON.stringify(JSON.parse(tab.jsonA), null, 2)
      } catch (e) {
        this.$message.error('JSON 格式错误')
      }
    },
    formatJsonB(tab) {
      try {
        tab.jsonB = JSON.stringify(JSON.parse(tab.jsonB), null, 2)
      } catch (e) {
        this.$message.error('JSON 格式错误')
      }
    },
    swap(tab) {
      const temp = tab.jsonA
      tab.jsonA = tab.jsonB
      tab.jsonB = temp
    },
    clear(tab) {
      if (!tab) return
      tab.jsonA = ''
      tab.jsonB = ''
      tab.differences = []
      tab.highlightedA = ''
      tab.highlightedB = ''
    },
    loadExample(tab) {
      tab.jsonA = JSON.stringify({
        name: 'John',
        age: 30,
        email: 'john@example.com',
        address: {
          city: 'New York',
          country: 'USA'
        },
        hobbies: ['reading', 'swimming']
      }, null, 2)

      tab.jsonB = JSON.stringify({
        name: 'John',
        age: 31,
        email: 'john.doe@example.com',
        address: {
          city: 'Los Angeles',
          country: 'USA',
          zip: '90001'
        },
        hobbies: ['reading', 'gaming', 'coding']
      }, null, 2)
    }
  }
}
</script>

