<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>JSON 格式化</span>
        <el-button size="small" @click="clear">清空当前</el-button>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ tab.title }}
          </span>

          <el-row :gutter="20">
            <el-col :span="24">
              <div class="input-section">
                <div class="section-header">
                  <span>JSON 内容</span>
                  <el-tag size="mini" type="info">输入或粘贴 JSON，点击按钮格式化</el-tag>
                </div>
                <el-input
                  v-model="tab.jsonText"
                  type="textarea"
                  :rows="15"
                  placeholder='输入 JSON，如: {"name": "张三", "age": 25}'
                />
              </div>
            </el-col>
          </el-row>

          <el-row style="margin-top: 15px">
            <el-col :span="24" class="action-row">
              <el-radio-group v-model="tab.indent" size="small">
                <el-radio-button :label="2">2空格</el-radio-button>
                <el-radio-button :label="4">4空格</el-radio-button>
                <el-radio-button :label="1">Tab</el-radio-button>
              </el-radio-group>

              <div class="action-buttons">
                <el-button type="primary" @click="format(tab)">格式化</el-button>
                <el-button type="warning" @click="compress(tab)">压缩</el-button>
                <el-button type="success" @click="sortKeys(tab)">排序键名</el-button>
                <el-button type="info" @click="validate(tab)">验证</el-button>
                <el-button @click="copy(tab)">复制</el-button>
              </div>
            </el-col>
          </el-row>

          <el-row style="margin-top: 15px" v-if="tab.error">
            <el-col :span="24">
              <el-alert type="error" :closable="false" show-icon>
                <template slot="title">{{ tab.error }}</template>
              </el-alert>
            </el-col>
          </el-row>

          <el-row style="margin-top: 15px" v-if="tab.stats">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">JSON 统计</div>
                <el-descriptions :column="4" border size="small">
                  <el-descriptions-item label="对象数">{{ tab.stats.objects }}</el-descriptions-item>
                  <el-descriptions-item label="数组数">{{ tab.stats.arrays }}</el-descriptions-item>
                  <el-descriptions-item label="键数量">{{ tab.stats.keys }}</el-descriptions-item>
                  <el-descriptions-item label="字符数">{{ tab.stats.chars }}</el-descriptions-item>
                </el-descriptions>
              </el-card>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'JsonTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: 'JSON ' + seq,
        jsonText: '',
        indent: 2,
        error: '',
        stats: null
      }
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clear()
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },
    format(tab) {
      if (!tab.jsonText.trim()) {
        this.$message.warning('请输入 JSON 内容')
        return
      }

      try {
        const obj = JSON.parse(tab.jsonText)
        tab.jsonText = JSON.stringify(obj, null, tab.indent)
        tab.error = ''
        this.updateStats(tab, obj)
        this.$message.success('格式化成功')
      } catch (e) {
        tab.error = 'JSON 格式错误: ' + e.message
        tab.stats = null
      }
    },
    compress(tab) {
      if (!tab.jsonText.trim()) {
        this.$message.warning('请输入 JSON 内容')
        return
      }

      try {
        const obj = JSON.parse(tab.jsonText)
        tab.jsonText = JSON.stringify(obj)
        tab.error = ''
        this.updateStats(tab, obj)
        this.$message.success('压缩成功')
      } catch (e) {
        tab.error = 'JSON 格式错误: ' + e.message
        tab.stats = null
      }
    },
    sortKeys(tab) {
      if (!tab.jsonText.trim()) {
        this.$message.warning('请输入 JSON 内容')
        return
      }

      try {
        const obj = JSON.parse(tab.jsonText)
        const sorted = this.sortObjectKeys(obj)
        tab.jsonText = JSON.stringify(sorted, null, tab.indent)
        tab.error = ''
        this.updateStats(tab, sorted)
        this.$message.success('排序成功')
      } catch (e) {
        tab.error = 'JSON 格式错误: ' + e.message
        tab.stats = null
      }
    },
    sortObjectKeys(obj) {
      if (typeof obj !== 'object' || obj === null) {
        return obj
      }

      if (Array.isArray(obj)) {
        return obj.map(item => this.sortObjectKeys(item))
      }

      const sorted = {}
      Object.keys(obj).sort().forEach(key => {
        sorted[key] = this.sortObjectKeys(obj[key])
      })
      return sorted
    },
    validate(tab) {
      if (!tab.jsonText.trim()) {
        this.$message.warning('请输入 JSON 内容')
        return
      }

      try {
        JSON.parse(tab.jsonText)
        tab.error = ''
        this.$message.success('JSON 格式正确')
      } catch (e) {
        tab.error = 'JSON 格式错误: ' + e.message
      }
    },
    updateStats(tab, obj) {
      let objects = 0
      let arrays = 0
      let keys = 0

      const count = (o) => {
        if (typeof o !== 'object' || o === null) return

        if (Array.isArray(o)) {
          arrays++
          o.forEach(item => count(item))
        } else {
          objects++
          keys += Object.keys(o).length
          Object.values(o).forEach(v => count(v))
        }
      }

      count(obj)

      tab.stats = {
        objects,
        arrays,
        keys,
        chars: tab.jsonText.length
      }
    },
    copy(tab) {
      if (!tab.jsonText) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(tab.jsonText).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    clear() {
      const tab = this.currentTab()
      if (!tab) return
      tab.jsonText = ''
      tab.error = ''
      tab.stats = null
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .input-section {
    .section-header {
      display: flex;
      align-items: center;
      margin-bottom: 10px;
