<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>文本编辑器</span>
        <div class="header-actions">
          <el-dropdown trigger="click" size="small" style="margin-right: 10px">
            <el-button size="small">
              标签操作<i class="el-icon-arrow-down el-icon--right"></i>
            </el-button>
            <el-dropdown-menu slot="dropdown">
              <el-dropdown-item @click.native="closeOtherTabs">关闭其他</el-dropdown-item>
              <el-dropdown-item @click.native="closeAllTabs">关闭全部</el-dropdown-item>
              <el-dropdown-item divided @click.native="closeLeftTabs">关闭左侧</el-dropdown-item>
              <el-dropdown-item @click.native="closeRightTabs">关闭右侧</el-dropdown-item>
            </el-dropdown-menu>
          </el-dropdown>
          <el-button-group>
            <el-button size="small" @click="clearAll">清空</el-button>
            <el-button size="small" type="primary" @click="downloadText">下载</el-button>
            <el-button size="small" @click="copyText">复制</el-button>
          </el-button-group>
        </div>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ getTabTitle(tab) }}
          </span>

          <el-row :gutter="20">
            <el-col :span="24">
              <div class="editor-section">
                <div class="section-header">
                  <span>编辑区</span>
                  <div class="editor-info">
                    <el-tag size="mini" type="info">{{ charCount(tab) }} 字符</el-tag>
                    <el-tag size="mini" type="info">{{ lineCount(tab) }} 行</el-tag>
                    <el-tag size="mini" type="info">{{ wordCount(tab) }} 词</el-tag>
                  </div>
                </div>
                <el-input
                  v-model="tab.textContent"
                  type="textarea"
                  :ref="'text-' + tab.id"
                  :rows="20"
                  placeholder="在此输入或粘贴文本..."
                  class="text-editor"
                />
              </div>
            </el-col>
          </el-row>

          <el-row style="margin-top: 20px">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">文本处理工具</div>
                <div class="text-tools">
                  <el-button-group>
                    <el-button size="small" @click="toUpperCase(tab)">转大写</el-button>
                    <el-button size="small" @click="toLowerCase(tab)">转小写</el-button>
                    <el-button size="small" @click="toTitleCase(tab)">首字母大写</el-button>
                  </el-button-group>
                  <el-button-group>
                    <el-button size="small" @click="removeExtraSpaces(tab)">去多余空格</el-button>
                    <el-button size="small" @click="removeEmptyLines(tab)">去空行</el-button>
                    <el-button size="small" @click="trimLines(tab)">行首尾去空</el-button>
                  </el-button-group>
                  <el-button-group>
                    <el-button size="small" @click="sortLines(tab)">行排序</el-button>
                    <el-button size="small" @click="reverseLines(tab)">行反转</el-button>
                    <el-button size="small" @click="uniqueLines(tab)">去重行</el-button>
                  </el-button-group>
                  <el-button-group>
                    <el-button size="small" @click="addLineNumbers(tab)">加行号</el-button>
                    <el-button size="small" @click="removeLineNumbers(tab)">去行号</el-button>
                  </el-button-group>
                  <el-button-group>
                    <el-button size="small" @click="base64Encode(tab)">Base64编码</el-button>
                    <el-button size="small" @click="base64Decode(tab)">Base64解码</el-button>
                  </el-button-group>
                  <el-button-group>
                    <el-button size="small" @click="urlEncode(tab)">URL编码</el-button>
                    <el-button size="small" @click="urlDecode(tab)">URL解码</el-button>
                  </el-button-group>
                </div>
              </el-card>
            </el-col>
          </el-row>

          <el-row style="margin-top: 20px">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">查找替换</div>
                <el-row :gutter="10">
                  <el-col :span="8">
                    <el-input v-model="tab.findText" placeholder="查找内容" size="small">
                      <template slot="prepend">查找</template>
                    </el-input>
                  </el-col>
                  <el-col :span="8">
                    <el-input v-model="tab.replaceText" placeholder="替换为" size="small">
                      <template slot="prepend">替换</template>
                    </el-input>
                  </el-col>
                  <el-col :span="8">
                    <el-button-group>
                      <el-button size="small" type="primary" @click="replaceAll(tab)">全部替换</el-button>
                      <el-button size="small" @click="findNext(tab)">查找下一个</el-button>
                    </el-button-group>
                  </el-col>
                </el-row>
                <el-row style="margin-top: 10px">
                  <el-col :span="24">
                    <el-checkbox v-model="tab.caseSensitive">区分大小写</el-checkbox>
                    <el-checkbox v-model="tab.useRegex">使用正则表达式</el-checkbox>
                  </el-col>
                </el-row>
              </el-card>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'TextEditorTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: 'Text ' + seq,
        textContent: '',
        findText: '',
        replaceText: '',
        caseSensitive: false,
        useRegex: false,
        lastFindIndex: -1
      }
    },
    getTabTitle(tab) {
      const content = tab.textContent || ''
      const preview = content.trim().split('\n')[0].slice(0, 15)
      return preview ? `${tab.title}: ${preview}...` : tab.title
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clearAll()
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },

    // 统计（按标签计算）
    charCount(tab) {
      return tab.textContent.length
    },
    lineCount(tab) {
      return tab.textContent ? tab.textContent.split('\n').length : 0
    },
    wordCount(tab) {
      return tab.textContent ? tab.textContent.trim().split(/\s+/).filter(w => w).length : 0
    },

    // 大小写转换
    toUpperCase(tab) {
      tab.textContent = tab.textContent.toUpperCase()
      this.$message.success('已转换为大写')
    },
    toLowerCase(tab) {
      tab.textContent = tab.textContent.toLowerCase()
      this.$message.success('已转换为小写')
    },
    toTitleCase(tab) {
      tab.textContent = tab.textContent.replace(/\w\S*/g, txt =>
        txt.charAt(0).toUpperCase() + txt.substr(1).toLowerCase()
      )
      this.$message.success('已转换为标题格式')
    },

    // 空格和空行处理
    removeExtraSpaces(tab) {
      tab.textContent = tab.textContent.replace(/\s+/g, ' ')
      this.$message.success('已去除多余空格')
    },
    removeEmptyLines(tab) {
      tab.textContent = tab.textContent.split('\n').filter(line => line.trim()).join('\n')
      this.$message.success('已去除空行')
    },
    trimLines(tab) {
      tab.textContent = tab.textContent.split('\n').map(line => line.trim()).join('\n')
      this.$message.success('已去除行首尾空格')
    },

    // 行操作
    sortLines(tab) {
      tab.textContent = tab.textContent.split('\n').sort().join('\n')
      this.$message.success('已排序')
    },
    reverseLines(tab) {
      tab.textContent = tab.textContent.split('\n').reverse().join('\n')
      this.$message.success('已反转')
    },
    uniqueLines(tab) {
      const lines = tab.textContent.split('\n')
      tab.textContent = [...new Set(lines)].join('\n')
      this.$message.success('已去重')
    },

    // 行号
    addLineNumbers(tab) {
      const lines = tab.textContent.split('\n')
      const maxDigits = String(lines.length).length
      tab.textContent = lines.map((line, index) => {
        const num = String(index + 1).padStart(maxDigits, '0')
        return `${num}. ${line}`
      }).join('\n')
      this.$message.success('已添加行号')
    },
    removeLineNumbers(tab) {
      tab.textContent = tab.textContent.split('\n').map(line =>
        line.replace(/^\s*\d+[\.\)]\s*/, '')
      ).join('\n')
      this.$message.success('已移除行号')
    },

    // 编码解码
    base64Encode(tab) {
      try {
        tab.textContent = btoa(unescape(encodeURIComponent(tab.textContent)))
        this.$message.success('Base64 编码成功')
      } catch (e) {
        this.$message.error('编码失败: ' + e.message)
      }
    },
    base64Decode(tab) {
      try {
        tab.textContent = decodeURIComponent(escape(atob(tab.textContent)))
        this.$message.success('Base64 解码成功')
      } catch (e) {
        this.$message.error('解码失败: 无效的 Base64')
      }
    },
    urlEncode(tab) {
      try {
        tab.textContent = encodeURIComponent(tab.textContent)
        this.$message.success('URL 编码成功')
      } catch (e) {
        this.$message.error('编码失败: ' + e.message)
      }
    },
    urlDecode(tab) {
      try {
        tab.textContent = decodeURIComponent(tab.textContent)
        this.$message.success('URL 解码成功')
      } catch (e) {
        this.$message.error('解码失败: 无效的 URL 编码')
      }
    },

    // 查找替换
    replaceAll(tab) {
      if (!tab.findText) {
        this.$message.warning('请输入查找内容')
        return
      }
      try {
        let regex
        const flags = 'g' + (tab.caseSensitive ? '' : 'i')
        if (tab.useRegex) {
          regex = new RegExp(tab.findText, flags)
        } else {
          regex = new RegExp(this.escapeRegex(tab.findText), flags)
        }
        const count = (tab.textContent.match(regex) || []).length
        tab.textContent = tab.textContent.replace(regex, tab.replaceText)
        this.$message.success(`已替换 ${count} 处`)
      } catch (e) {
        this.$message.error('替换失败: ' + e.message)
      }
    },
    findNext(tab) {
      if (!tab.findText) {
        this.$message.warning('请输入查找内容')
        return
      }
      try {
        let regex
        const flags = tab.caseSensitive ? '' : 'i'
        if (tab.useRegex) {
          regex = new RegExp(tab.findText, flags)
        } else {
          regex = new RegExp(this.escapeRegex(tab.findText), flags)
        }

        // 用 ref 精确获取当前标签的 textarea
        const inputComp = this.$refs['text-' + tab.id]
        if (!inputComp || !inputComp[0]) return
        const textarea = inputComp[0].$el.querySelector('textarea')
        const content = tab.textContent

        // 从当前位置开始查找
        const startPos = tab.lastFindIndex >= 0 ? tab.lastFindIndex + 1 : 0
        const match = content.slice(startPos).match(regex)

        if (match) {
          const matchIndex = content.indexOf(match[0], startPos)
          tab.lastFindIndex = matchIndex

          // 选中匹配的文本
          if (textarea) {
            textarea.setSelectionRange(matchIndex, matchIndex + match[0].length)
            textarea.focus()
          }

          this.$message.success(`找到: "${match[0]}"`)
        } else {
          // 从头开始查找
          const firstMatch = content.match(regex)
          if (firstMatch) {
            tab.lastFindIndex = content.indexOf(firstMatch[0])
            if (textarea) {
              textarea.setSelectionRange(tab.lastFindIndex, tab.lastFindIndex + firstMatch[0].length)
              textarea.focus()
            }
            this.$message.success(`找到: "${firstMatch[0]}" (从头开始)`)
          } else {
            tab.lastFindIndex = -1
            this.$message.warning('未找到匹配内容')
          }
        }
      } catch (e) {
        this.$message.error('查找失败: ' + e.message)
      }
    },
    escapeRegex(string) {
      return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    },

    // 文件操作
    downloadText() {
      const tab = this.currentTab()
      if (!tab) return
      if (!tab.textContent) {
        this.$message.warning('没有可下载的内容')
        return
      }
      const blob = new Blob([tab.textContent], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = `text_${Date.now()}.txt`
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(url)
      this.$message.success('已下载文本文件')
    },
    copyText() {
      const tab = this.currentTab()
      if (!tab) return
      if (!tab.textContent) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(tab.textContent).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    clearAll() {
      const tab = this.currentTab()
      if (!tab) return
      tab.textContent = ''
      tab.findText = ''
      tab.replaceText = ''
      tab.lastFindIndex = -1
    },
    // 标签批量操作
    closeOtherTabs() {
      const current = this.currentTab()
      if (!current) return
      this.tabs = [current]
      this.$message.success('已关闭其他标签')
    },
    closeAllTabs() {
      this.tabs = [this.createTab(++this.tabCounter)]
      this.activeTab = this.tabs[0].id
      this.$message.success('已关闭全部标签并新建空白标签')
    },
    closeLeftTabs() {
      const index = this.tabs.findIndex(t => t.id === this.activeTab)
      if (index <= 0) {
        this.$message.info('当前标签左侧没有其他标签')
        return
      }
      this.tabs = this.tabs.slice(index)
      this.$message.success(`已关闭左侧 ${index} 个标签`)
    },
    closeRightTabs() {
      const index = this.tabs.findIndex(t => t.id === this.activeTab)
      if (index === -1 || index === this.tabs.length - 1) {
        this.$message.info('当前标签右侧没有其他标签')
        return
      }
      const removed = this.tabs.length - index - 1
      this.tabs = this.tabs.slice(0, index + 1)
      this.$message.success(`已关闭右侧 ${removed} 个标签`)
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .header-actions {
    float: right;
  }

  .editor-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;

      .editor-info {
        display: flex;
        gap: 10px;
      }
    }
  }

  .text-editor {
    font-family: 'Monaco', 'Menlo', 'Consolas', monospace;
  }

  .text-tools {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;

    .el-button-group {
      margin-right: 10px;
    }
  }
}
</style>
