<template>
  <div class="image-compress-tool">
    <el-card>
      <div slot="header">
        <span>图片压缩工具</span>
        <el-button-group style="float: right;">
          <el-button size="small" @click="clearAll">清空</el-button>
        </el-button-group>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <div class="upload-area" @click="triggerUpload" @drop.prevent="handleDrop" @dragover.prevent>
            <input type="file" ref="fileInput" @change="handleFileSelect" accept="image/*" style="display: none" />
            <div v-if="!originalImage" class="upload-placeholder">
              <i class="el-icon-upload" style="font-size: 48px; color: #909399"></i>
              <p>点击或拖拽图片到此处</p>
              <p style="color: #909399; font-size: 12px">支持 JPG、PNG、GIF、WebP 格式</p>
            </div>
            <img v-else :src="originalImage" class="preview-image" />
          </div>
          <div v-if="originalInfo" class="image-info">
            <el-tag size="small">原始大小: {{ originalInfo.size }}</el-tag>
            <el-tag size="small" style="margin-left: 10px">尺寸: {{ originalInfo.width }} x {{ originalInfo.height }}</el-tag>
            <el-tag size="small" style="margin-left: 10px">格式: {{ originalInfo.type }}</el-tag>
          </div>
        </el-col>

        <el-col :span="12">
          <div class="result-area">
            <div v-if="!compressedImage" class="result-placeholder">
              <i class="el-icon-picture-outline" style="font-size: 48px; color: #c0c4cc"></i>
              <p>压缩后的图片将显示在这里</p>
            </div>
            <img v-else :src="compressedImage" class="preview-image" />
          </div>
          <div v-if="compressedInfo" class="image-info">
            <el-tag size="small" type="success">压缩后大小: {{ compressedInfo.size }}</el-tag>
            <el-tag size="small" type="success" style="margin-left: 10px">压缩率: {{ compressedInfo.ratio }}%</el-tag>
          </div>
        </el-col>
      </el-row>

      <el-divider>压缩设置</el-divider>

      <el-form label-width="100px">
        <el-row :gutter="20">
          <el-col :span="8">
            <el-form-item label="输出格式">
              <el-select v-model="outputFormat" style="width: 100%">
                <el-option label="保持原格式" value="auto" />
                <el-option label="JPEG" value="image/jpeg" />
                <el-option label="PNG" value="image/png" />
                <el-option label="WebP" value="image/webp" />
              </el-select>
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="压缩质量">
              <el-slider v-model="quality" :min="0.1" :max="1" :step="0.1" show-input :format-tooltip="formatQuality" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="最大宽度">
              <el-input-number v-model="maxWidth" :min="0" :max="10000" placeholder="不限制" style="width: 100%" />
            </el-form-item>
          </el-col>
        </el-row>
        <el-row :gutter="20">
          <el-col :span="8">
            <el-form-item label="最大高度">
              <el-input-number v-model="maxHeight" :min="0" :max="10000" placeholder="不限制" style="width: 100%" />
            </el-form-item>
          </el-col>
          <el-col :span="16">
            <el-form-item>
              <el-button type="primary" @click="compress" :disabled="!originalImage" :loading="compressing">
                开始压缩
              </el-button>
              <el-button type="success" @click="download" :disabled="!compressedImage">
                下载图片
              </el-button>
            </el-form-item>
          </el-col>
        </el-row>
      </el-form>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'ImageCompressTool',
  data() {
    return {
      originalImage: '',
      compressedImage: '',
      originalInfo: null,
      compressedInfo: null,
      outputFormat: 'auto',
      quality: 0.8,
      maxWidth: 0,
      maxHeight: 0,
      compressing: false,
      originalFile: null
    }
  },
  methods: {
    triggerUpload() {
      this.$refs.fileInput.click()
    },
    handleFileSelect(e) {
      const file = e.target.files[0]
      if (file) {
        this.loadImage(file)
      }
    },
    handleDrop(e) {
      const file = e.dataTransfer.files[0]
      if (file && file.type.startsWith('image/')) {
        this.loadImage(file)
      }
    },
    loadImage(file) {
      this.originalFile = file
      const reader = new FileReader()
      reader.onload = (e) => {
        this.originalImage = e.target.result
        const img = new Image()
        img.onload = () => {
          this.originalInfo = {
            size: this.formatFileSize(file.size),
            width: img.width,
            height: img.height,
            type: file.type.split('/')[1].toUpperCase()
          }
        }
        img.src = e.target.result
      }
      reader.readAsDataURL(file)
    },
    async compress() {
      if (!this.originalImage) return
      
      this.compressing = true
      try {
        const img = new Image()
        img.src = this.originalImage
        
        await new Promise((resolve) => {
          img.onload = resolve
        })

        let width = img.width
        let height = img.height

        if (this.maxWidth > 0 && width > this.maxWidth) {
          height = (this.maxWidth / width) * height
          width = this.maxWidth
        }
        if (this.maxHeight > 0 && height > this.maxHeight) {
          width = (this.maxHeight / height) * width
          height = this.maxHeight
        }

        const canvas = document.createElement('canvas')
        canvas.width = width
        canvas.height = height
        const ctx = canvas.getContext('2d')
        ctx.drawImage(img, 0, 0, width, height)

        let mimeType = this.outputFormat === 'auto' ? this.originalFile.type : this.outputFormat
        if (mimeType === 'image/gif') {
          mimeType = 'image/png'
        }

        const compressedDataUrl = canvas.toDataURL(mimeType, this.quality)
        this.compressedImage = compressedDataUrl

        const compressedSize = Math.round((compressedDataUrl.length - `data:${mimeType};base64,`.length) * 0.75)
        const originalSize = this.originalFile.size
        const ratio = ((1 - compressedSize / originalSize) * 100).toFixed(1)

        this.compressedInfo = {
          size: this.formatFileSize(compressedSize),
          ratio: ratio > 0 ? ratio : 0
        }
      } catch (error) {
        this.$message.error('压缩失败: ' + error.message)
      } finally {
        this.compressing = false
      }
    },
    download() {
      if (!this.compressedImage) return
      
      const link = document.createElement('a')
      link.download = `compressed_${Date.now()}.${this.getFileExtension()}`
      link.href = this.compressedImage
      link.click()
    },
    getFileExtension() {
      if (this.outputFormat === 'auto') {
        return this.originalFile.type.split('/')[1] || 'png'
      }
      return this.outputFormat.split('/')[1]
    },
    formatFileSize(bytes) {
      if (bytes < 1024) return bytes + ' B'
      if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(2) + ' KB'
      return (bytes / (1024 * 1024)).toFixed(2) + ' MB'
    },
    formatQuality(val) {
      return Math.round(val * 100) + '%'
    },
    clearAll() {
      this.originalImage = ''
      this.compressedImage = ''
      this.originalInfo = null
      this.compressedInfo = null
      this.originalFile = null
      this.$refs.fileInput.value = ''
    }
  }
}
</script>

<style scoped>
.image-compress-tool {
  padding: 20px;
}

.upload-area,
.result-area {
  border: 2px dashed #dcdfe6;
  border-radius: 8px;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: border-color 0.3s;
  overflow: hidden;
}

.upload-area:hover {
  border-color: #409EFF;
}

.upload-placeholder,
.result-placeholder {
  text-align: center;
  color: #909399;
}

.preview-image {
  max-width: 100%;
  max-height: 300px;
  object-fit: contain;
}

.image-info {
  margin-top: 10px;
  text-align: center;
}
</style>
