<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>XML 格式化</span>
        <el-button size="small" @click="clear">清空当前</el-button>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ tab.title }}
          </span>

          <el-row :gutter="20">
            <el-col :span="24">
              <div class="input-section">
                <div class="section-header">
                  <span>XML 内容</span>
                  <el-tag size="mini" type="info">输入或粘贴 XML，点击按钮格式化</el-tag>
                </div>
                <el-input
                  v-model="tab.xmlText"
                  type="textarea"
                  :rows="15"
                  placeholder="输入 XML，如: <root><name>张三</name><age>25</age></root>"
                />
              </div>
            </el-col>
          </el-row>

          <el-row style="margin-top: 15px">
            <el-col :span="24" class="action-row">
              <el-radio-group v-model="tab.indent" size="small">
                <el-radio-button :label="2">2空格</el-radio-button>
                <el-radio-button :label="4">4空格</el-radio-button>
                <el-radio-button :label="1">Tab</el-radio-button>
              </el-radio-group>

              <div class="action-buttons">
                <el-button type="primary" @click="format(tab)">格式化</el-button>
                <el-button type="warning" @click="compress(tab)">压缩</el-button>
                <el-button type="info" @click="validate(tab)">验证</el-button>
                <el-button @click="copy(tab)">复制</el-button>
              </div>
            </el-col>
          </el-row>

          <el-row style="margin-top: 15px" v-if="tab.error">
            <el-col :span="24">
              <el-alert type="error" :closable="false" show-icon>
                <template slot="title">{{ tab.error }}</template>
              </el-alert>
            </el-col>
          </el-row>

          <el-row style="margin-top: 15px" v-if="tab.stats">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">XML 统计</div>
                <el-descriptions :column="4" border size="small">
                  <el-descriptions-item label="元素数">{{ tab.stats.elements }}</el-descriptions-item>
                  <el-descriptions-item label="属性数">{{ tab.stats.attributes }}</el-descriptions-item>
                  <el-descriptions-item label="文本节点">{{ tab.stats.textNodes }}</el-descriptions-item>
                  <el-descriptions-item label="字符数">{{ tab.stats.chars }}</el-descriptions-item>
                </el-descriptions>
              </el-card>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'XmlTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: 'XML ' + seq,
        xmlText: '',
        indent: 2,
        error: '',
        stats: null
      }
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clear()
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },
    format(tab) {
      if (!tab.xmlText.trim()) {
        this.$message.warning('请输入 XML 内容')
        return
      }

      try {
        tab.xmlText = this.formatXml(tab.xmlText, tab.indent)
        tab.error = ''
        this.updateStats(tab)
        this.$message.success('格式化成功')
      } catch (e) {
        tab.error = 'XML 格式错误: ' + e.message
        tab.stats = null
      }
    },
    formatXml(xml, indent) {
      const PADDING = indent === 1 ? '\t' : ' '.repeat(indent)
      let formatted = ''
      let pad = 0

      xml = xml.replace(/(>)(<)(\/*)/g, '$1\n$2$3')
      xml.split('\n').forEach((node) => {
        let indentDelta = 0
        if (node.match(/.+<\/\w[^>]*>$/)) {
          indentDelta = 0
        } else if (node.match(/^<\/\w/)) {
          if (pad !== 0) pad -= 1
        } else if (node.match(/^<\w([^>]*[^\/])?>.*$/)) {
          indentDelta = 1
        }

        formatted += PADDING.repeat(pad) + node + '\n'
        pad += indentDelta
      })

      return formatted.trim()
    },
    compress(tab) {
      if (!tab.xmlText.trim()) {
        this.$message.warning('请输入 XML 内容')
        return
      }

      try {
        tab.xmlText = tab.xmlText
          .replace(/\n/g, '')
          .replace(/\s{2,}/g, ' ')
          .replace(/>\s+</g, '><')
          .trim()
        tab.error = ''
        this.updateStats(tab)
        this.$message.success('压缩成功')
      } catch (e) {
        tab.error = '压缩失败: ' + e.message
      }
    },
    validate(tab) {
      if (!tab.xmlText.trim()) {
        this.$message.warning('请输入 XML 内容')
        return
      }

      try {
        const parser = new DOMParser()
        const doc = parser.parseFromString(tab.xmlText, 'text/xml')
        const errorNode = doc.querySelector('parsererror')

        if (errorNode) {
          tab.error = 'XML 格式错误: ' + errorNode.textContent
        } else {
          tab.error = ''
          this.$message.success('XML 格式正确')
        }
      } catch (e) {
        tab.error = 'XML 格式错误: ' + e.message
      }
    },
    updateStats(tab) {
      const parser = new DOMParser()
      const doc = parser.parseFromString(tab.xmlText, 'text/xml')

      const elements = doc.getElementsByTagName('*').length
      const textNodes = this.countTextNodes(doc.documentElement)

      let attributes = 0
      const allElements = doc.getElementsByTagName('*')
      for (let i = 0; i < allElements.length; i++) {
        attributes += allElements[i].attributes.length
      }

      tab.stats = {
        elements,
        attributes,
        textNodes,
        chars: tab.xmlText.length
      }
    },
    countTextNodes(node) {
      let count = 0
      if (node && node.childNodes) {
        for (let i = 0; i < node.childNodes.length; i++) {
          const child = node.childNodes[i]
          if (child.nodeType === 3 && child.textContent.trim()) {
            count++
          } else if (child.nodeType === 1) {
            count += this.countTextNodes(child)
          }
        }
      }
      return count
    },
    copy(tab) {
      if (!tab.xmlText) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(tab.xmlText).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    clear() {
      const tab = this.currentTab()
      if (!tab) return
      tab.xmlText = ''
      tab.error = ''
      tab.stats = null
    }
  }
}
</script>

