<template>
  <div class="csv-editor-tool">
    <el-card>
      <div slot="header">
        <span>CSV 编辑器</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
          <el-button size="small" @click="importCsv" type="primary">导入</el-button>
          <el-button size="small" @click="exportCsv" type="success">导出</el-button>
        </el-button-group>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ tab.title }}
          </span>

          <el-upload
            class="uploader"
            :auto-upload="false"
            :show-file-list="false"
            :on-change="(file) => handleFileChange(tab, file)"
            accept=".csv"
          >
            <el-button size="small" type="info">
              <i class="el-icon-upload2"></i> 选择 CSV 文件
            </el-button>
          </el-upload>

          <div class="editor-container">
            <el-table
              :data="tab.csvData"
              border
              style="width: 100%"
            >
              <el-table-column
                v-for="(header, index) in tab.headers"
                :key="index"
                :prop="`col${index}`"
                :label="header"
                min-width="120"
              >
                <template slot-scope="scope">
                  <el-input
                    v-model="scope.row[`col${index}`]"
                    size="small"
                    @change="updateCsv"
                  />
                </template>
              </el-table-column>
              <el-table-column label="操作" width="120">
                <template slot-scope="scope">
                  <el-button
                    size="mini"
                    type="danger"
                    @click="removeRow(tab, scope.$index)"
                  >
                    删除
                  </el-button>
                </template>
              </el-table-column>
            </el-table>

            <div class="table-actions">
              <el-button @click="addRow(tab)" type="primary" size="small">
                <i class="el-icon-plus"></i> 添加行
              </el-button>
              <el-button @click="addColumn(tab)" type="primary" size="small">
                <i class="el-icon-plus"></i> 添加列
              </el-button>
              <el-button @click="removeColumn(tab)" type="danger" size="small" :disabled="tab.headers.length <= 1">
                <i class="el-icon-minus"></i> 删除列
              </el-button>
            </div>
          </div>

          <div class="preview-container" style="margin-top: 20px">
            <el-card shadow="hover">
              <div slot="header">
                <span>CSV 预览</span>
                <el-button size="small" @click="copyCsv(tab)" type="primary">复制</el-button>
              </div>
              <el-input
                type="textarea"
                :rows="10"
                :value="csvContent(tab)"
                readonly
                class="code-area"
              />
            </el-card>
          </div>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CsvEditorTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: 'CSV ' + seq,
        headers: ['Name', 'Age', 'Email'],
        csvData: [
          { col0: 'John Doe', col1: '30', col2: 'john@example.com' },
          { col0: 'Jane Smith', col1: '25', col2: 'jane@example.com' },
          { col0: 'Bob Johnson', col1: '35', col2: 'bob@example.com' }
        ]
      }
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clearAll()
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },
    csvContent(tab) {
      // 生成 CSV 内容
      const headerRow = tab.headers.join(',')
      const dataRows = tab.csvData.map(row => {
        return tab.headers.map((_, index) => {
          const value = row[`col${index}`] || ''
          // 处理包含逗号或引号的值
          if (value.includes(',') || value.includes('"') || value.includes('\n')) {
            return `"${value.replace(/"/g, '""')}"`
          }
          return value
        }).join(',')
      })
      return [headerRow, ...dataRows].join('\n')
    },
    clearAll() {
      const tab = this.currentTab()
      if (!tab) return
      tab.headers = ['Column 1', 'Column 2']
      tab.csvData = [
        { col0: '', col1: '' },
        { col0: '', col1: '' }
      ]
    },
    addRow(tab) {
      const newRow = {}
      tab.headers.forEach((_, index) => {
        newRow[`col${index}`] = ''
      })
      tab.csvData.push(newRow)
    },
    removeRow(tab, index) {
      tab.csvData.splice(index, 1)
    },
    addColumn(tab) {
      const newColIndex = tab.headers.length
      tab.headers.push(`Column ${newColIndex + 1}`)
      tab.csvData.forEach(row => {
        this.$set(row, `col${newColIndex}`, '')
      })
    },
    removeColumn(tab) {
      if (tab.headers.length > 1) {
        const lastColIndex = tab.headers.length - 1
        tab.headers.pop()
        tab.csvData.forEach(row => {
          this.$delete(row, `col${lastColIndex}`)
        })
      }
    },
    updateCsv() {
      // 可以在这里添加额外的更新逻辑
    },
    handleFileChange(tab, file) {
      const reader = new FileReader()
      reader.onload = (e) => {
        this.parseCsv(tab, e.target.result)
      }
      reader.readAsText(file.raw)
    },
    parseCsv(tab, csvText) {
      const lines = csvText.split(/\r?\n/).filter(line => line.trim())
      if (lines.length === 0) return

      // 解析表头
      tab.headers = this.parseCsvLine(lines[0])

      // 解析数据
      const csvData = []
      for (let i = 1; i < lines.length; i++) {
        const values = this.parseCsvLine(lines[i])
        const row = {}
        tab.headers.forEach((_, index) => {
          row[`col${index}`] = values[index] || ''
        })
        csvData.push(row)
      }
      tab.csvData = csvData
    },
    parseCsvLine(line) {
      const result = []
      let current = ''
      let inQuotes = false
      let escapeNext = false

      for (let i = 0; i < line.length; i++) {
        const char = line[i]

        if (escapeNext) {
          current += char
          escapeNext = false
        } else if (char === '"') {
          inQuotes = !inQuotes
        } else if (char === ',' && !inQuotes) {
          result.push(current)
          current = ''
        } else if (char === '\\') {
          escapeNext = true
        } else {
          current += char
        }
      }

      result.push(current)
      return result
    },
    importCsv() {
      const tab = this.currentTab()
      if (!tab) return
      const input = document.createElement('input')
      input.type = 'file'
      input.accept = '.csv'
      input.onchange = (e) => {
        const file = e.target.files[0]
        if (file) {
          const reader = new FileReader()
          reader.onload = (e) => {
            this.parseCsv(tab, e.target.result)
          }
          reader.readAsText(file)
        }
      }
      input.click()
    },
    exportCsv() {
      const tab = this.currentTab()
      if (!tab) return
      const blob = new Blob([this.csvContent(tab)], { type: 'text/csv;charset=utf-8;' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.setAttribute('download', `data_${new Date().toISOString().slice(0, 10)}.csv`)
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
    },
    copyCsv(tab) {
      this.$copyText(this.csvContent(tab)).then(() => {
        this.$message.success('CSV 内容已复制到剪贴板')
      })
    }
  }
}
</script>

<style lang="scss" scoped>
