<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>文本统计</span>
        <el-button size="small" @click="clearAll">清空当前</el-button>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ tab.title }}
          </span>

          <el-row :gutter="20">
            <el-col :span="24">
              <div class="input-section">
                <div class="section-header">
                  <span>输入文本</span>
                  <el-tag size="mini" type="info">支持多行文本</el-tag>
                </div>
                <el-input
                  v-model="tab.textContent"
                  type="textarea"
                  :rows="10"
                  placeholder="在此输入或粘贴文本进行统计分析..."
                  @input="analyzeText(tab)"
                />
              </div>
            </el-col>
          </el-row>

          <el-row :gutter="20" style="margin-top: 20px">
            <el-col :span="12">
              <el-card shadow="never">
                <div slot="header">基本统计</div>
                <el-descriptions :column="2" border size="small">
                  <el-descriptions-item label="字符数">{{ tab.stats.chars }}</el-descriptions-item>
                  <el-descriptions-item label="字符数(不含空格)">{{ tab.stats.charsNoSpace }}</el-descriptions-item>
                  <el-descriptions-item label="中文字符">{{ tab.stats.chinese }}</el-descriptions-item>
                  <el-descriptions-item label="英文字符">{{ tab.stats.english }}</el-descriptions-item>
                  <el-descriptions-item label="数字">{{ tab.stats.numbers }}</el-descriptions-item>
                  <el-descriptions-item label="标点符号">{{ tab.stats.punctuation }}</el-descriptions-item>
                  <el-descriptions-item label="单词数">{{ tab.stats.words }}</el-descriptions-item>
                  <el-descriptions-item label="行数">{{ tab.stats.lines }}</el-descriptions-item>
                  <el-descriptions-item label="段落数">{{ tab.stats.paragraphs }}</el-descriptions-item>
                  <el-descriptions-item label="句子数">{{ tab.stats.sentences }}</el-descriptions-item>
                </el-descriptions>
              </el-card>
            </el-col>

            <el-col :span="12">
              <el-card shadow="never">
                <div slot="header">阅读时间估算</div>
                <el-descriptions :column="1" border size="small">
                  <el-descriptions-item label="中文阅读时间">{{ tab.stats.readTimeChinese }} 分钟</el-descriptions-item>
                  <el-descriptions-item label="英文阅读时间">{{ tab.stats.readTimeEnglish }} 分钟</el-descriptions-item>
                  <el-descriptions-item label="演讲时间">{{ tab.stats.speakTime }} 分钟</el-descriptions-item>
                  <el-descriptions-item label="A4纸页数">{{ tab.stats.a4Pages }} 页</el-descriptions-item>
                </el-descriptions>
              </el-card>
            </el-col>
          </el-row>

          <el-row :gutter="20" style="margin-top: 20px">
            <el-col :span="12">
              <el-card shadow="never">
                <div slot="header">
                  <span>字符频率 Top 20</span>
                  <el-radio-group v-model="tab.charFreqType" size="mini" style="float: right" @change="analyzeText(tab)">
                    <el-radio-button label="all">全部</el-radio-button>
                    <el-radio-button label="chinese">中文</el-radio-button>
                    <el-radio-button label="english">英文</el-radio-button>
                  </el-radio-group>
                </div>
                <el-table :data="tab.charFrequency" border size="small" max-height="300">
                  <el-table-column prop="char" label="字符" width="80" align="center">
                    <template slot-scope="scope">
                      <span class="freq-char">{{ scope.row.char }}</span>
                    </template>
                  </el-table-column>
                  <el-table-column prop="count" label="次数" width="80" />
                  <el-table-column prop="percent" label="占比">
                    <template slot-scope="scope">
                      <el-progress :percentage="scope.row.percent" :stroke-width="10" :show-text="false" />
                      <span class="percent-text">{{ scope.row.percent.toFixed(2) }}%</span>
                    </template>
                  </el-table-column>
                </el-table>
              </el-card>
            </el-col>

            <el-col :span="12">
              <el-card shadow="never">
                <div slot="header">词频统计 Top 20</div>
                <el-table :data="tab.wordFrequency" border size="small" max-height="300">
                  <el-table-column prop="word" label="词语" width="150">
                    <template slot-scope="scope">
                      <span class="freq-word">{{ scope.row.word }}</span>
                    </template>
                  </el-table-column>
                  <el-table-column prop="count" label="次数" width="80" />
                  <el-table-column prop="percent" label="占比">
                    <template slot-scope="scope">
                      <el-progress :percentage="scope.row.percent" :stroke-width="10" :show-text="false" />
                      <span class="percent-text">{{ scope.row.percent.toFixed(2) }}%</span>
                    </template>
                  </el-table-column>
                </el-table>
              </el-card>
            </el-col>
          </el-row>

          <el-row :gutter="20" style="margin-top: 20px">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">字符分布</div>
                <div class="char-distribution">
                  <div class="dist-item">
                    <span class="dist-label">中文字符</span>
                    <el-progress :percentage="getPercentage(tab.stats.chinese, tab.stats.chars)" :stroke-width="20" />
                  </div>
                  <div class="dist-item">
                    <span class="dist-label">英文字符</span>
                    <el-progress :percentage="getPercentage(tab.stats.english, tab.stats.chars)" :stroke-width="20" color="#67C23A" />
                  </div>
                  <div class="dist-item">
                    <span class="dist-label">数字</span>
                    <el-progress :percentage="getPercentage(tab.stats.numbers, tab.stats.chars)" :stroke-width="20" color="#E6A23C" />
                  </div>
                  <div class="dist-item">
                    <span class="dist-label">空格</span>
                    <el-progress :percentage="getPercentage(tab.stats.spaces, tab.stats.chars)" :stroke-width="20" color="#909399" />
                  </div>
                  <div class="dist-item">
                    <span class="dist-label">标点符号</span>
                    <el-progress :percentage="getPercentage(tab.stats.punctuation, tab.stats.chars)" :stroke-width="20" color="#F56C6C" />
                  </div>
                </div>
              </el-card>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'TextStatsTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: '统计 ' + seq,
        textContent: '',
        charFreqType: 'all',
        stats: this.emptyStats(),
        charFrequency: [],
        wordFrequency: []
      }
    },
    emptyStats() {
      return {
        chars: 0,
        charsNoSpace: 0,
        chinese: 0,
        english: 0,
        numbers: 0,
        punctuation: 0,
        spaces: 0,
        words: 0,
        lines: 0,
        paragraphs: 0,
        sentences: 0,
        readTimeChinese: 0,
        readTimeEnglish: 0,
        speakTime: 0,
        a4Pages: 0
      }
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clearAll()
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },
    analyzeText(tab) {
      const text = tab.textContent

      // 基本统计
      tab.stats.chars = text.length
      tab.stats.charsNoSpace = text.replace(/\s/g, '').length
      tab.stats.chinese = (text.match(/[一-龥]/g) || []).length
      tab.stats.english = (text.match(/[a-zA-Z]/g) || []).length
      tab.stats.numbers = (text.match(/[0-9]/g) || []).length
      tab.stats.spaces = (text.match(/\s/g) || []).length
      tab.stats.punctuation = (text.match(/[，。！？、；：""''（）【】《》,.!?;:'"()\[\]{}<>]/g) || []).length

      // 行和段落
      tab.stats.lines = text ? text.split('\n').length : 0
      tab.stats.paragraphs = text ? text.split(/\n\s*\n/).filter(p => p.trim()).length : 0

      // 句子数
      tab.stats.sentences = (text.match(/[。！？.!?]+/g) || []).length

      // 单词数（英文单词 + 中文字符作为词）
      const englishWords = (text.match(/[a-zA-Z]+/g) || []).length
      tab.stats.words = englishWords + tab.stats.chinese

      // 阅读时间估算
      // 中文阅读速度约 300-500 字/分钟，取 400
      tab.stats.readTimeChinese = Math.ceil(tab.stats.chinese / 400)
      // 英文阅读速度约 200-250 词/分钟，取 225
      tab.stats.readTimeEnglish = Math.ceil(englishWords / 225)
      // 演讲速度约 150-200 词/分钟，取 175
      tab.stats.speakTime = Math.ceil(tab.stats.words / 175)
      // A4纸约 500-800 字/页，取 600
      tab.stats.a4Pages = Math.max(1, Math.ceil(tab.stats.chars / 600))

      // 字符频率
      this.calculateCharFrequency(tab, text)

      // 词频统计
      this.calculateWordFrequency(tab, text)
    },
    calculateCharFrequency(tab, text) {
      if (!text) {
        tab.charFrequency = []
        return
      }

      let chars = text.replace(/\s/g, '')

      if (tab.charFreqType === 'chinese') {
        chars = chars.match(/[一-龥]/g) || []
      } else if (tab.charFreqType === 'english') {
        chars = chars.match(/[a-zA-Z]/g) || []
      } else {
        chars = chars.split('')
      }

      const freq = {}
      chars.forEach(char => {
        freq[char] = (freq[char] || 0) + 1
      })

      const total = chars.length || 1
      tab.charFrequency = Object.entries(freq)
        .map(([char, count]) => ({
          char,
          count,
          percent: (count / total) * 100
        }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 20)
    },
    calculateWordFrequency(tab, text) {
      if (!text) {
        tab.wordFrequency = []
        return
      }

      // 提取英文单词和中文词语（简单按字分割）
      const englishWords = text.match(/[a-zA-Z]+/g) || []
      const chineseChars = text.match(/[一-龥]/g) || []

      const allWords = [
        ...englishWords.map(w => w.toLowerCase()),
        ...chineseChars
      ]

      const freq = {}
      allWords.forEach(word => {
        if (word.length > 0) {
          freq[word] = (freq[word] || 0) + 1
        }
      })

      const total = allWords.length || 1
      tab.wordFrequency = Object.entries(freq)
        .map(([word, count]) => ({
          word,
          count,
          percent: (count / total) * 100
        }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 20)
    },
    getPercentage(value, total) {
      if (total === 0) return 0
      return Math.round((value / total) * 100)
    },
    clearAll() {
      const tab = this.currentTab()
      if (!tab) return
      tab.textContent = ''
      tab.charFreqType = 'all'
      tab.stats = this.emptyStats()
      tab.charFrequency = []
      tab.wordFrequency = []
    }
  }
}
</script>

