<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>JSON / XML 互转</span>
        <el-button size="small" @click="clearAll">清空当前</el-button>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ getTabTitle(tab) }}
          </span>

          <el-row :gutter="20">
            <el-col :span="11">
              <div class="input-section">
                <div class="section-header">
                  <span>JSON</span>
                  <el-tag size="mini" type="primary">输入或输出</el-tag>
                </div>
                <el-input
                  v-model="tab.jsonText"
                  type="textarea"
                  :rows="15"
                  placeholder='输入 JSON，如: {"name": "张三", "age": 25}'
                  @input="onJsonChange(tab)"
                />
              </div>
            </el-col>

            <el-col :span="2" class="actions-col">
              <div class="action-buttons">
                <el-button type="primary" circle @click="jsonToXml(tab)" title="JSON → XML">
                  <i class="el-icon-right"></i>
                </el-button>
                <span class="action-label">JSON转XML</span>
                <el-button type="success" circle @click="xmlToJson(tab)" title="XML → JSON">
                  <i class="el-icon-back"></i>
                </el-button>
                <span class="action-label">XML转JSON</span>
              </div>
            </el-col>

            <el-col :span="11">
              <div class="output-section">
                <div class="section-header">
                  <span>XML</span>
                  <el-tag size="mini" type="success">输入或输出</el-tag>
                  <el-button type="text" size="mini" @click="copyXml(tab)">复制</el-button>
                </div>
                <el-input
                  v-model="tab.xmlText"
                  type="textarea"
                  :rows="15"
                  placeholder="输入 XML，如: <root><name>张三</name><age>25</age></root>"
                  @input="onXmlChange(tab)"
                />
              </div>
            </el-col>
          </el-row>

          <el-row style="margin-top: 20px">
            <el-col :span="24">
              <el-alert type="info" :closable="false" show-icon>
                <template slot="title">
                  使用提示：在任意一侧输入内容，点击中间按钮即可转换到另一侧
                </template>
              </el-alert>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'JsonXmlTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: 'JSON⇄XML ' + seq,
        jsonText: '',
        xmlText: '',
        isConverting: false
      }
    },
    getTabTitle(tab) {
      const content = tab.jsonText || ''
      const preview = content.trim().split('\n')[0].slice(0, 15)
      return preview ? `${tab.title}: ${preview}...` : tab.title
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clearAll()
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },
    onJsonChange(tab) {
      if (tab.isConverting) return
    },
    onXmlChange(tab) {
      if (tab.isConverting) return
    },
    jsonToXml(tab) {
      if (!tab.jsonText.trim()) {
        this.$message.warning('请输入 JSON 内容')
        return
      }

      try {
        const obj = JSON.parse(tab.jsonText)
        tab.isConverting = true
        tab.xmlText = this.convertJsonToXml(obj, 'root')
        tab.isConverting = false
        this.$message.success('转换成功')
      } catch (e) {
        this.$message.error('JSON 格式错误: ' + e.message)
      }
    },
    convertJsonToXml(obj, rootName) {
      let xml = '<?xml version="1.0" encoding="UTF-8"?>\n'
      xml += this.objectToXml(obj, rootName, 0)
      return xml
    },
    objectToXml(obj, tagName, indent) {
      const spaces = '  '.repeat(indent)
      let result = ''
      
      if (typeof obj !== 'object' || obj === null) {
        result += `${spaces}<${tagName}>${this.escapeXml(obj)}</${tagName}>\n`
        return result
      }
      
      if (Array.isArray(obj)) {
        obj.forEach((item, index) => {
          result += this.objectToXml(item, 'item', indent)
        })
        return result
      }
      
      result += `${spaces}<${tagName}>\n`
      
      for (const key in obj) {
        if (obj.hasOwnProperty(key)) {
          const value = obj[key]
          const safeKey = this.safeTagName(key)
          
          if (Array.isArray(value)) {
            value.forEach(item => {
              result += this.objectToXml(item, safeKey, indent + 1)
            })
          } else if (typeof value === 'object' && value !== null) {
            result += this.objectToXml(value, safeKey, indent + 1)
          } else {
            result += `${spaces}  <${safeKey}>${this.escapeXml(value)}</${safeKey}>\n`
          }
        }
      }
      
      result += `${spaces}</${tagName}>\n`
      return result
    },
    xmlToJson(tab) {
      if (!tab.xmlText.trim()) {
        this.$message.warning('请输入 XML 内容')
        return
      }

      try {
        const parser = new DOMParser()
        const doc = parser.parseFromString(tab.xmlText, 'text/xml')

        const errorNode = doc.querySelector('parsererror')
        if (errorNode) {
          throw new Error('XML 格式错误')
        }

        tab.isConverting = true
        const result = this.xmlNodeToJson(doc.documentElement)
        tab.jsonText = JSON.stringify(result, null, 2)
        tab.isConverting = false
        this.$message.success('转换成功')
      } catch (e) {
        this.$message.error('XML 解析错误: ' + e.message)
      }
    },
    xmlNodeToJson(node) {
      const result = {}
      
      if (node.attributes && node.attributes.length > 0) {
        result['@attributes'] = {}
        for (let i = 0; i < node.attributes.length; i++) {
          const attr = node.attributes[i]
          result['@attributes'][attr.name] = attr.value
        }
      }
      
      if (node.childNodes && node.childNodes.length > 0) {
        let hasElementChild = false
        const childResults = {}
        
        for (let i = 0; i < node.childNodes.length; i++) {
          const child = node.childNodes[i]
          
          if (child.nodeType === 1) {
            hasElementChild = true
            const childName = child.nodeName
            const childJson = this.xmlNodeToJson(child)
            
            if (childResults[childName]) {
              if (!Array.isArray(childResults[childName])) {
                childResults[childName] = [childResults[childName]]
              }
              childResults[childName].push(childJson)
            } else {
              childResults[childName] = childJson
            }
          }
        }
        
        if (hasElementChild) {
          Object.assign(result, childResults)
        } else {
          const text = node.textContent.trim()
          if (text) {
            return this.parseValue(text)
          }
        }
      }
      
      return Object.keys(result).length > 0 ? result : ''
    },
    parseValue(value) {
      if (value === 'true') return true
      if (value === 'false') return false
      if (value === 'null') return null
      if (!isNaN(value) && value.trim() !== '') {
        return Number(value)
      }
      return value
    },
    escapeXml(value) {
      if (value === null || value === undefined) return ''
      return String(value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&apos;')
    },
    safeTagName(name) {
      return name.replace(/[^a-zA-Z0-9_-]/g, '_')
    },
    clearAll() {
      const tab = this.currentTab()
      if (!tab) return
      tab.jsonText = ''
      tab.xmlText = ''
    },
    copyXml(tab) {
      if (!tab.xmlText) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(tab.xmlText).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .input-section, .output-section {
    .section-header {
      display: flex;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
      gap: 10px;

      .el-button {
        margin-left: auto;
      }
    }
  }

  .actions-col {
    display: flex;
    align-items: center;
    justify-content: center;

    .action-buttons {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 10px;

      .action-label {
        font-size: 12px;
        color: #606266;
        margin-bottom: 10px;
      }
    }
  }
}
</style>
