<template>
  <div class="date-calc-tool">
    <el-card>
      <div slot="header">
        <span>日期计算器</span>
      </div>

      <el-tabs v-model="activeTab">
        <el-tab-pane label="日期差计算" name="diff">
          <el-row :gutter="20">
            <el-col :span="12">
              <el-form label-width="100px">
                <el-form-item label="开始日期">
                  <el-date-picker v-model="diff.startDate" type="date" placeholder="选择日期" style="width: 100%" />
                </el-form-item>
                <el-form-item label="结束日期">
                  <el-date-picker v-model="diff.endDate" type="date" placeholder="选择日期" style="width: 100%" />
                </el-form-item>
              </el-form>
              <el-divider>计算结果</el-divider>
              <div class="result-box">
                <div class="result-item">
                  <span class="label">相差天数：</span>
                  <span class="value">{{ diff.days }} 天</span>
                </div>
                <div class="result-item">
                  <span class="label">相差周数：</span>
                  <span class="value">{{ diff.weeks }} 周 (余 {{ diff.weekDays }} 天)</span>
                </div>
                <div class="result-item">
                  <span class="label">相差月数：</span>
                  <span class="value">约 {{ diff.months }} 个月</span>
                </div>
                <div class="result-item">
                  <span class="label">相差年数：</span>
                  <span class="value">约 {{ diff.years }} 年</span>
                </div>
                <div class="result-item">
                  <span class="label">工作日：</span>
                  <span class="value">{{ diff.workDays }} 天</span>
                </div>
              </div>
            </el-col>
            <el-col :span="12">
              <el-divider>时间轴</el-divider>
              <div class="timeline">
                <div class="timeline-item">
                  <div class="timeline-date">{{ formatDate(diff.startDate) }}</div>
                  <div class="timeline-label">开始</div>
                </div>
                <div class="timeline-bar">
                  <div class="timeline-progress" :style="{ width: '100%' }"></div>
                </div>
                <div class="timeline-item">
                  <div class="timeline-date">{{ formatDate(diff.endDate) }}</div>
                  <div class="timeline-label">结束</div>
                </div>
              </div>
              <el-divider>详细分解</el-divider>
              <div class="breakdown">
                <p>共 <strong>{{ diff.days }}</strong> 天</p>
                <p>= <strong>{{ diff.years }}</strong> 年 + <strong>{{ diff.monthsRemainder }}</strong> 月 + <strong>{{ diff.daysRemainder }}</strong> 天</p>
                <p>= <strong>{{ diff.totalHours }}</strong> 小时</p>
                <p>= <strong>{{ diff.totalMinutes }}</strong> 分钟</p>
                <p>= <strong>{{ diff.totalSeconds }}</strong> 秒</p>
              </div>
            </el-col>
          </el-row>
        </el-tab-pane>

        <el-tab-pane label="日期加减" name="add">
          <el-row :gutter="20">
            <el-col :span="12">
              <el-form label-width="100px">
                <el-form-item label="基准日期">
                  <el-date-picker v-model="add.baseDate" type="date" placeholder="选择日期" style="width: 100%" />
                </el-form-item>
                <el-form-item label="操作">
                  <el-radio-group v-model="add.operation">
                    <el-radio label="add">加</el-radio>
                    <el-radio label="subtract">减</el-radio>
                  </el-radio-group>
                </el-form-item>
                <el-form-item label="年">
                  <el-input-number v-model="add.years" :min="0" style="width: 120px" />
                </el-form-item>
                <el-form-item label="月">
                  <el-input-number v-model="add.months" :min="0" style="width: 120px" />
                </el-form-item>
                <el-form-item label="天">
                  <el-input-number v-model="add.days" :min="0" style="width: 120px" />
                </el-form-item>
                <el-form-item label="周">
                  <el-input-number v-model="add.weeks" :min="0" style="width: 120px" />
                </el-form-item>
              </el-form>
            </el-col>
            <el-col :span="12">
              <el-divider>计算结果</el-divider>
              <div class="result-box">
                <div class="result-item highlight">
                  <span class="label">结果日期：</span>
                  <span class="value">{{ formatDate(add.resultDate) }}</span>
                </div>
                <div class="result-item">
                  <span class="label">星期：</span>
                  <span class="value">{{ add.resultDayOfWeek }}</span>
                </div>
                <div class="result-item">
                  <span class="label">是第几周：</span>
                  <span class="value">第 {{ add.resultWeek }} 周</span>
                </div>
                <div class="result-item">
                  <span class="label">是第几天：</span>
                  <span class="value">第 {{ add.resultDayOfYear }} 天</span>
                </div>
              </div>
            </el-col>
          </el-row>
        </el-tab-pane>

        <el-tab-pane label="工作日计算" name="workday">
          <el-row :gutter="20">
            <el-col :span="12">
              <el-form label-width="100px">
                <el-form-item label="开始日期">
                  <el-date-picker v-model="workday.startDate" type="date" placeholder="选择日期" style="width: 100%" />
                </el-form-item>
                <el-form-item label="工作日数">
                  <el-input-number v-model="workday.days" :min="1" style="width: 200px" />
                </el-form-item>
                <el-form-item label="排除节假日">
                  <el-switch v-model="workday.excludeHolidays" />
                </el-form-item>
              </el-form>
            </el-col>
            <el-col :span="12">
              <el-divider>计算结果</el-divider>
              <div class="result-box">
                <div class="result-item highlight">
                  <span class="label">截止日期：</span>
                  <span class="value">{{ formatDate(workday.resultDate) }}</span>
                </div>
                <div class="result-item">
                  <span class="label">自然日数：</span>
                  <span class="value">{{ workday.naturalDays }} 天</span>
                </div>
                <div class="result-item">
                  <span class="label">跳过周末：</span>
                  <span class="value">{{ workday.weekendDays }} 天</span>
                </div>
              </div>
            </el-col>
          </el-row>
        </el-tab-pane>

        <el-tab-pane label="年龄计算" name="age">
          <el-row :gutter="20">
            <el-col :span="12">
              <el-form label-width="100px">
                <el-form-item label="出生日期">
                  <el-date-picker v-model="age.birthDate" type="date" placeholder="选择日期" style="width: 100%" />
                </el-form-item>
              </el-form>
            </el-col>
            <el-col :span="12">
              <el-divider>计算结果</el-divider>
              <div class="result-box">
                <div class="result-item highlight">
                  <span class="label">年龄：</span>
                  <span class="value">{{ age.years }} 岁</span>
                </div>
                <div class="result-item">
                  <span class="label">精确年龄：</span>
                  <span class="value">{{ age.years }} 岁 {{ age.months }} 月 {{ age.days }} 天</span>
                </div>
                <div class="result-item">
                  <span class="label">总天数：</span>
                  <span class="value">{{ age.totalDays }} 天</span>
                </div>
                <div class="result-item">
                  <span class="label">总周数：</span>
                  <span class="value">{{ age.totalWeeks }} 周</span>
                </div>
                <div class="result-item">
                  <span class="label">总月数：</span>
                  <span class="value">{{ age.totalMonths }} 月</span>
                </div>
                <div class="result-item">
                  <span class="label">下次生日：</span>
                  <span class="value">{{ age.nextBirthday }} (还有 {{ age.daysToNextBirthday }} 天)</span>
                </div>
                <div class="result-item">
                  <span class="label">生肖：</span>
                  <span class="value">{{ age.zodiac }}</span>
                </div>
                <div class="result-item">
                  <span class="label">星座：</span>
                  <span class="value">{{ age.constellation }}</span>
                </div>
              </div>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'DateCalcTool',
  data() {
    return {
      activeTab: 'diff',
      diff: {
        startDate: new Date(),
        endDate: new Date()
      },
      add: {
        baseDate: new Date(),
        operation: 'add',
        years: 0,
        months: 0,
        days: 0,
        weeks: 0
      },
      workday: {
        startDate: new Date(),
        days: 10,
        excludeHolidays: false
      },
      age: {
        birthDate: new Date(1990, 0, 1)
      }
    }
  },
  computed: {
    diffResults() {
      const start = new Date(this.diff.startDate)
      const end = new Date(this.diff.endDate)
      const diffTime = Math.abs(end - start)
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24))
      return { diffDays }
    },
    'diff.days'() {
      const start = new Date(this.diff.startDate)
      const end = new Date(this.diff.endDate)
      return Math.abs(Math.ceil((end - start) / (1000 * 60 * 60 * 24)))
    },
    'diff.weeks'() {
      return Math.floor(this.diff.days / 7)
    },
    'diff.weekDays'() {
      return this.diff.days % 7
    },
    'diff.months'() {
      return Math.floor(this.diff.days / 30)
    },
    'diff.years'() {
      return (this.diff.days / 365).toFixed(2)
    },
    'diff.workDays'() {
      const start = new Date(this.diff.startDate)
      const end = new Date(this.diff.endDate)
      let count = 0
      const current = new Date(start)
      while (current <= end) {
        const day = current.getDay()
        if (day !== 0 && day !== 6) count++
        current.setDate(current.getDate() + 1)
      }
      return count
    },
    'diff.monthsRemainder'() {
      return Math.floor((this.diff.days % 365) / 30)
    },
    'diff.daysRemainder'() {
      return this.diff.days % 30
    },
    'diff.totalHours'() {
      return this.diff.days * 24
    },
    'diff.totalMinutes'() {
      return this.diff.days * 24 * 60
    },
    'diff.totalSeconds'() {
      return this.diff.days * 24 * 60 * 60
    },
    'add.resultDate'() {
      const date = new Date(this.add.baseDate)
      const multiplier = this.add.operation === 'add' ? 1 : -1
      date.setFullYear(date.getFullYear() + (this.add.years * multiplier))
      date.setMonth(date.getMonth() + (this.add.months * multiplier))
      date.setDate(date.getDate() + (this.add.days * multiplier) + (this.add.weeks * 7 * multiplier))
      return date
    },
    'add.resultDayOfWeek'() {
      const days = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六']
      return days[this.add.resultDate.getDay()]
    },
    'add.resultWeek'() {
      const start = new Date(this.add.resultDate.getFullYear(), 0, 1)
      return Math.ceil((((this.add.resultDate - start) / 86400000) + start.getDay() + 1) / 7)
    },
    'add.resultDayOfYear'() {
      const start = new Date(this.add.resultDate.getFullYear(), 0, 0)
      return Math.floor((this.add.resultDate - start) / (1000 * 60 * 60 * 24))
    },
    'workday.resultDate'() {
      let current = new Date(this.workday.startDate)
      let count = 0
      while (count < this.workday.days) {
        current.setDate(current.getDate() + 1)
        const day = current.getDay()
        if (day !== 0 && day !== 6) count++
      }
      return current
    },
    'workday.naturalDays'() {
      const start = new Date(this.workday.startDate)
      const end = new Date(this.workday.resultDate)
      return Math.ceil((end - start) / (1000 * 60 * 60 * 24))
    },
    'workday.weekendDays'() {
      return this.workday.naturalDays - this.workday.days
    },
    'age.years'() {
      const today = new Date()
      const birth = new Date(this.age.birthDate)
      let age = today.getFullYear() - birth.getFullYear()
      const monthDiff = today.getMonth() - birth.getMonth()
      if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) {
        age--
      }
      return age
    },
    'age.months'() {
      const today = new Date()
      const birth = new Date(this.age.birthDate)
      let months = today.getMonth() - birth.getMonth()
      if (months < 0) months += 12
      return months
    },
    'age.days'() {
      const today = new Date()
      const birth = new Date(this.age.birthDate)
      let days = today.getDate() - birth.getDate()
      if (days < 0) {
        const lastMonth = new Date(today.getFullYear(), today.getMonth(), 0)
        days += lastMonth.getDate()
      }
      return days
    },
    'age.totalDays'() {
      const today = new Date()
      const birth = new Date(this.age.birthDate)
      return Math.floor((today - birth) / (1000 * 60 * 60 * 24))
    },
    'age.totalWeeks'() {
      return Math.floor(this.age.totalDays / 7)
    },
    'age.totalMonths'() {
      return this.age.years * 12 + this.age.months
    },
    'age.nextBirthday'() {
      const today = new Date()
      const birth = new Date(this.age.birthDate)
      const next = new Date(today.getFullYear(), birth.getMonth(), birth.getDate())
      if (next < today) {
        next.setFullYear(next.getFullYear() + 1)
      }
      return this.formatDate(next)
    },
    'age.daysToNextBirthday'() {
      const today = new Date()
      const birth = new Date(this.age.birthDate)
      const next = new Date(today.getFullYear(), birth.getMonth(), birth.getDate())
      if (next < today) {
        next.setFullYear(next.getFullYear() + 1)
      }
      return Math.ceil((next - today) / (1000 * 60 * 60 * 24))
    },
    'age.zodiac'() {
      const zodiacs = ['猴', '鸡', '狗', '猪', '鼠', '牛', '虎', '兔', '龙', '蛇', '马', '羊']
      const birth = new Date(this.age.birthDate)
      return zodiacs[birth.getFullYear() % 12]
    },
    'age.constellation'() {
      const birth = new Date(this.age.birthDate)
      const month = birth.getMonth() + 1
      const day = birth.getDate()
      const constellations = [
        { name: '摩羯座', start: [1, 1], end: [1, 19] },
        { name: '水瓶座', start: [1, 20], end: [2, 18] },
        { name: '双鱼座', start: [2, 19], end: [3, 20] },
        { name: '白羊座', start: [3, 21], end: [4, 19] },
        { name: '金牛座', start: [4, 20], end: [5, 20] },
        { name: '双子座', start: [5, 21], end: [6, 21] },
        { name: '巨蟹座', start: [6, 22], end: [7, 22] },
        { name: '狮子座', start: [7, 23], end: [8, 22] },
        { name: '处女座', start: [8, 23], end: [9, 22] },
        { name: '天秤座', start: [9, 23], end: [10, 23] },
        { name: '天蝎座', start: [10, 24], end: [11, 22] },
        { name: '射手座', start: [11, 23], end: [12, 21] },
        { name: '摩羯座', start: [12, 22], end: [12, 31] }
      ]
      for (const c of constellations) {
        if ((month === c.start[0] && day >= c.start[1]) || (month === c.end[0] && day <= c.end[1])) {
          return c.name
        }
      }
      return ''
    }
  },
  methods: {
    formatDate(date) {
      if (!date) return ''
      const d = new Date(date)
      return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
    }
  }
}
</script>

<style scoped>
.date-calc-tool {
  padding: 20px;
}

.result-box {
  background: #f5f7fa;
  border-radius: 8px;
  padding: 20px;
}

.result-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 0;
  border-bottom: 1px solid #ebeef5;
}

.result-item:last-child {
  border-bottom: none;
}

.result-item.highlight {
  background: #e6f7ff;
  margin: -10px -20px 10px;
  padding: 15px 20px;
  border-radius: 8px 8px 0 0;
  border-bottom: 1px solid #b3e5fc;
}

.result-item .label {
  color: #606266;
}

.result-item .value {
  font-size: 18px;
  font-weight: bold;
  color: #409eff;
}

.timeline {
  display: flex;
  align-items: center;
  padding: 20px;
}

.timeline-item {
  text-align: center;
}

.timeline-date {
  font-size: 14px;
  font-weight: bold;
  color: #303133;
}

.timeline-label {
  font-size: 12px;
  color: #909399;
}

.timeline-bar {
  flex: 1;
  height: 4px;
  background: #e4e7ed;
  margin: 0 20px;
  border-radius: 2px;
  position: relative;
}

.timeline-progress {
  height: 100%;
  background: #409eff;
  border-radius: 2px;
}

.breakdown {
  background: #f5f7fa;
  padding: 15px;
  border-radius: 8px;
  line-height: 2;
}

.breakdown p {
  margin: 0;
}

.breakdown strong {
  color: #409eff;
}
</style>
