<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header" class="card-header">
        <span class="card-title">文生图 / 图生图</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="showConfig = !showConfig">
            {{ showConfig ? '隐藏配置' : '显示配置' }}
          </el-button>
          <el-button size="small" @click="clearResults">清空结果</el-button>
        </el-button-group>
      </div>

      <!-- 配置面板 -->
      <el-collapse-transition>
        <div v-show="showConfig" class="config-panel">
          <el-form :model="config" :label-width="labelWidth" size="small">
            <el-row :gutter="20">
              <el-col :xs="24" :sm="12">
                <el-form-item label="API 地址">
                  <el-input v-model="config.baseUrl" placeholder="https://api.openai.com/v1">
                    <el-button slot="append" @click="presetDialogVisible = true">预设</el-button>
                  </el-input>
                  <div class="field-tip">仅填到 /v1，工具自动拼接 /images/generations 与 /images/edits</div>
                </el-form-item>
              </el-col>
              <el-col :xs="24" :sm="12">
                <el-form-item label="API Key">
                  <el-input v-model="config.apiKey" type="password" show-password placeholder="sk-..." />
                </el-form-item>
              </el-col>
            </el-row>
            <el-row :gutter="20">
              <el-col :xs="24" :sm="8">
                <el-form-item label="模型">
                  <el-select v-model="config.model" filterable allow-create default-first-option placeholder="选择或输入模型">
                    <el-option v-for="m in modelOptions" :key="m" :label="m" :value="m" />
                  </el-select>
                </el-form-item>
              </el-col>
              <el-col :xs="24" :sm="8">
                <el-form-item label="尺寸">
                  <el-select v-model="config.size" filterable allow-create default-first-option placeholder="选择尺寸">
                    <el-option v-for="s in sizeOptions" :key="s" :label="s" :value="s" />
                  </el-select>
                </el-form-item>
              </el-col>
              <el-col :xs="24" :sm="8">
                <el-form-item label="生成数量">
                  <el-input-number v-model="config.n" :min="1" :max="10" />
                </el-form-item>
              </el-col>
            </el-row>
          </el-form>
        </div>
      </el-collapse-transition>

      <el-tabs v-model="activeMode" class="mode-tabs">
        <!-- 文生图 -->
        <el-tab-pane label="文生图" name="t2i">
          <el-form label-width="0" size="small">
            <el-input
              v-model="t2iPrompt"
              type="textarea"
              :rows="4"
              placeholder="输入图像描述提示词，例如：a cute cat astronaut floating in space, digital art"
            />
            <div class="action-bar">
              <el-button type="primary" :loading="loading" @click="generateFromText">
                {{ loading ? '生成中...' : '生成图像' }}
              </el-button>
            </div>
          </el-form>
        </el-tab-pane>

        <!-- 图生图 -->
        <el-tab-pane label="图生图（编辑）" name="i2i">
          <el-form label-width="0" size="small">
            <div class="upload-row">
              <el-upload
                action=""
                :auto-upload="false"
                :show-file-list="false"
                accept="image/png"
                :on-change="onImageChange"
              >
                <el-button size="small" icon="el-icon-upload2">选择源图（PNG）</el-button>
              </el-upload>
              <el-upload
                action=""
                :auto-upload="false"
                :show-file-list="false"
                accept="image/png"
                :on-change="onMaskChange"
              >
                <el-button size="small" icon="el-icon-upload2">选择蒙版（可选，PNG）</el-button>
              </el-upload>
              <span v-if="sourceImage" class="file-name">源图: {{ sourceImage.name }}</span>
              <span v-if="maskImage" class="file-name">蒙版: {{ maskImage.name }}</span>
            </div>
            <div v-if="sourcePreview" class="source-preview">
              <img :src="sourcePreview" alt="源图预览" />
            </div>
            <el-input
              v-model="i2iPrompt"
              type="textarea"
              :rows="3"
              placeholder="描述希望编辑后的效果，例如：add a red hat on the cat"
            />
            <div class="action-bar">
              <el-button type="primary" :loading="loading" :disabled="!sourceImage" @click="generateFromImage">
                {{ loading ? '生成中...' : '编辑图像' }}
              </el-button>
              <span class="field-tip">编辑接口要求 PNG、正方形且小于 4MB；蒙版透明区域为待重绘区域</span>
            </div>
          </el-form>
        </el-tab-pane>
      </el-tabs>

      <el-alert v-if="error" type="error" :closable="false" show-icon class="error-alert">
        <template slot="title">{{ error }}</template>
      </el-alert>

      <!-- 结果展示 -->
      <div v-if="results.length" class="results">
        <div class="results-header">生成结果（{{ results.length }}）</div>
        <div class="result-grid">
          <div v-for="(img, idx) in results" :key="img.id" class="result-item">
            <img :src="img.src" :alt="img.id" @click="previewImage(img.src)" />
            <div class="result-ops">
              <el-button type="text" size="mini" @click="useAsSource(img)">
                <i class="el-icon-refresh-right"></i> 用作源图
              </el-button>
              <el-button type="text" size="mini" @click="downloadImage(img.src, idx)">
                <i class="el-icon-download"></i> 下载
              </el-button>
            </div>
          </div>
        </div>
      </div>
      <div v-else-if="!loading" class="empty-results">
        <i class="el-icon-picture-outline"></i>
        <p>生成的图像会显示在这里</p>
      </div>
    </el-card>

    <el-dialog title="API 预设" :visible.sync="presetDialogVisible" width="500px">
      <div class="preset-list">
        <div v-for="preset in apiPresets" :key="preset.name" class="preset-item" @click="applyPreset(preset)">
          <div class="preset-name">{{ preset.name }}</div>
          <div class="preset-url">{{ preset.baseUrl }}</div>
        </div>
      </div>
    </el-dialog>

    <el-dialog :visible.sync="previewVisible" width="auto" custom-class="image-preview-dialog">
      <img v-if="previewSrc" :src="previewSrc" style="max-width: 100%; max-height: 80vh" alt="预览" />
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: 'ImageGenTool',
  data() {
    return {
      showConfig: true,
      labelWidth: '90px',
      activeMode: 't2i',
      config: {
        baseUrl: 'https://api.openai.com/v1',
        apiKey: '',
        model: 'dall-e-3',
        size: '1024x1024',
        n: 1
      },
      modelOptions: ['gpt-image-1', 'dall-e-3', 'dall-e-2'],
      sizeOptions: ['1024x1024', '1792x1024', '1024x1792', '512x512', '256x256'],
      t2iPrompt: '',
      i2iPrompt: '',
      sourceImage: null,
      sourcePreview: '',
      maskImage: null,
      loading: false,
      error: '',
      results: [],
      previewVisible: false,
      previewSrc: '',
      presetDialogVisible: false,
      apiPresets: [
        { name: 'OpenAI', baseUrl: 'https://api.openai.com/v1', model: 'dall-e-3' },
        { name: '通义万相（兼容）', baseUrl: 'https://dashscope.aliyuncs.com/compatible-mode/v1', model: 'wanx-v1' },
        { name: '智谱 CogView', baseUrl: 'https://open.bigmodel.cn/api/paas/v4', model: 'cogview-3' },
        { name: '自定义中转', baseUrl: 'https://your-proxy.example.com/v1', model: 'dall-e-3' }
      ]
    }
  },
  mounted() {
    this.loadConfig()
    this.handleResize()
    window.addEventListener('resize', this.handleResize)
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.handleResize)
  },
  methods: {
    handleResize() {
      this.labelWidth = window.innerWidth < 768 ? '70px' : '90px'
    },
    endpoint(path) {
      const base = this.config.baseUrl.replace(/\/+$/, '')
      return base + path
    },
    checkReady() {
      if (!this.config.apiKey) {
        this.$message.warning('请先配置 API Key')
        return false
      }
      if (!this.config.baseUrl) {
        this.$message.warning('请先配置 API 地址')
        return false
      }
      return true
    },
    async generateFromText() {
      if (!this.checkReady()) return
      if (!this.t2iPrompt.trim()) {
        this.$message.warning('请输入提示词')
        return
      }
      this.loading = true
      this.error = ''
      try {
        const body = {
          model: this.config.model,
          prompt: this.t2iPrompt,
          n: this.config.n,
          size: this.config.size
        }
        const response = await fetch(this.endpoint('/images/generations'), {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${this.config.apiKey}`
          },
          body: JSON.stringify(body)
        })
        await this.handleResponse(response)
      } catch (e) {
        this.error = '请求失败: ' + e.message
      } finally {
        this.loading = false
      }
    },
    async generateFromImage() {
      if (!this.checkReady()) return
      if (!this.sourceImage) {
        this.$message.warning('请选择源图')
        return
      }
      if (!this.i2iPrompt.trim()) {
        this.$message.warning('请输入编辑提示词')
        return
      }
      this.loading = true
      this.error = ''
      try {
        const form = new FormData()
        form.append('model', this.config.model)
        form.append('image', this.sourceImage)
        if (this.maskImage) {
          form.append('mask', this.maskImage)
        }
        form.append('prompt', this.i2iPrompt)
        form.append('n', this.config.n)
        form.append('size', this.config.size)

        const response = await fetch(this.endpoint('/images/edits'), {
          method: 'POST',
          headers: {
            // FormData 不要手动设 Content-Type，浏览器会带 boundary
            'Authorization': `Bearer ${this.config.apiKey}`
          },
          body: form
        })
        await this.handleResponse(response)
      } catch (e) {
        this.error = '请求失败: ' + e.message
      } finally {
        this.loading = false
      }
    },
    async handleResponse(response) {
      if (!response.ok) {
        let msg = '请求失败 (HTTP ' + response.status + ')'
        try {
          const err = await response.json()
          msg = err.error?.message || err.message || msg
        } catch (e) { /* 非 JSON 错误体 */ }
        throw new Error(msg)
      }
      const data = await response.json()
      const items = data.data || []
      if (!items.length) {
        throw new Error('响应中没有图像数据')
      }
      const newResults = items.map(item => {
        const id = 'img-' + Date.now() + '-' + Math.random().toString(36).slice(2, 9)
        if (item.b64_json) {
          return { id, src: 'data:image/png;base64,' + item.b64_json }
        }
        return { id, src: item.url }
      })
      this.results = newResults.concat(this.results)
      this.$message.success(`成功生成 ${newResults.length} 张图像`)
    },
    onImageChange(file) {
      this.sourceImage = file.raw
      const reader = new FileReader()
      reader.onload = e => { this.sourcePreview = e.target.result }
      reader.readAsDataURL(file.raw)
    },
    onMaskChange(file) {
      this.maskImage = file.raw
    },
    async useAsSource(img) {
      try {
        // base64 data URI 与远程 URL 统一抓成 blob，再包成 File 供编辑接口使用
        const resp = await fetch(img.src)
        const blob = await resp.blob()
        const type = blob.type && blob.type.startsWith('image/') ? blob.type : 'image/png'
        const ext = type.includes('png') ? 'png' : (type.split('/')[1] || 'png')
        const file = new File([blob], `source-${img.id}.${ext}`, { type })
        this.sourceImage = file
        this.maskImage = null
        const reader = new FileReader()
        reader.onload = e => { this.sourcePreview = e.target.result }
        reader.readAsDataURL(file)
        this.activeMode = 'i2i'
        this.$message.success('已载入为源图，可在图生图中继续编辑')
      } catch (e) {
        this.$message.error('载入源图失败：' + e.message + '（远程图片可能受跨域限制，可先下载再上传）')
      }
    },
    previewImage(src) {
      this.previewSrc = src
      this.previewVisible = true
    },
    async downloadImage(src, index) {
      try {
        let blobUrl = src
        let revoke = false
        // 远程 URL 先抓成 blob，避免跨域直接下载被拦
        if (src.startsWith('http')) {
          const resp = await fetch(src)
          const blob = await resp.blob()
          blobUrl = URL.createObjectURL(blob)
          revoke = true
        }
        const a = document.createElement('a')
        a.href = blobUrl
        a.download = `image_${Date.now()}_${index + 1}.png`
        a.click()
        if (revoke) URL.revokeObjectURL(blobUrl)
      } catch (e) {
        this.$message.error('下载失败，可右键图片另存为')
      }
    },
    clearResults() {
      this.results = []
      this.error = ''
    },
    applyPreset(preset) {
      this.config.baseUrl = preset.baseUrl
      this.config.model = preset.model
      this.presetDialogVisible = false
    },
    loadConfig() {
      const saved = localStorage.getItem('imagegen_config')
      if (saved) {
        try {
          this.config = { ...this.config, ...JSON.parse(saved) }
        } catch (e) { /* 忽略 */ }
      }
    },
    saveConfig() {
      localStorage.setItem('imagegen_config', JSON.stringify(this.config))
    }
  },
  watch: {
    config: {
      handler() { this.saveConfig() },
      deep: true
    }
  }
}
</script>

