<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>大小写转换</span>
        <el-button size="small" @click="clear">清空当前</el-button>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ tab.title }}
          </span>

          <el-row :gutter="20">
            <el-col :span="11">
              <div class="input-section">
                <div class="section-header">
                  <span>输入文本</span>
                  <el-tag size="mini" type="primary">输入或输出</el-tag>
                </div>
                <el-input
                  v-model="tab.inputText"
                  type="textarea"
                  :rows="8"
                  placeholder="请输入要转换的文本"
                />
              </div>
            </el-col>

            <el-col :span="2" class="actions-col">
              <div class="action-buttons">
                <el-button type="primary" circle @click="convertForward(tab)" title="转换">
                  <i class="el-icon-right"></i>
                </el-button>
                <span class="action-label">转换</span>
                <el-button type="success" circle @click="convertBackward(tab)" title="反向转换">
                  <i class="el-icon-back"></i>
                </el-button>
                <span class="action-label">反向</span>
              </div>
            </el-col>

            <el-col :span="11">
              <div class="output-section">
                <div class="section-header">
                  <span>转换结果</span>
                  <el-tag size="mini" type="success">输入或输出</el-tag>
                </div>
                <el-input
                  v-model="tab.outputText"
                  type="textarea"
                  :rows="8"
                  placeholder="转换结果将显示在这里"
                />
              </div>
            </el-col>
          </el-row>

          <el-row :gutter="10" style="margin-top: 20px">
            <el-col :span="24" class="conversion-options">
              <span class="options-label">转换方式：</span>
              <el-radio-group v-model="tab.conversionType" size="small">
                <el-radio-button label="upper">转大写</el-radio-button>
                <el-radio-button label="lower">转小写</el-radio-button>
                <el-radio-button label="camel">驼峰式</el-radio-button>
                <el-radio-button label="pascal">帕斯卡</el-radio-button>
                <el-radio-button label="snake">蛇形式</el-radio-button>
                <el-radio-button label="kebab">短横线</el-radio-button>
                <el-radio-button label="constant">常量式</el-radio-button>
              </el-radio-group>
            </el-col>
          </el-row>

          <el-divider>批量转换预览</el-divider>

          <el-row v-if="tab.inputText">
            <el-col :span="24">
              <el-table :data="previewData(tab)" border size="small">
                <el-table-column prop="name" label="转换类型" width="150" />
                <el-table-column prop="value" label="结果">
                  <template slot-scope="scope">
                    <code>{{ scope.row.value }}</code>
                    <el-button
                      type="text"
                      size="mini"
                      style="float: right"
                      @click="applyConversion(tab, scope.row.type)"
                    >应用</el-button>
                  </template>
                </el-table-column>
              </el-table>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>
<script>
export default {
  name: 'CaseTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: '大小写 ' + seq,
        inputText: '',
        outputText: '',
        conversionType: 'upper'
      }
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时关闭转为清空
        const tab = this.tabs[0]
        tab.inputText = ''
        tab.outputText = ''
        return
      }
      const tabs = this.tabs
      let activeName = this.activeTab
      if (activeName === targetName) {
        tabs.forEach((tab, index) => {
          if (tab.id === targetName) {
            const nextTab = tabs[index + 1] || tabs[index - 1]
            if (nextTab) {
              activeName = nextTab.id
            }
          }
        })
      }
      this.activeTab = activeName
      this.tabs = tabs.filter(tab => tab.id !== targetName)
    },
    currentTab() {
      return this.tabs.find(tab => tab.id === this.activeTab)
    },
    previewData(tab) {
      if (!tab.inputText) return []
      return [
        { name: '大写', value: tab.inputText.toUpperCase(), type: 'upper' },
        { name: '小写', value: tab.inputText.toLowerCase(), type: 'lower' },
        { name: '驼峰式', value: this.convertToCamelCase(tab.inputText), type: 'camel' },
        { name: '帕斯卡式', value: this.convertToPascalCase(tab.inputText), type: 'pascal' },
        { name: '蛇形式', value: this.convertToSnakeCase(tab.inputText), type: 'snake' },
        { name: '短横线式', value: this.convertToKebabCase(tab.inputText), type: 'kebab' },
        { name: '常量式', value: this.convertToConstantCase(tab.inputText), type: 'constant' }
      ]
    },
    convertForward(tab) {
      if (!tab.inputText) {
        this.$message.warning('请输入要转换的文本')
        return
      }
      tab.outputText = this.convert(tab.inputText, tab.conversionType)
      this.$message.success('转换成功')
    },
    convertBackward(tab) {
      if (!tab.outputText) {
        this.$message.warning('请输入要转换的文本')
        return
      }
      tab.inputText = this.convert(tab.outputText, tab.conversionType)
      this.$message.success('转换成功')
    },
    convert(text, type) {
      switch (type) {
        case 'upper': return text.toUpperCase()
        case 'lower': return text.toLowerCase()
        case 'camel': return this.convertToCamelCase(text)
        case 'pascal': return this.convertToPascalCase(text)
        case 'snake': return this.convertToSnakeCase(text)
        case 'kebab': return this.convertToKebabCase(text)
        case 'constant': return this.convertToConstantCase(text)
        default: return text
      }
    },
    applyConversion(tab, type) {
      tab.conversionType = type
      tab.outputText = this.convert(tab.inputText, type)
      this.$message.success('已应用转换')
    },
    convertToCamelCase(str) {
      return str
        .replace(/[-_\s]+(.)?/g, (_, char) => char ? char.toUpperCase() : '')
        .replace(/^[A-Z]/, char => char.toLowerCase())
    },
    convertToPascalCase(str) {
      return str
        .replace(/[-_\s]+(.)?/g, (_, char) => char ? char.toUpperCase() : '')
        .replace(/^[a-z]/, char => char.toUpperCase())
    },
    convertToSnakeCase(str) {
      return str
        .replace(/([A-Z])/g, '_$1')
        .replace(/[-\s]+/g, '_')
        .toLowerCase()
        .replace(/^_/, '')
    },
    convertToKebabCase(str) {
      return str
        .replace(/([A-Z])/g, '-$1')
        .replace(/[_\s]+/g, '-')
        .toLowerCase()
        .replace(/^-/, '')
    },
    convertToConstantCase(str) {
      return this.convertToSnakeCase(str).toUpperCase()
    },
    clear() {
      const tab = this.currentTab()
      if (!tab) return
      tab.inputText = ''
      tab.outputText = ''
    }
  }
}
</script>

