<template>
  <div class="chinese-convert-tool">
    <el-card>
      <div slot="header">
        <span>简繁转换工具</span>
        <el-button size="small" @click="clear">清空当前</el-button>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ tab.title }}
          </span>

          <el-row :gutter="20">
            <el-col :span="11">
              <div class="section-header">
                <span>简体中文</span>
                <el-button type="text" @click="copySimple(tab)">复制</el-button>
              </div>
              <el-input
                v-model="tab.simpleText"
                type="textarea"
                :rows="12"
                placeholder="输入简体中文..."
                @input="convertToTraditional(tab)"
              />
            </el-col>

            <el-col :span="2" class="convert-buttons">
              <el-button type="primary" icon="el-icon-right" @click="convertToTraditional(tab)" title="简体转繁体"></el-button>
              <el-button type="primary" icon="el-icon-back" @click="convertToSimple(tab)" title="繁体转简体"></el-button>
            </el-col>

            <el-col :span="11">
              <div class="section-header">
                <span>繁体中文</span>
                <el-button type="text" @click="copyTraditional(tab)">复制</el-button>
              </div>
              <el-input
                v-model="tab.traditionalText"
                type="textarea"
                :rows="12"
                placeholder="输入繁体中文..."
                @input="convertToSimple(tab)"
              />
            </el-col>
          </el-row>

          <div class="action-buttons">
            <el-button @click="loadExample(tab)">加载示例</el-button>
            <el-button @click="clear">清空</el-button>
          </div>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
