const traditionalToSimpleMap = {}
for (const [key, value] of Object.entries(simpleToTraditionalMap)) {
  traditionalToSimpleMap[value] = key
}

export default {
  name: 'ChineseConvertTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: '简繁 ' + seq,
        simpleText: '',
        traditionalText: ''
      }
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clear()
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },
    convertToTraditional(tab) {
      if (!tab.simpleText) {
        tab.traditionalText = ''
        return
      }
      const chars = tab.simpleText.split('')
      const result = chars.map(char => simpleToTraditionalMap[char] || char)
      tab.traditionalText = result.join('')
    },
    convertToSimple(tab) {
      if (!tab.traditionalText) {
        tab.simpleText = ''
        return
      }
      const chars = tab.traditionalText.split('')
      const result = chars.map(char => traditionalToSimpleMap[char] || char)
      tab.simpleText = result.join('')
    },
    copySimple(tab) {
      if (!tab.simpleText) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(tab.simpleText).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    copyTraditional(tab) {
      if (!tab.traditionalText) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(tab.traditionalText).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    loadExample(tab) {
      tab.simpleText = '欢迎使用简繁转换工具，这是一个非常好用的在线工具。'
      this.convertToTraditional(tab)
    },
    clear() {
      const tab = this.currentTab()
      if (!tab) return
      tab.simpleText = ''
      tab.traditionalText = ''
    }
  }
}
</script>

