<template>
  <div class="data-mask-tool">
    <el-card>
      <div slot="header">
        <span>数据脱敏工具</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="loadExample">加载示例</el-button>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <div class="input-section">
            <div class="section-title">原始数据</div>
            <el-input
              v-model="input"
              type="textarea"
              :rows="12"
              placeholder="输入需要脱敏的数据..."
            />
          </div>
        </el-col>

        <el-col :span="12">
          <div class="output-section">
            <div class="section-title">脱敏结果</div>
            <el-input
              v-model="output"
              type="textarea"
              :rows="12"
              readonly
              placeholder="脱敏后的数据将显示在这里..."
            />
          </div>
        </el-col>
      </el-row>

      <el-divider>脱敏配置</el-divider>

      <el-form :model="config" label-width="120px">
        <el-row :gutter="20">
          <el-col :span="8">
            <el-form-item label="脱敏类型">
              <el-select v-model="config.type" style="width: 100%" @change="autoMask">
                <el-option label="手机号" value="phone" />
                <el-option label="身份证号" value="idCard" />
                <el-option label="银行卡号" value="bankCard" />
                <el-option label="邮箱" value="email" />
                <el-option label="姓名" value="name" />
                <el-option label="地址" value="address" />
                <el-option label="自定义" value="custom" />
              </el-select>
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="掩码字符">
              <el-input v-model="config.maskChar" maxlength="1" @change="autoMask" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="保留前N位">
              <el-input-number v-model="config.keepStart" :min="0" :max="20" style="width: 100%" @change="autoMask" />
            </el-form-item>
          </el-col>
        </el-row>

        <el-row :gutter="20" v-if="config.type === 'custom'">
          <el-col :span="8">
            <el-form-item label="保留后N位">
              <el-input-number v-model="config.keepEnd" :min="0" :max="20" style="width: 100%" @change="autoMask" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="正则表达式">
              <el-switch v-model="config.useRegex" @change="autoMask" />
            </el-form-item>
          </el-col>
          <el-col :span="8" v-if="config.useRegex">
            <el-form-item label="匹配模式">
              <el-input v-model="config.pattern" placeholder="输入正则表达式" @change="autoMask" />
            </el-form-item>
          </el-col>
        </el-row>

        <el-row :gutter="20">
          <el-col :span="24">
            <el-form-item label="批量处理">
              <el-switch v-model="config.batchMode" />
              <span class="help-text">（每行一个数据）</span>
            </el-form-item>
          </el-col>
        </el-row>
      </el-form>

      <div class="action-buttons">
        <el-button type="primary" @click="maskData">脱敏</el-button>
        <el-button @click="copyResult">复制结果</el-button>
        <el-button @click="clear">清空</el-button>
      </div>

      <el-divider>常用脱敏规则</el-divider>

      <el-table :data="rules" border size="small">
        <el-table-column prop="name" label="规则名称" width="150" />
        <el-table-column prop="pattern" label="匹配模式" width="200" />
        <el-table-column prop="example" label="示例" width="200">
          <template slot-scope="scope">
            <span>{{ scope.row.example }}</span>
            <i class="el-icon-arrow-right" style="margin: 0 8px; color: #909399;" />
            <span class="masked">{{ scope.row.masked }}</span>
          </template>
        </el-table-column>
        <el-table-column label="操作" width="100">
          <template slot-scope="scope">
            <el-button type="text" size="small" @click="applyRule(scope.row)">应用</el-button>
          </template>
        </el-table-column>
      </el-table>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'DataMaskTool',
  data() {
    return {
      input: '',
      output: '',
      config: {
        type: 'phone',
        maskChar: '*',
        keepStart: 3,
        keepEnd: 4,
        useRegex: false,
        pattern: '',
        batchMode: false
      },
      rules: [
        { name: '手机号', type: 'phone', pattern: '保留前3后4', example: '13812345678', masked: '138****5678' },
        { name: '身份证号', type: 'idCard', pattern: '保留前6后4', example: '110101199001011234', masked: '110101********1234' },
        { name: '银行卡号', type: 'bankCard', pattern: '保留前4后4', example: '6222021234567890123', masked: '6222***********0123' },
        { name: '邮箱', type: 'email', pattern: '保留首字符和@后', example: 'zhangsan@example.com', masked: 'z****@example.com' },
        { name: '姓名', type: 'name', pattern: '保留姓', example: '张三丰', masked: '张**' },
        { name: '地址', type: 'address', pattern: '保留省市区', example: '北京市朝阳区xxx街道123号', masked: '北京市朝阳区********' }
      ]
    }
  },
  methods: {
    maskData() {
      if (!this.input) {
        this.$message.warning('请输入需要脱敏的数据')
        return
      }

      if (this.config.batchMode) {
        const lines = this.input.split('\n').filter(line => line.trim())
        this.output = lines.map(line => this.maskSingle(line)).join('\n')
      } else {
        this.output = this.maskSingle(this.input)
      }
    },
    maskSingle(text) {
      if (this.config.useRegex && this.config.pattern) {
        try {
          const regex = new RegExp(this.config.pattern, 'g')
          return text.replace(regex, (match) => {
            return this.applyMask(match, this.config.keepStart, this.config.keepEnd)
          })
        } catch (e) {
          this.$message.error('正则表达式错误: ' + e.message)
          return text
        }
      }

      switch (this.config.type) {
        case 'phone':
          return this.maskPhone(text)
        case 'idCard':
          return this.maskIdCard(text)
        case 'bankCard':
          return this.maskBankCard(text)
        case 'email':
          return this.maskEmail(text)
        case 'name':
          return this.maskName(text)
        case 'address':
          return this.maskAddress(text)
        case 'custom':
          return this.applyMask(text, this.config.keepStart, this.config.keepEnd)
        default:
          return text
      }
    },
    maskPhone(phone) {
      const cleaned = phone.replace(/\D/g, '')
      if (cleaned.length !== 11) return phone
      return cleaned.slice(0, 3) + this.config.maskChar.repeat(4) + cleaned.slice(7)
    },
    maskIdCard(idCard) {
      const cleaned = idCard.replace(/\D/g, '')
      if (cleaned.length !== 18) return idCard
      return cleaned.slice(0, 6) + this.config.maskChar.repeat(8) + cleaned.slice(14)
    },
    maskBankCard(card) {
      const cleaned = card.replace(/\D/g, '')
      if (cleaned.length < 8) return card
      const showCount = cleaned.length - 8
      return cleaned.slice(0, 4) + this.config.maskChar.repeat(showCount) + cleaned.slice(-4)
    },
    maskEmail(email) {
      const atIndex = email.indexOf('@')
      if (atIndex === -1) return email
      const local = email.slice(0, atIndex)
      const domain = email.slice(atIndex)
      if (local.length <= 1) return email
      return local[0] + this.config.maskChar.repeat(local.length - 1) + domain
    },
    maskName(name) {
      if (name.length <= 1) return name
      return name[0] + this.config.maskChar.repeat(name.length - 1)
    },
    maskAddress(address) {
      // 简单实现：保留前6个字符
      if (address.length <= 6) return address
      return address.slice(0, 6) + this.config.maskChar.repeat(address.length - 6)
    },
    applyMask(text, keepStart, keepEnd) {
      if (text.length <= keepStart + keepEnd) return text
      const start = text.slice(0, keepStart)
      const end = text.slice(-keepEnd)
      const middleLength = text.length - keepStart - keepEnd
      return start + this.config.maskChar.repeat(middleLength) + end
    },
    autoMask() {
      if (this.input) {
        this.maskData()
      }
    },
    applyRule(rule) {
      this.config.type = rule.type
      switch (rule.type) {
        case 'phone':
          this.config.keepStart = 3
          this.config.keepEnd = 4
          break
        case 'idCard':
          this.config.keepStart = 6
          this.config.keepEnd = 4
          break
        case 'bankCard':
          this.config.keepStart = 4
          this.config.keepEnd = 4
          break
        case 'email':
        case 'name':
          this.config.keepStart = 1
          this.config.keepEnd = 0
          break
        case 'address':
          this.config.keepStart = 6
          this.config.keepEnd = 0
          break
      }
      this.$message.success(`已应用"${rule.name}"规则`)
      if (this.input) {
        this.maskData()
      }
    },
    copyResult() {
      if (!this.output) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.output).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    clear() {
      this.input = ''
      this.output = ''
    },
    loadExample() {
      this.config.batchMode = true
      this.config.type = 'phone'
      this.input = `13812345678
13987654321
15011112222
18666668888`
      this.maskData()
    }
  }
}
</script>

<style scoped>
.data-mask-tool {
  padding: 20px;
}

.section-title {
  font-weight: bold;
  margin-bottom: 10px;
  color: #606266;
}

.input-section, .output-section {
  margin-bottom: 20px;
}

.action-buttons {
  text-align: center;
  margin: 20px 0;
}

.help-text {
  margin-left: 10px;
  color: #909399;
  font-size: 12px;
}

.masked {
  color: #f56c6c;
  font-weight: bold;
}
</style>
