<template>
  <div class="csv-json-tool">
    <el-card>
      <div slot="header">
        <span>CSV/JSON 互转</span>
        <el-button size="small" @click="clear">清空当前</el-button>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ tab.title }}
          </span>

          <el-row :gutter="20">
            <el-col :span="11">
              <div class="section-header">
                <span>输入</span>
                <el-radio-group v-model="tab.inputFormat" size="small">
                  <el-radio-button label="csv">CSV</el-radio-button>
                  <el-radio-button label="json">JSON</el-radio-button>
                </el-radio-group>
              </div>
              <el-input
                v-model="tab.inputData"
                type="textarea"
                :rows="15"
                :placeholder="inputPlaceholder(tab)"
              />
            </el-col>

            <el-col :span="2" class="convert-buttons">
              <el-button type="primary" icon="el-icon-right" @click="convert(tab)" title="转换"></el-button>
            </el-col>

            <el-col :span="11">
              <div class="section-header">
                <span>输出</span>
                <el-radio-group v-model="tab.outputFormat" size="small">
                  <el-radio-button label="json">JSON</el-radio-button>
                  <el-radio-button label="csv">CSV</el-radio-button>
                </el-radio-group>
              </div>
              <el-input
                v-model="tab.outputData"
                type="textarea"
                :rows="15"
                readonly
                placeholder="转换结果..."
              />
            </el-col>
          </el-row>

          <el-divider>转换选项</el-divider>

          <el-form label-width="100px" v-if="tab.inputFormat === 'csv'">
            <el-row :gutter="20">
              <el-col :span="6">
                <el-form-item label="分隔符">
                  <el-select v-model="tab.options.delimiter" style="width: 100%">
                    <el-option label="逗号 (,)" value="," />
                    <el-option label="分号 (;)" value=";" />
                    <el-option label="制表符 (\\t)" value="\t" />
                    <el-option label="竖线 (|)" value="|" />
                  </el-select>
                </el-form-item>
              </el-col>
              <el-col :span="6">
                <el-form-item label="首行为标题">
                  <el-switch v-model="tab.options.header" />
                </el-form-item>
              </el-col>
              <el-col :span="6">
                <el-form-item label="跳过空行">
                  <el-switch v-model="tab.options.skipEmptyLines" />
                </el-form-item>
              </el-col>
              <el-col :span="6">
                <el-form-item label="自动类型转换">
                  <el-switch v-model="tab.options.autoType" />
                </el-form-item>
              </el-col>
            </el-row>
          </el-form>

          <el-form label-width="100px" v-else>
            <el-row :gutter="20">
              <el-col :span="6">
                <el-form-item label="分隔符">
                  <el-select v-model="tab.options.delimiter" style="width: 100%">
                    <el-option label="逗号 (,)" value="," />
                    <el-option label="分号 (;)" value=";" />
                    <el-option label="制表符 (\\t)" value="\t" />
                    <el-option label="竖线 (|)" value="|" />
                  </el-select>
                </el-form-item>
              </el-col>
              <el-col :span="6">
                <el-form-item label="包含标题">
                  <el-switch v-model="tab.options.header" />
                </el-form-item>
              </el-col>
              <el-col :span="6">
                <el-form-item label="引号包裹">
                  <el-switch v-model="tab.options.quote" />
                </el-form-item>
              </el-col>
            </el-row>
          </el-form>

          <div class="action-buttons">
            <el-button type="primary" @click="convert(tab)">转换</el-button>
            <el-button @click="copyOutput(tab)">复制结果</el-button>
            <el-button @click="downloadOutput(tab)">下载文件</el-button>
            <el-button @click="loadExample(tab)">加载示例</el-button>
            <el-button @click="clear">清空</el-button>
          </div>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CsvJsonTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: 'CSV⇄JSON ' + seq,
        inputFormat: 'csv',
        outputFormat: 'json',
        inputData: '',
        outputData: '',
        options: {
          delimiter: ',',
          header: true,
          skipEmptyLines: true,
          autoType: true,
          quote: true
        }
      }
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clear()
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },
    inputPlaceholder(tab) {
      return tab.inputFormat === 'csv'
        ? '输入 CSV 数据...\n例如:\nname,age,city\nJohn,30,New York\nJane,25,Los Angeles'
        : '输入 JSON 数据...\n例如:\n[{"name":"John","age":30,"city":"New York"}]'
    },
    convert(tab) {
      if (!tab.inputData) {
        this.$message.warning('请输入数据')
        return
      }

      try {
        if (tab.inputFormat === 'csv' && tab.outputFormat === 'json') {
          this.csvToJson(tab)
        } else if (tab.inputFormat === 'json' && tab.outputFormat === 'csv') {
          this.jsonToCsv(tab)
        } else {
          tab.outputData = tab.inputData
        }
        this.$message.success('转换成功')
      } catch (e) {
        this.$message.error('转换失败: ' + e.message)
      }
    },
    csvToJson(tab) {
      const lines = tab.inputData.split('\n')
      const result = []
      let headers = []

      const startIndex = tab.options.header ? 1 : 0

      if (tab.options.header && lines.length > 0) {
        headers = this.parseCSVLine(tab, lines[0])
      }

      for (let i = startIndex; i < lines.length; i++) {
        const line = lines[i].trim()
        if (tab.options.skipEmptyLines && !line) continue

        const values = this.parseCSVLine(tab, line)
        const obj = {}

        if (tab.options.header) {
          headers.forEach((header, index) => {
            let value = values[index] || ''
            if (tab.options.autoType) {
              value = this.convertType(value)
            }
            obj[header] = value
          })
        } else {
          values.forEach((value, index) => {
            let val = value
            if (tab.options.autoType) {
              val = this.convertType(val)
            }
            obj[`col${index}`] = val
          })
        }

        result.push(obj)
      }

      tab.outputData = JSON.stringify(result, null, 2)
    },
    parseCSVLine(tab, line) {
      const result = []
      let current = ''
      let inQuotes = false

      for (let i = 0; i < line.length; i++) {
        const char = line[i]
        const nextChar = line[i + 1]

        if (inQuotes) {
          if (char === '"') {
            if (nextChar === '"') {
              current += '"'
              i++
            } else {
              inQuotes = false
            }
          } else {
            current += char
          }
        } else {
          if (char === '"') {
            inQuotes = true
          } else if (char === tab.options.delimiter) {
            result.push(current.trim())
            current = ''
          } else {
            current += char
          }
        }
      }

      result.push(current.trim())
      return result
    },
    convertType(value) {
      if (value === '') return null
      if (value === 'true') return true
      if (value === 'false') return false
      if (!isNaN(value) && value !== '') {
        return value.includes('.') ? parseFloat(value) : parseInt(value)
      }
      return value
    },
    jsonToCsv(tab) {
      const json = JSON.parse(tab.inputData)
      const array = Array.isArray(json) ? json : [json]

      if (array.length === 0) {
        tab.outputData = ''
        return
      }

      const headers = Object.keys(array[0])
      let csv = ''

      if (tab.options.header) {
        csv += headers.map(h => this.quoteValue(tab, h)).join(tab.options.delimiter) + '\n'
      }

      for (const item of array) {
        const values = headers.map(h => {
          let value = item[h]
          if (value === null || value === undefined) {
            value = ''
          } else if (typeof value === 'object') {
            value = JSON.stringify(value)
          }
          return this.quoteValue(tab, String(value))
        })
        csv += values.join(tab.options.delimiter) + '\n'
      }

      tab.outputData = csv.trim()
    },
    quoteValue(tab, value) {
      if (!tab.options.quote) return value
      if (value.includes(tab.options.delimiter) || value.includes('"') || value.includes('\n')) {
        return '"' + value.replace(/"/g, '""') + '"'
      }
      return value
    },
    copyOutput(tab) {
      if (!tab.outputData) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(tab.outputData).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    downloadOutput(tab) {
      if (!tab.outputData) {
        this.$message.warning('没有可下载的内容')
        return
      }
      const filename = tab.outputFormat === 'json' ? 'data.json' : 'data.csv'
      const blob = new Blob([tab.outputData], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = filename
      link.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    loadExample(tab) {
      if (tab.inputFormat === 'csv') {
        tab.inputData = `name,age,city,email
John,30,New York,john@example.com
Jane,25,Los Angeles,jane@example.com
Bob,35,Chicago,bob@example.com`
      } else {
        tab.inputData = `[
  {"name": "John", "age": 30, "city": "New York", "email": "john@example.com"},
  {"name": "Jane", "age": 25, "city": "Los Angeles", "email": "jane@example.com"},
  {"name": "Bob", "age": 35, "city": "Chicago", "email": "bob@example.com"}
]`
      }
    },
    clear() {
      const tab = this.currentTab()
      if (!tab) return
      tab.inputData = ''
      tab.outputData = ''
    }
  }
}
</script>

<style scoped>
.csv-json-tool {
  padding: 20px;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.convert-buttons {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 10px;
}

.action-buttons {
  text-align: center;
  margin-top: 20px;
}
</style>
