<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>Java 代码格式化</span>
        <el-button size="small" @click="clear">清空当前</el-button>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ tab.title }}
          </span>

          <el-row :gutter="20">
            <el-col :span="24">
              <div class="input-section">
                <div class="section-header">
                  <span>Java 代码</span>
                  <el-tag size="mini" type="info">输入或粘贴 Java 代码，点击按钮格式化</el-tag>
                </div>
                <el-input
                  v-model="tab.javaCode"
                  type="textarea"
                  :rows="15"
                  placeholder="输入 Java 代码，如: public class Main { public static void main(String[] args) { } }"
                />
              </div>
            </el-col>
          </el-row>

          <el-row style="margin-top: 15px">
            <el-col :span="24" class="action-row">
              <el-radio-group v-model="tab.indent" size="small">
                <el-radio-button :label="2">2空格</el-radio-button>
                <el-radio-button :label="4">4空格</el-radio-button>
                <el-radio-button :label="1">Tab</el-radio-button>
              </el-radio-group>

              <div class="action-buttons">
                <el-button type="primary" @click="format(tab)">格式化</el-button>
                <el-button type="warning" @click="compress(tab)">压缩</el-button>
                <el-button @click="copy(tab)">复制</el-button>
              </div>
            </el-col>
          </el-row>

          <el-row style="margin-top: 15px" v-if="tab.stats">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">代码统计</div>
                <el-descriptions :column="4" border size="small">
                  <el-descriptions-item label="行数">{{ tab.stats.lines }}</el-descriptions-item>
                  <el-descriptions-item label="字符数">{{ tab.stats.chars }}</el-descriptions-item>
                  <el-descriptions-item label="类数">{{ tab.stats.classes }}</el-descriptions-item>
                  <el-descriptions-item label="方法数">{{ tab.stats.methods }}</el-descriptions-item>
                </el-descriptions>
              </el-card>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'JavaFormatTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: 'Java ' + seq,
        javaCode: '',
        indent: 4,
        stats: null
      }
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clear()
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },
    format(tab) {
      if (!tab.javaCode.trim()) {
        this.$message.warning('请输入 Java 代码')
        return
      }

      try {
        tab.javaCode = this.formatJava(tab.javaCode, tab.indent)
        this.updateStats(tab)
        this.$message.success('格式化成功')
      } catch (e) {
        this.$message.error('格式化失败: ' + e.message)
      }
    },
    formatJava(code, indent) {
      const PADDING = indent === 1 ? '\t' : ' '.repeat(indent)

      code = code.replace(/\s+/g, ' ')

      code = code.replace(/\s*([{};])\s*/g, '$1\n')
      code = code.replace(/\s*\(\s*/g, '(')
      code = code.replace(/\s*\)\s*/g, ')')
      code = code.replace(/\s*,\s*/g, ', ')

      const keywords = ['public', 'private', 'protected', 'static', 'final', 'class', 'interface', 'enum', 'void', 'int', 'String', 'boolean', 'return', 'if', 'else', 'for', 'while', 'do', 'switch', 'case', 'break', 'continue', 'try', 'catch', 'finally', 'throw', 'throws', 'new', 'this', 'super', 'import', 'package', 'extends', 'implements']

      keywords.forEach(kw => {
        const regex = new RegExp('\\b' + kw + '\\b', 'g')
        code = code.replace(regex, kw)
      })

      let result = []
      let level = 0
      let lines = code.split('\n')

      lines.forEach(line => {
        line = line.trim()
        if (!line) return

        if (line.startsWith('}')) {
          level = Math.max(0, level - 1)
        }

        result.push(PADDING.repeat(level) + line)

        const openBraces = (line.match(/{/g) || []).length
        const closeBraces = (line.match(/}/g) || []).length
        level += openBraces - closeBraces
        level = Math.max(0, level)
      })

      return result.join('\n')
    },
    compress(tab) {
      if (!tab.javaCode.trim()) {
        this.$message.warning('请输入 Java 代码')
        return
      }

      tab.javaCode = tab.javaCode
        .replace(/\n/g, ' ')
        .replace(/\s{2,}/g, ' ')
        .replace(/\s*([{}();,])\s*/g, '$1')
        .replace(/\s+/g, ' ')
        .trim()
      this.updateStats(tab)
      this.$message.success('压缩成功')
    },
    updateStats(tab) {
      const classMatches = tab.javaCode.match(/\bclass\s+\w+/g) || []
      const methodMatches = tab.javaCode.match(/\b(public|private|protected|static)\s+\w+\s+\w+\s*\(/g) || []

      tab.stats = {
        lines: tab.javaCode.split('\n').length,
        chars: tab.javaCode.length,
        classes: classMatches.length,
        methods: methodMatches.length
      }
    },
    copy(tab) {
      if (!tab.javaCode) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(tab.javaCode).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    clear() {
      const tab = this.currentTab()
      if (!tab) return
      tab.javaCode = ''
      tab.stats = null
    }
  }
}
</script>

