<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>英文词典查询</span>
        <span style="font-size:12px;color:#909399;margin-left:10px">数据来源: Free Dictionary API</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="24">
          <el-input
            v-model="word"
            placeholder="输入英文单词..."
            size="large"
            clearable
            @keyup.enter.native="search"
          >
            <el-button slot="append" type="primary" icon="el-icon-search" @click="search" :loading="loading">
              查询
            </el-button>
          </el-input>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 15px" v-if="!result && !loading && !error">
        <el-col :span="24">
          <div class="quick-words">
            <span style="color:#909399;margin-right:10px">试试这些词：</span>
            <el-tag
              v-for="w in sampleWords"
              :key="w"
              style="cursor:pointer;margin:3px"
              @click.native="word = w; search()"
            >{{ w }}</el-tag>
          </div>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 20px" v-if="result">
        <el-col :span="24">
          <el-card shadow="never" class="word-header">
            <div class="word-title">
              <h2>{{ result.word }}</h2>
              <span v-if="result.phonetic" class="phonetic">{{ result.phonetic }}</span>
              <el-button
                v-if="result.phoneticAudio"
                type="text"
                icon="el-icon-video-play"
                @click="playAudio(result.phoneticAudio)"
                size="small"
              >发音</el-button>
            </div>
          </el-card>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 10px" v-if="result">
        <el-col
          :span="12"
          v-for="(meaning, mi) in result.meanings"
          :key="mi"
          style="margin-bottom: 15px"
        >
          <el-card shadow="never" class="meaning-card">
            <div slot="header">
              <el-tag type="primary">{{ meaning.partOfSpeech }}</el-tag>
            </div>
            <ol class="definition-list">
              <li v-for="(def, di) in meaning.definitions" :key="di" class="definition-item">
                <p class="def-text">{{ def.definition }}</p>
                <p v-if="def.example" class="def-example">
                  <i class="el-icon-document"></i>
                  {{ def.example }}
                </p>
                <div v-if="def.synonyms && def.synonyms.length > 0" style="margin-top: 5px">
                  <span style="color:#909399;font-size:12px">同义词：</span>
                  <el-tag
                    v-for="syn in def.synonyms.slice(0, 6)"
                    :key="syn"
                    size="mini"
                    style="margin:2px"
                    @click.native="word = syn; search()"
                  >{{ syn }}</el-tag>
                </div>
                <div v-if="def.antonyms && def.antonyms.length > 0" style="margin-top: 5px">
                  <span style="color:#909399;font-size:12px">反义词：</span>
                  <el-tag
                    v-for="ant in def.antonyms.slice(0, 6)"
                    :key="ant"
                    size="mini"
                    type="danger"
                    style="margin:2px"
                    @click.native="word = ant; search()"
                  >{{ ant }}</el-tag>
                </div>
              </li>
            </ol>
          </el-card>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 10px" v-if="result && result.sourceUrls && result.sourceUrls.length > 0">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">参考来源</div>
            <a
              v-for="url in result.sourceUrls"
              :key="url"
              :href="url"
              target="_blank"
              style="display:block;font-size:12px;color:#409EFF;margin-bottom:4px"
            >{{ url }}</a>
          </el-card>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 20px" v-if="error">
        <el-col :span="24">
          <el-alert :title="error" type="error" show-icon :closable="false" />
        </el-col>
      </el-row>

      <el-divider v-if="history.length > 0">查询历史</el-divider>
      <div v-if="history.length > 0" style="margin-top:10px">
        <el-tag
          v-for="(w, i) in history"
          :key="i"
          style="cursor:pointer;margin:3px"
          @click.native="word = w; search()"
        >{{ w }}</el-tag>
      </div>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'DictionaryTool',
  data() {
    return {
      word: '',
      result: null,
      loading: false,
      error: '',
      history: [],
      sampleWords: ['serendipity', 'algorithm', 'elegant', 'resilient', 'paradigm', 'eloquent', 'ubiquitous', 'pragmatic'],
    }
  },
  methods: {
    async search() {
      const w = this.word.trim()
      if (!w) {
        this.$message.warning('请输入单词')
        return
      }

      this.loading = true
      this.error = ''
      this.result = null

      try {
        const res = await fetch(`https://api.dictionaryapi.dev/api/v2/entries/en/${encodeURIComponent(w)}`)
        if (res.status === 404) {
          this.error = `未找到单词 "${w}" 的定义`
          return
        }
        if (!res.ok) throw new Error(`请求失败 (${res.status})`)

        const data = await res.json()
        const entry = data[0]

        this.result = {
          word: entry.word || w,
          phonetic: entry.phonetic || '',
          phoneticAudio: (entry.phonetics || []).find(p => p.audio)?.audio || '',
          meanings: (entry.meanings || []).map(m => ({
            partOfSpeech: m.partOfSpeech || '-',
            definitions: (m.definitions || []).slice(0, 5).map(d => ({
              definition: d.definition || '',
              example: d.example || '',
              synonyms: d.synonyms || [],
              antonyms: d.antonyms || [],
            })),
          })),
          sourceUrls: entry.sourceUrls || [],
        }

        // 添加到历史记录
        this.history = [w, ...this.history.filter(h => h !== w)].slice(0, 10)
      } catch (e) {
        this.error = '查询失败: ' + e.message
      } finally {
        this.loading = false
      }
    },
    playAudio(url) {
      const audio = new Audio(url)
      audio.play().catch(() => this.$message.warning('无法播放发音'))
    }
  }
}
</script>

