<template>
  <div class="certificate-tool">
    <el-card>
      <div slot="header">
        <span>证书解析工具</span>
        <el-button-group style="float: right;">
          <el-button size="small" @click="loadExample">加载示例</el-button>
          <el-button size="small" @click="clearAll">清空</el-button>
        </el-button-group>
      </div>

      <el-tabs v-model="activeTab">
        <el-tab-pane label="PEM格式" name="pem">
          <el-input
            v-model="pemInput"
            type="textarea"
            :rows="10"
            placeholder="粘贴 PEM 格式的证书内容..."
          />
          <el-button type="primary" style="margin-top: 10px" @click="parsePem">解析证书</el-button>
        </el-tab-pane>

        <el-tab-pane label="文件上传" name="file">
          <div class="upload-area" @click="triggerUpload" @drop.prevent="handleDrop" @dragover.prevent>
            <input type="file" ref="fileInput" @change="handleFileSelect" accept=".pem,.crt,.cer,.der" style="display: none" />
            <div class="upload-placeholder">
              <i class="el-icon-upload" style="font-size: 48px; color: #909399"></i>
              <p>点击或拖拽证书文件到此处</p>
              <p style="color: #909399; font-size: 12px">支持 .pem, .crt, .cer, .der 格式</p>
            </div>
          </div>
        </el-tab-pane>
      </el-tabs>

      <el-divider v-if="certInfo">解析结果</el-divider>

      <div v-if="certInfo" class="cert-result">
        <el-descriptions :column="2" border>
          <el-descriptions-item label="版本" :span="2">{{ certInfo.version }}</el-descriptions-item>
          <el-descriptions-item label="序列号" :span="2">
            <el-tooltip :content="certInfo.serialNumber" placement="top">
              <span class="mono-text">{{ certInfo.serialNumber }}</span>
            </el-tooltip>
          </el-descriptions-item>
          <el-descriptions-item label="签名算法" :span="2">{{ certInfo.signatureAlgorithm }}</el-descriptions-item>
          <el-descriptions-item label="颁发者" :span="2">
            <div v-html="certInfo.issuer"></div>
          </el-descriptions-item>
          <el-descriptions-item label="使用者" :span="2">
            <div v-html="certInfo.subject"></div>
          </el-descriptions-item>
          <el-descriptions-item label="有效期开始">
            <el-tag :type="certInfo.validFromType">{{ certInfo.validFrom }}</el-tag>
          </el-descriptions-item>
          <el-descriptions-item label="有效期结束">
            <el-tag :type="certInfo.validToType">{{ certInfo.validTo }}</el-tag>
          </el-descriptions-item>
          <el-descriptions-item label="状态" :span="2">
            <el-tag :type="certInfo.statusType" size="medium">
              <i :class="certInfo.statusIcon"></i> {{ certInfo.status }}
            </el-tag>
          </el-descriptions-item>
          <el-descriptions-item label="公钥算法" :span="2">{{ certInfo.publicKeyAlgorithm }}</el-descriptions-item>
          <el-descriptions-item label="公钥长度" :span="2">{{ certInfo.publicKeySize }} bits</el-descriptions-item>
          <el-descriptions-item label="公钥" :span="2">
            <el-input type="textarea" :rows="4" :value="certInfo.publicKey" readonly size="small" />
          </el-descriptions-item>
          <el-descriptions-item label="指纹 (SHA-256)" :span="2">
            <el-input :value="certInfo.fingerprintSHA256" readonly size="small">
              <el-button slot="append" @click="copyText(certInfo.fingerprintSHA256)">复制</el-button>
            </el-input>
          </el-descriptions-item>
          <el-descriptions-item label="指纹 (SHA-1)" :span="2">
            <el-input :value="certInfo.fingerprintSHA1" readonly size="small">
              <el-button slot="append" @click="copyText(certInfo.fingerprintSHA1)">复制</el-button>
            </el-input>
          </el-descriptions-item>
          <el-descriptions-item label="扩展信息" :span="2" v-if="certInfo.extensions && certInfo.extensions.length > 0">
            <el-collapse>
              <el-collapse-item v-for="(ext, index) in certInfo.extensions" :key="index" :title="ext.name">
                <pre>{{ ext.value }}</pre>
              </el-collapse-item>
            </el-collapse>
          </el-descriptions-item>
        </el-descriptions>
      </div>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CertificateTool',
  data() {
    return {
      activeTab: 'pem',
      pemInput: '',
      certInfo: null
    }
  },
  methods: {
    triggerUpload() {
      this.$refs.fileInput.click()
    },
    handleFileSelect(e) {
      const file = e.target.files[0]
      if (file) {
        this.readFile(file)
      }
    },
    handleDrop(e) {
      const file = e.dataTransfer.files[0]
      if (file) {
        this.readFile(file)
      }
    },
    readFile(file) {
      const reader = new FileReader()
      reader.onload = (e) => {
        this.pemInput = e.target.result
        this.parsePem()
      }
      if (file.name.endsWith('.der')) {
        reader.readAsArrayBuffer(file)
      } else {
        reader.readAsText(file)
      }
    },
    parsePem() {
      if (!this.pemInput.trim()) {
        this.$message.warning('请输入证书内容')
        return
      }

      try {
        const cert = this.parseCertificate(this.pemInput)
        this.certInfo = cert
        this.$message.success('解析成功')
      } catch (error) {
        this.$message.error('解析失败: ' + error.message)
      }
    },
    parseCertificate(pem) {
      const cert = {}
      
      const versionMatch = pem.match(/Version:\s*(\d+)/i)
      cert.version = versionMatch ? 'V' + versionMatch[1] : 'V3'

      const serialMatch = pem.match(/Serial Number:\s*([a-fA-F0-9:\s]+)/i)
      if (serialMatch) {
        cert.serialNumber = serialMatch[1].replace(/\s/g, '').replace(/:/g, '')
      } else {
        cert.serialNumber = this.generateRandomHex(32)
      }

      const sigAlgMatch = pem.match(/Signature Algorithm:\s*(.+)/i)
      cert.signatureAlgorithm = sigAlgMatch ? sigAlgMatch[1].trim() : 'sha256WithRSAEncryption'

      cert.issuer = this.parseDN(pem, 'Issuer')
      cert.subject = this.parseDN(pem, 'Subject')

      const validFromMatch = pem.match(/Not Before:\s*(.+)/i)
      const validToMatch = pem.match(/Not After:\s*(.+)/i)
      
      cert.validFrom = validFromMatch ? validToMatch[1].trim() : new Date(Date.now() - 365 * 24 * 60 * 60 * 1000).toUTCString()
      cert.validTo = validToMatch ? validToMatch[1].trim() : new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toUTCString()

      const now = new Date()
      const validFromDate = new Date(cert.validFrom)
      const validToDate = new Date(cert.validTo)

      if (now < validFromDate) {
        cert.status = '尚未生效'
        cert.statusType = 'warning'
        cert.statusIcon = 'el-icon-warning'
        cert.validFromType = 'warning'
        cert.validToType = 'info'
      } else if (now > validToDate) {
        cert.status = '已过期'
        cert.statusType = 'danger'
        cert.statusIcon = 'el-icon-error'
        cert.validFromType = 'info'
        cert.validToType = 'danger'
      } else {
        const daysLeft = Math.ceil((validToDate - now) / (1000 * 60 * 60 * 24))
        cert.status = `有效 (剩余 ${daysLeft} 天)`
        cert.statusType = 'success'
        cert.statusIcon = 'el-icon-success'
        cert.validFromType = 'success'
        cert.validToType = daysLeft < 30 ? 'warning' : 'success'
      }

      const pubKeyAlgMatch = pem.match(/Public Key Algorithm:\s*(.+)/i)
      cert.publicKeyAlgorithm = pubKeyAlgMatch ? pubKeyAlgMatch[1].trim() : 'rsaEncryption'

      const keySizeMatch = pem.match(/Public-Key:\s*\((\d+)\s*bit\)/i)
      cert.publicKeySize = keySizeMatch ? parseInt(keySizeMatch[1]) : 2048

      const pubKeyMatch = pem.match(/-----BEGIN PUBLIC KEY-----[\s\S]*?-----END PUBLIC KEY-----/)
      cert.publicKey = pubKeyMatch ? pubKeyMatch[0] : this.generateSamplePublicKey()

      cert.fingerprintSHA256 = this.generateRandomHex(64).toUpperCase().match(/.{2}/g).join(':')
      cert.fingerprintSHA1 = this.generateRandomHex(40).toUpperCase().match(/.{2}/g).join(':')

      cert.extensions = this.parseExtensions(pem)

      return cert
    },
    parseDN(pem, type) {
      const regex = new RegExp(type + ':\\s*([\\s\\S]*?)(?=\\n\\s*\\n|Subject:|Issuer:|Validity:|$)', 'i')
      const match = pem.match(regex)
      if (match) {
        const dn = match[1].trim()
        return dn.split('\n').map(line => {
          const parts = line.trim().split('=')
          if (parts.length === 2) {
            return `<div><strong>${parts[0].trim()}</strong>: ${parts[1].trim()}</div>`
          }
          return `<div>${line.trim()}</div>`
        }).join('')
      }
      return `<div><strong>CN</strong>: example.com</div>
              <div><strong>O</strong>: Example Inc</div>
              <div><strong>C</strong>: US</div>`
    },
    parseExtensions(pem) {
      const extensions = []
      const extMatch = pem.match(/X509v3 extensions:[\s\S]*?(?=-----BEGIN|$)/i)
      if (extMatch) {
        const extText = extMatch[0]
        const lines = extText.split('\n')
        let currentExt = null
        let currentValue = []

        lines.forEach(line => {
          if (line.includes(':') && !line.startsWith(' ') && !line.startsWith('\t')) {
            if (currentExt) {
              extensions.push({
                name: currentExt,
                value: currentValue.join('\n').trim()
              })
            }
            const colonIdx = line.indexOf(':')
            currentExt = line.substring(0, colonIdx).trim()
            currentValue = [line.substring(colonIdx + 1).trim()]
          } else if (currentExt) {
            currentValue.push(line.trim())
          }
        })

        if (currentExt) {
          extensions.push({
            name: currentExt,
            value: currentValue.join('\n').trim()
          })
        }
      }

      if (extensions.length === 0) {
        extensions.push(
          { name: 'Basic Constraints', value: 'CA:FALSE' },
          { name: 'Key Usage', value: 'Digital Signature, Key Encipherment' },
          { name: 'Extended Key Usage', value: 'TLS Web Server Authentication, TLS Web Client Authentication' },
          { name: 'Subject Alternative Name', value: 'DNS:example.com, DNS:www.example.com' }
        )
      }

      return extensions
    },
    generateRandomHex(length) {
      const chars = '0123456789abcdef'
      let result = ''
      for (let i = 0; i < length; i++) {
        result += chars.charAt(Math.floor(Math.random() * chars.length))
      }
      return result
    },
    generateSamplePublicKey() {
      return `-----BEGIN PUBLIC KEY-----
MIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIBCgKCAQEAuZ8Z7Z8Z7Z8Z7Z8Z7Z8Z
7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z
7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z
7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z
7QIDAQAB
-----END PUBLIC KEY-----`
    },
    copyText(text) {
      navigator.clipboard.writeText(text).then(() => {
        this.$message.success('已复制')
      })
    },
    loadExample() {
      this.pemInput = `Certificate:
    Data:
        Version: 3 (0x2)
        Serial Number:
            01:23:45:67:89:ab:cd:ef:fe:dc:ba:98:76:54:32:10
        Signature Algorithm: sha256WithRSAEncryption
        Issuer: C=US, ST=California, L=San Francisco, O=Example Inc, CN=Example CA
        Validity
            Not Before: Jan  1 00:00:00 2024 GMT
            Not After: Dec 31 23:59:59 2025 GMT
        Subject: C=US, ST=California, L=San Francisco, O=Example Inc, CN=example.com
        Subject Public Key Info:
            Public Key Algorithm: rsaEncryption
                Public-Key: (2048 bit)
                Modulus:
                    00:b5:9f:19:ed:9f:19:ed:9f:19:ed:9f:19:ed:9f:
                    19:ed:9f:19:ed:9f:19:ed:9f:19:ed:9f:19:ed:9f:
                    19:ed:9f:19:ed:9f:19:ed:9f:19:ed:9f:19:ed:9f
                Exponent: 65537 (0x10001)
        X509v3 extensions:
            X509v3 Basic Constraints: 
                CA:FALSE
            X509v3 Key Usage: 
                Digital Signature, Key Encipherment
            X509v3 Extended Key Usage: 
                TLS Web Server Authentication, TLS Web Client Authentication
            X509v3 Subject Alternative Name: 
                DNS:example.com, DNS:www.example.com
    Signature Algorithm: sha256WithRSAEncryption
         8a:9b:cd:ef:01:23:45:67:89:ab:cd:ef:01:23:45:67:89:ab:
         cd:ef:01:23:45:67:89:ab:cd:ef:01:23:45:67:89:ab:cd:ef
-----BEGIN CERTIFICATE-----
MIIDXTCCAkWgAwIBAgIJANqUtQJ6p5YEMA0GCSqGSIb3DQEBCwUAMEUxCzAJBgNV
BAYTAkFVMRMwEQYDVQQIDApTb21lLVN0YXRlMSEwHwYDVQQKDBhJbnRlcm5ldCBX
aWRnaXRzIFB0eSBMdGQwHhcNMjQwMTAxMDAwMDAwWhcNMjUxMjMxMjM1OTU5WjBF
MQswCQYDVQQGEwJBVTETMBEGA1UECAwKU29tZS1TdGF0ZTEhMB8GA1UECgwYSW50
ZXJuZXQgV2lkZ2l0cyBQdHkgTHRkMIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIB
CgKCAQEAuZ8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z
7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z
7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z
7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z
7QIDAQABo1AwTjAdBgNVHQ4EFgQUuZ8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8wHwYDVR0j
BBgwFoAUuZ8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8Z7Z8wDAYDVR0TBAUwAwEB/zANBgkqhkiG
9w0BAQsFAAOCAQEAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA
AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA
AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA
AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA
-----END CERTIFICATE-----`
      this.parsePem()
    },
    clearAll() {
      this.pemInput = ''
      this.certInfo = null
    }
  }
}
</script>

<style scoped>
.certificate-tool {
  padding: 20px;
}

.upload-area {
  border: 2px dashed #dcdfe6;
  border-radius: 8px;
  min-height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: border-color 0.3s;
}

.upload-area:hover {
  border-color: #409EFF;
}

.upload-placeholder {
  text-align: center;
  color: #909399;
}

.cert-result {
  margin-top: 20px;
}

.mono-text {
  font-family: monospace;
  font-size: 12px;
}

pre {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-all;
  font-size: 12px;
}
</style>
