<template>
  <div class="code-minifier-tool">
    <el-card>
      <div slot="header">
        <span>代码压缩工具</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="loadExample">加载示例</el-button>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <div class="input-section">
            <div class="section-header">
              <span class="section-title">原始代码</span>
              <div class="section-actions">
                <el-select v-model="language" size="small" style="width: 120px" @change="clear">
                  <el-option label="JavaScript" value="javascript" />
                  <el-option label="CSS" value="css" />
                  <el-option label="HTML" value="html" />
                  <el-option label="JSON" value="json" />
                  <el-option label="SQL" value="sql" />
                </el-select>
              </div>
            </div>
            <el-input
              v-model="input"
              type="textarea"
              :rows="20"
              placeholder="粘贴需要压缩的代码..."
            />
          </div>
        </el-col>

        <el-col :span="12">
          <div class="output-section">
            <div class="section-header">
              <span class="section-title">压缩结果</span>
              <div class="section-actions">
                <el-button type="text" size="small" @click="copyOutput">复制</el-button>
                <el-button type="text" size="small" @click="downloadOutput">下载</el-button>
              </div>
            </div>
            <el-input
              v-model="output"
              type="textarea"
              :rows="20"
              readonly
              placeholder="压缩后的代码将显示在这里..."
            />
          </div>
        </el-col>
      </el-row>

      <el-divider>压缩选项</el-divider>

      <el-form :model="options" label-width="150px">
        <el-row :gutter="20">
          <el-col :span="8">
            <el-form-item label="移除注释">
              <el-switch v-model="options.removeComments" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="移除空白">
              <el-switch v-model="options.removeWhitespace" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="压缩变量名">
              <el-switch v-model="options.mangleNames" :disabled="language !== 'javascript'" />
            </el-form-item>
          </el-col>
        </el-row>
        <el-row :gutter="20">
          <el-col :span="8">
            <el-form-item label="移除console">
              <el-switch v-model="options.removeConsole" :disabled="language !== 'javascript'" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="合并文件">
              <el-switch v-model="options.mergeFiles" disabled />
              <span class="help-text">（暂不支持）</span>
            </el-form-item>
          </el-col>
        </el-row>
      </el-form>

      <div class="action-buttons">
        <el-button type="primary" @click="minify">压缩代码</el-button>
        <el-button @click="clear">清空</el-button>
      </div>

      <div class="stats-section" v-if="stats.originalSize > 0">
        <el-row :gutter="20">
          <el-col :span="6">
            <div class="stat-item">
              <div class="stat-label">原始大小</div>
              <div class="stat-value">{{ formatSize(stats.originalSize) }}</div>
            </div>
          </el-col>
          <el-col :span="6">
            <div class="stat-item">
              <div class="stat-label">压缩后大小</div>
              <div class="stat-value">{{ formatSize(stats.minifiedSize) }}</div>
            </div>
          </el-col>
          <el-col :span="6">
            <div class="stat-item">
              <div class="stat-label">节省空间</div>
              <div class="stat-value">{{ formatSize(stats.saved) }}</div>
            </div>
          </el-col>
          <el-col :span="6">
            <div class="stat-item">
              <div class="stat-label">压缩率</div>
              <div class="stat-value" :class="{ 'good': stats.ratio > 30 }">{{ stats.ratio.toFixed(1) }}%</div>
            </div>
          </el-col>
        </el-row>
      </div>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CodeMinifierTool',
  data() {
    return {
      language: 'javascript',
      input: '',
      output: '',
      options: {
        removeComments: true,
        removeWhitespace: true,
        mangleNames: false,
        removeConsole: false,
        mergeFiles: false
      },
      stats: {
        originalSize: 0,
        minifiedSize: 0,
        saved: 0,
        ratio: 0
      }
    }
  },
  methods: {
    minify() {
      if (!this.input) {
        this.$message.warning('请输入代码')
        return
      }

      this.stats.originalSize = new Blob([this.input]).size
      let result = this.input

      switch (this.language) {
        case 'javascript':
          result = this.minifyJavaScript(result)
          break
        case 'css':
          result = this.minifyCss(result)
          break
        case 'html':
          result = this.minifyHtml(result)
          break
        case 'json':
          result = this.minifyJson(result)
          break
        case 'sql':
          result = this.minifySql(result)
          break
      }

      this.output = result
      this.stats.minifiedSize = new Blob([result]).size
      this.stats.saved = this.stats.originalSize - this.stats.minifiedSize
      this.stats.ratio = (this.stats.saved / this.stats.originalSize) * 100
    },
    minifyJavaScript(code) {
      let result = code

      if (this.options.removeComments) {
        // Remove single-line comments
        result = result.replace(/\/\/.*$/gm, '')
        // Remove multi-line comments
        result = result.replace(/\/\*[\s\S]*?\*\//g, '')
      }

      if (this.options.removeConsole) {
        result = result.replace(/console\.(log|warn|error|info|debug)\([^)]*\);?/g, '')
      }

      if (this.options.removeWhitespace) {
        // Remove extra whitespace while preserving necessary spaces
        result = result.replace(/\s+/g, ' ')
        // Remove spaces around operators and punctuation
        result = result.replace(/\s*([{}();,:])\s*/g, '$1')
        result = result.replace(/\s*([=+\-*/%<>!&|])\s*/g, '$1')
        // Trim
        result = result.trim()
      }

      if (this.options.mangleNames) {
        // Simple variable name mangling (basic implementation)
        const varNames = new Set()
        const varRegex = /\b(var|let|const|function)\s+(\w+)/g
        let match
        while ((match = varRegex.exec(result)) !== null) {
          varNames.add(match[2])
        }
        
        let counter = 0
        varNames.forEach(name => {
          if (name.length > 2) {
            const mangled = String.fromCharCode(97 + (counter % 26)) + Math.floor(counter / 26)
            const regex = new RegExp(`\\b${name}\\b`, 'g')
            result = result.replace(regex, mangled)
            counter++
          }
        })
      }

      return result
    },
    minifyCss(code) {
      let result = code

      if (this.options.removeComments) {
        result = result.replace(/\/\*[\s\S]*?\*\//g, '')
      }

      if (this.options.removeWhitespace) {
        result = result.replace(/\s+/g, ' ')
        result = result.replace(/\s*([{}:;,])\s*/g, '$1')
        result = result.replace(/;\s*}/g, '}')
        result = result.trim()
      }

      return result
    },
    minifyHtml(code) {
      let result = code

      if (this.options.removeComments) {
        result = result.replace(/<!--[\s\S]*?-->/g, '')
      }

      if (this.options.removeWhitespace) {
        // Preserve whitespace in pre, textarea, etc.
        const preserveTags = ['pre', 'textarea', 'script', 'style']
        const preserved = []
        
        preserveTags.forEach(tag => {
          const regex = new RegExp(`<${tag}[^>]*>[\\s\\S]*?<\\/${tag}>`, 'gi')
          result = result.replace(regex, (match) => {
            preserved.push(match)
            return `___PRESERVE_${preserved.length - 1}___`
          })
        })

        result = result.replace(/>\s+</g, '><')
        result = result.replace(/\s+/g, ' ')
        result = result.trim()

        // Restore preserved content
        preserved.forEach((content, index) => {
          result = result.replace(`___PRESERVE_${index}___`, content)
        })
      }

      return result
    },
    minifyJson(code) {
      try {
        const parsed = JSON.parse(code)
        return JSON.stringify(parsed)
      } catch (e) {
        this.$message.error('JSON 格式错误: ' + e.message)
        return code
      }
    },
    minifySql(code) {
      let result = code

      if (this.options.removeComments) {
        result = result.replace(/--.*$/gm, '')
        result = result.replace(/\/\*[\s\S]*?\*\//g, '')
      }

      if (this.options.removeWhitespace) {
        result = result.replace(/\s+/g, ' ')
        result = result.replace(/\s*([(),])\s*/g, '$1')
        result = result.trim()
      }

      return result
    },
    copyOutput() {
      if (!this.output) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.output).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    downloadOutput() {
      if (!this.output) {
        this.$message.warning('没有可下载的内容')
        return
      }
      const extensions = {
        javascript: 'js',
        css: 'css',
        html: 'html',
        json: 'json',
        sql: 'sql'
      }
      const blob = new Blob([this.output], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = `minified.${extensions[this.language]}`
      link.click()
      URL.revokeObjectURL(url)
    },
    clear() {
      this.input = ''
      this.output = ''
      this.stats = {
        originalSize: 0,
        minifiedSize: 0,
        saved: 0,
        ratio: 0
      }
    },
    formatSize(bytes) {
      if (bytes === 0) return '0 B'
      const k = 1024
      const sizes = ['B', 'KB', 'MB']
      const i = Math.floor(Math.log(bytes) / Math.log(k))
      return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
    },
    loadExample() {
      this.language = 'javascript'
      this.input = `// This is a sample JavaScript function
function calculateSum(a, b) {
    // Add two numbers
    console.log("Calculating sum...");
    var result = a + b;
    return result;
}

// Main execution
var x = 10;
var y = 20;
var sum = calculateSum(x, y);
console.log("Sum is: " + sum);`
      this.minify()
    }
  }
}
</script>

<style scoped>
.code-minifier-tool {
  padding: 20px;
}

.input-section, .output-section {
  height: 100%;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.section-title {
  font-weight: bold;
  color: #606266;
}

.section-actions {
  display: flex;
  gap: 10px;
}

.action-buttons {
  text-align: center;
  margin: 20px 0;
}

.stats-section {
  margin-top: 20px;
  padding: 20px;
  background: #f5f7fa;
  border-radius: 4px;
}

.stat-item {
  text-align: center;
}

.stat-label {
  font-size: 12px;
  color: #909399;
  margin-bottom: 5px;
}

.stat-value {
  font-size: 20px;
  font-weight: bold;
  color: #303133;
}

.stat-value.good {
  color: #67c23a;
}

.help-text {
  margin-left: 5px;
  color: #909399;
  font-size: 12px;
}
</style>
