<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>HTTP 请求工具</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
          <el-button size="small" type="primary" @click="saveRequest">保存请求</el-button>
          <el-button size="small" @click="showHistory = true">历史记录</el-button>
        </el-button-group>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="24">
          <div class="request-section">
            <el-row :gutter="10">
              <el-col :span="4">
                <el-select v-model="request.method" class="method-select">
                  <el-option label="GET" value="GET" />
                  <el-option label="POST" value="POST" />
                  <el-option label="PUT" value="PUT" />
                  <el-option label="DELETE" value="DELETE" />
                  <el-option label="PATCH" value="PATCH" />
                  <el-option label="HEAD" value="HEAD" />
                  <el-option label="OPTIONS" value="OPTIONS" />
                </el-select>
              </el-col>
              <el-col :span="16">
                <el-input 
                  v-model="request.url" 
                  placeholder="输入请求 URL，如: https://api.example.com/users"
                  @keyup.enter.native="sendRequest"
                />
              </el-col>
              <el-col :span="4">
                <el-button type="primary" style="width: 100%" @click="sendRequest" :loading="loading">
                  <i class="el-icon-s-promotion"></i> 发送
                </el-button>
              </el-col>
            </el-row>
            <el-row style="margin-top: 10px">
              <el-col :span="24">
                <el-checkbox v-model="request.useProxy">使用 CORS 代理（解决跨域问题）</el-checkbox>
                <el-tooltip content="当请求外部 API 出现跨域错误时，可以勾选此选项使用代理服务器">
                  <i class="el-icon-question" style="margin-left: 5px; color: #909399;"></i>
                </el-tooltip>
              </el-col>
            </el-row>
            </div>
        </el-col>
      </el-row>

      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-tabs v-model="activeTab">
            <el-tab-pane label="请求头" name="headers">
              <div class="params-section">
                <div class="section-header">
                  <span>请求头</span>
                  <el-button type="text" size="small" @click="addHeader">+ 添加</el-button>
                </div>
                <el-row v-for="(header, index) in request.headers" :key="index" :gutter="10" class="param-row">
                  <el-col :span="8">
                    <el-input v-model="header.key" placeholder="Header 名称" size="small" />
                  </el-col>
                  <el-col :span="14">
                    <el-input v-model="header.value" placeholder="Header 值" size="small" />
                  </el-col>
                  <el-col :span="2">
                    <el-button type="text" size="small" @click="removeHeader(index)">
                      <i class="el-icon-delete"></i>
                    </el-button>
                  </el-col>
                </el-row>
                <el-row v-if="request.headers.length === 0" class="empty-row">
                  <el-col :span="24">
                    <el-button type="text" @click="addHeader">添加请求头</el-button>
                  </el-col>
                </el-row>
              </div>
            </el-tab-pane>

            <el-tab-pane label="查询参数" name="params">
              <div class="params-section">
                <div class="section-header">
                  <span>查询参数</span>
                  <el-button type="text" size="small" @click="addParam">+ 添加</el-button>
                </div>
                <el-row v-for="(param, index) in request.params" :key="index" :gutter="10" class="param-row">
                  <el-col :span="8">
                    <el-input v-model="param.key" placeholder="参数名" size="small" />
                  </el-col>
                  <el-col :span="14">
                    <el-input v-model="param.value" placeholder="参数值" size="small" />
                  </el-col>
                  <el-col :span="2">
                    <el-button type="text" size="small" @click="removeParam(index)">
                      <i class="el-icon-delete"></i>
                    </el-button>
                  </el-col>
                </el-row>
                <el-row v-if="request.params.length === 0" class="empty-row">
                  <el-col :span="24">
                    <el-button type="text" @click="addParam">添加查询参数</el-button>
                  </el-col>
                </el-row>
              </div>
            </el-tab-pane>

            <el-tab-pane label="请求体" name="body" :disabled="['GET', 'HEAD'].includes(request.method)">
              <div class="body-section">
                <el-row :gutter="10">
                  <el-col :span="6">
                    <el-select v-model="request.contentType" size="small">
                      <el-option label="JSON" value="application/json" />
                      <el-option label="Form Data" value="multipart/form-data" />
                      <el-option label="x-www-form-urlencoded" value="application/x-www-form-urlencoded" />
                      <el-option label="Text" value="text/plain" />
                      <el-option label="XML" value="application/xml" />
                    </el-select>
                  </el-col>
                  <el-col :span="18" style="text-align: right;">
                    <el-button size="small" @click="formatBody">格式化</el-button>
                    <el-button size="small" @click="compressBody">压缩</el-button>
                  </el-col>
                </el-row>
                <el-input
                  v-model="request.body"
                  type="textarea"
                  :rows="8"
                  placeholder="请求体内容"
                  style="margin-top: 10px"
                />
              </div>
            </el-tab-pane>

            <el-tab-pane label="认证" name="auth">
              <div class="auth-section">
                <el-radio-group v-model="request.authType">
                  <el-radio label="none">无认证</el-radio>
                  <el-radio label="basic">Basic Auth</el-radio>
                  <el-radio label="bearer">Bearer Token</el-radio>
                </el-radio-group>

                <div v-if="request.authType === 'basic'" style="margin-top: 15px;">
                  <el-row :gutter="10">
                    <el-col :span="12">
                      <el-input v-model="request.auth.username" placeholder="用户名" />
                    </el-col>
                    <el-col :span="12">
                      <el-input v-model="request.auth.password" placeholder="密码" show-password />
                    </el-col>
                  </el-row>
                </div>

                <div v-if="request.authType === 'bearer'" style="margin-top: 15px;">
                  <el-input v-model="request.auth.token" placeholder="Bearer Token" />
                </div>
              </div>
            </el-tab-pane>
          </el-tabs>
        </el-col>
      </el-row>

      <el-divider>响应结果</el-divider>

      <el-row v-if="response">
        <el-col :span="24">
          <el-card shadow="never" :class="['response-card', responseStatusClass]">
            <div slot="header">
              <span>响应</span>
              <el-tag :type="responseStatusType" size="small" style="margin-left: 10px;">
                {{ response.status }} {{ response.statusText }}
              </el-tag>
              <span class="response-time">{{ response.time }}ms</span>
              <el-button-group style="float: right;">
                <el-button size="small" @click="downloadResponse">下载响应</el-button>
                <el-button size="small" @click="copyResponse">复制</el-button>
              </el-button-group>
            </div>

            <el-tabs v-model="responseTab">
              <el-tab-pane label="Body" name="body">
                <el-input
                  v-model="response.body"
                  type="textarea"
                  :rows="12"
                  readonly
                  class="response-body"
                />
              </el-tab-pane>
              <el-tab-pane label="Headers" name="headers">
                <el-table :data="responseHeaders" border size="small">
                  <el-table-column prop="key" label="Header" width="200" />
                  <el-table-column prop="value" label="Value" />
                </el-table>
              </el-tab-pane>
              <el-tab-pane label="Preview" name="preview">
                <div class="response-preview" v-html="responsePreview"></div>
              </el-tab-pane>
            </el-tabs>
          </el-card>
        </el-col>
      </el-row>

      <el-row v-else-if="error" style="margin-top: 20px;">
        <el-col :span="24">
          <el-alert type="error" :closable="false" show-icon>
            <template slot="title">{{ error }}</template>
          </el-alert>
        </el-col>
      </el-row>
    </el-card>

    <!-- 历史记录对话框 -->
    <el-dialog title="请求历史" :visible.sync="showHistory" width="700px">
      <el-table :data="requestHistory" border size="small">
        <el-table-column prop="method" label="方法" width="80">
          <template slot-scope="scope">
            <el-tag :type="getMethodType(scope.row.method)" size="mini">{{ scope.row.method }}</el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="url" label="URL" show-overflow-tooltip />
        <el-table-column prop="time" label="时间" width="150" />
        <el-table-column label="操作" width="120">
          <template slot-scope="scope">
            <el-button type="text" size="small" @click="loadRequest(scope.row)">加载</el-button>
            <el-button type="text" size="small" @click="deleteHistory(scope.$index)">删除</el-button>
          </template>
        </el-table-column>
      </el-table>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: 'HttpRequestTool',
  data() {
    return {
      loading: false,
      activeTab: 'headers',
      responseTab: 'body',
      request: {
        method: 'GET',
        url: '',
        headers: [
          { key: 'Accept', value: 'application/json' },
          { key: 'Content-Type', value: 'application/json' }
        ],
        params: [],
        body: '',
        contentType: 'application/json',
        authType: 'none',
        useProxy: false,
        auth: {
          username: '',
          password: '',
          token: ''
        }
      },
      response: null,
      error: null,
      showHistory: false,
      requestHistory: []
    }
  },
  computed: {
    responseStatusClass() {
      if (!this.response) return ''
      const status = this.response.status
      if (status >= 200 && status < 300) return 'success'
      if (status >= 300 && status < 400) return 'warning'
      if (status >= 400) return 'error'
      return ''
    },
    responseStatusType() {
      if (!this.response) return ''
      const status = this.response.status
      if (status >= 200 && status < 300) return 'success'
      if (status >= 300 && status < 400) return 'warning'
      if (status >= 400) return 'danger'
      return 'info'
    },
    responseHeaders() {
      if (!this.response || !this.response.headers) return []
      return Object.entries(this.response.headers).map(([key, value]) => ({
        key,
        value: Array.isArray(value) ? value.join(', ') : value
      }))
    },
    responsePreview() {
      if (!this.response || !this.response.body) return ''
      try {
        // 尝试解析为 JSON 并美化显示
        const json = JSON.parse(this.response.body)
        return '<pre style="background: #f5f7fa; padding: 15px; border-radius: 4px; overflow-x: auto;">' + 
               JSON.stringify(json, null, 2) + '</pre>'
      } catch {
        // 如果不是 JSON，尝试显示为 HTML 或纯文本
        const contentType = this.response.headers['content-type'] || ''
        if (contentType.includes('text/html')) {
          return '<iframe style="width: 100%; height: 400px; border: 1px solid #dcdfe6;" srcdoc="' + 
                 this.response.body.replace(/"/g, '&quot;') + '"></iframe>'
        }
        return '<pre style="background: #f5f7fa; padding: 15px; border-radius: 4px; overflow-x: auto; white-space: pre-wrap;">' + 
               this.escapeHtml(this.response.body) + '</pre>'
      }
    }
  },
  mounted() {
    this.loadHistory()
  },
  methods: {
    async sendRequest() {
      if (!this.request.url) {
        this.$message.warning('请输入请求 URL')
        return
      }

      this.loading = true
      this.response = null
      this.error = null

      const startTime = Date.now()

      try {
        // 构建 URL
        let url = this.request.url
        
        // 如果使用代理，添加代理前缀
        if (this.request.useProxy) {
          // 使用多个 CORS 代理服务
          const proxyUrls = [
            'https://api.allorigins.win/raw?url=',
            'https://corsproxy.io/?',
            'https://api.codetabs.com/v1/proxy?quest='
          ]
          // 随机选择一个代理，避免单个代理过载
          const proxyUrl = proxyUrls[Math.floor(Math.random() * proxyUrls.length)]
          url = proxyUrl + encodeURIComponent(url)
        }
        
        if (this.request.params.length > 0) {
          const params = new URLSearchParams()
          this.request.params.forEach(p => {
            if (p.key) params.append(p.key, p.value)
          })
          // 如果使用了代理，参数已经在 encodeURIComponent 中，不需要再次添加
          if (!this.request.useProxy) {
            url += (url.includes('?') ? '&' : '?') + params.toString()
          }
        }

        // 构建请求头
        const headers = {}
        this.request.headers.forEach(h => {
          if (h.key) headers[h.key] = h.value
        })

        // 处理认证
        if (this.request.authType === 'basic' && this.request.auth.username) {
          const credentials = btoa(`${this.request.auth.username}:${this.request.auth.password}`)
          headers['Authorization'] = `Basic ${credentials}`
        } else if (this.request.authType === 'bearer' && this.request.auth.token) {
          headers['Authorization'] = `Bearer ${this.request.auth.token}`
        }

        // 处理请求体
        let body = this.request.body
        if (this.request.contentType === 'application/json' && body) {
          try {
            body = JSON.stringify(JSON.parse(body))
          } catch {
            // 如果不是有效的 JSON，保持原样
          }
        }

        const options = {
          method: this.request.method,
          headers,
          body: ['GET', 'HEAD'].includes(this.request.method) ? undefined : body
        }

        // 使用 fetch 发送请求
        // 注意：由于 CORS 限制，某些请求可能会失败
        const res = await fetch(url, options)
        
        const responseHeaders = {}
        res.headers.forEach((value, key) => {
          responseHeaders[key] = value
        })

        const responseBody = await res.text()

        this.response = {
          status: res.status,
          statusText: res.statusText,
          headers: responseHeaders,
          body: responseBody,
          time: Date.now() - startTime
        }

        this.saveToHistory()
        this.$message.success('请求成功')
      } catch (err) {
        this.error = '请求失败: ' + err.message
        this.$message.error(this.error)
      } finally {
        this.loading = false
      }
    },
    addHeader() {
      this.request.headers.push({ key: '', value: '' })
    },
    removeHeader(index) {
      this.request.headers.splice(index, 1)
    },
    addParam() {
      this.request.params.push({ key: '', value: '' })
    },
    removeParam(index) {
      this.request.params.splice(index, 1)
    },
    formatBody() {
      if (!this.request.body) return
      try {
        const obj = JSON.parse(this.request.body)
        this.request.body = JSON.stringify(obj, null, 2)
      } catch {
        this.$message.warning('无法格式化：无效的 JSON')
      }
    },
    compressBody() {
      if (!this.request.body) return
      try {
        const obj = JSON.parse(this.request.body)
        this.request.body = JSON.stringify(obj)
      } catch {
        this.request.body = this.request.body.replace(/\s+/g, ' ').trim()
      }
    },
    downloadResponse() {
      if (!this.response || !this.response.body) {
        this.$message.warning('没有可下载的响应')
        return
      }
      const contentType = this.response.headers['content-type'] || 'text/plain'
      const extension = this.getExtensionFromContentType(contentType)
      const filename = `response_${Date.now()}${extension}`
      this.downloadFile(this.response.body, filename, contentType)
    },
    copyResponse() {
      if (!this.response || !this.response.body) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.response.body).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    downloadFile(content, filename, mimeType) {
      const blob = new Blob([content], { type: mimeType })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = filename
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(url)
      this.$message.success(`已下载 ${filename}`)
    },
    getExtensionFromContentType(contentType) {
      if (contentType.includes('json')) return '.json'
      if (contentType.includes('xml')) return '.xml'
      if (contentType.includes('html')) return '.html'
      if (contentType.includes('javascript')) return '.js'
      if (contentType.includes('css')) return '.css'
      if (contentType.includes('text/plain')) return '.txt'
      return '.bin'
    },
    escapeHtml(text) {
      const div = document.createElement('div')
      div.textContent = text
      return div.innerHTML
    },
    saveRequest() {
      const saved = JSON.parse(localStorage.getItem('savedRequests') || '[]')
      const name = prompt('请输入请求名称:')
      if (name) {
        saved.push({ name, request: JSON.parse(JSON.stringify(this.request)), time: new Date().toLocaleString() })
        localStorage.setItem('savedRequests', JSON.stringify(saved))
        this.$message.success('请求已保存')
      }
    },
    saveToHistory() {
      const history = JSON.parse(localStorage.getItem('requestHistory') || '[]')
      history.unshift({
        method: this.request.method,
        url: this.request.url,
        time: new Date().toLocaleString(),
        request: JSON.parse(JSON.stringify(this.request))
      })
      // 只保留最近 50 条
      if (history.length > 50) history.pop()
      localStorage.setItem('requestHistory', JSON.stringify(history))
      this.loadHistory()
    },
    loadHistory() {
      this.requestHistory = JSON.parse(localStorage.getItem('requestHistory') || '[]')
    },
    loadRequest(item) {
      this.request = JSON.parse(JSON.stringify(item.request))
      this.showHistory = false
      this.$message.success('请求已加载')
    },
    deleteHistory(index) {
      this.requestHistory.splice(index, 1)
      localStorage.setItem('requestHistory', JSON.stringify(this.requestHistory))
    },
    getMethodType(method) {
      const types = {
        'GET': 'success',
        'POST': 'primary',
        'PUT': 'warning',
        'DELETE': 'danger',
        'PATCH': 'info'
      }
      return types[method] || ''
    },
    clearAll() {
      this.request = {
        method: 'GET',
        url: '',
        headers: [{ key: 'Accept', value: 'application/json' }],
        params: [],
        body: '',
        contentType: 'application/json',
        authType: 'none',
        auth: { username: '', password: '', token: '' }
      }
      this.response = null
      this.error = null
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .header-actions {
    float: right;
  }

  .method-select {
    width: 100%;
  }

  .params-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }

    .param-row {
      margin-bottom: 10px;
    }

    .empty-row {
      text-align: center;
      padding: 20px;
      color: #909399;
    }
  }

  .auth-section {
    padding: 10px 0;
  }

  .response-card {
    &.success {
      border-left: 4px solid #67c23a;
    }
    &.warning {
      border-left: 4px solid #e6a23c;
    }
    &.error {
      border-left: 4px solid #f56c6c;
    }

    .response-time {
      margin-left: 10px;
      color: #909399;
      font-size: 12px;
    }
  }

  .response-body {
    font-family: 'Monaco', 'Menlo', 'Consolas', monospace;
  }

  .response-preview {
    max-height: 400px;
    overflow-y: auto;
  }
}
</style>
