<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>Markdown 格式化</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="loadExample">加载示例</el-button>
          <el-button size="small" @click="clear">清空当前</el-button>
        </el-button-group>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ tab.title }}
          </span>

          <el-row :gutter="20">
            <el-col :span="12">
              <div class="input-section">
                <div class="section-header">
                  <span>输入</span>
                </div>
                <el-input
                  v-model="tab.input"
                  type="textarea"
                  :rows="22"
                  placeholder="输入 Markdown..."
                />
              </div>
            </el-col>

            <el-col :span="12">
              <div class="input-section">
                <div class="section-header">
                  <span>{{ tab.previewMode ? '预览' : '格式化输出' }}</span>
                  <div>
                    <el-button type="text" size="mini" @click="tab.previewMode = !tab.previewMode">
                      {{ tab.previewMode ? '查看源码' : '查看预览' }}
                    </el-button>
                    <el-button type="text" size="mini" @click="copyOutput(tab)">复制</el-button>
                    <el-button type="text" size="mini" @click="downloadOutput(tab)">下载</el-button>
                  </div>
                </div>
                <div
                  v-show="tab.previewMode"
                  class="markdown-preview"
                  v-html="renderHtml(tab)"
                />
                <el-input
                  v-show="!tab.previewMode"
                  v-model="tab.output"
                  type="textarea"
                  :rows="22"
                  readonly
                  placeholder="格式化后的 Markdown 将显示在这里..."
                />
              </div>
            </el-col>
          </el-row>

          <el-row style="margin-top: 20px">
            <el-col :span="24">
              <el-form :inline="true" size="small">
                <el-form-item label="无序列表符号">
                  <el-select v-model="tab.bulletMarker" style="width: 90px">
                    <el-option label="-" value="-" />
                    <el-option label="*" value="*" />
                    <el-option label="+" value="+" />
                  </el-select>
                </el-form-item>
                <el-form-item label="标题前空行">
                  <el-switch v-model="tab.blankBeforeHeading" />
                </el-form-item>
                <el-form-item label="清理多余空行">
                  <el-switch v-model="tab.collapseBlankLines" />
                </el-form-item>
                <el-form-item label="去除行尾空格">
                  <el-switch v-model="tab.trimTrailing" />
                </el-form-item>
                <el-form-item>
                  <el-button type="primary" @click="format(tab)">格式化</el-button>
                </el-form-item>
              </el-form>
            </el-col>
          </el-row>

          <el-row style="margin-top: 20px">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">
                  <span>信息</span>
                </div>
                <el-descriptions :column="4" border size="small">
                  <el-descriptions-item label="输入行数">{{ inputLines(tab) }}</el-descriptions-item>
                  <el-descriptions-item label="输出行数">{{ outputLines(tab) }}</el-descriptions-item>
                  <el-descriptions-item label="字符数">{{ tab.output.length }}</el-descriptions-item>
                  <el-descriptions-item label="单词数">{{ wordCount(tab) }}</el-descriptions-item>
                </el-descriptions>
              </el-card>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
import { marked } from 'marked'

export default {
  name: 'MarkdownTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: 'MD ' + seq,
        input: '',
        output: '',
        previewMode: false,
        bulletMarker: '-',
        blankBeforeHeading: true,
        collapseBlankLines: true,
        trimTrailing: true
      }
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clear()
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },
    inputLines(tab) {
      return tab.input ? tab.input.split('\n').length : 0
    },
    outputLines(tab) {
      return tab.output ? tab.output.split('\n').length : 0
    },
    wordCount(tab) {
      const text = tab.output.trim()
      if (!text) return 0
      const matches = text.match(/[一-龥]|[A-Za-z0-9]+/g)
      return matches ? matches.length : 0
    },
    renderHtml(tab) {
      const source = tab.output || tab.input
      if (!source) return ''
      try {
        return marked.parse(source, { breaks: true, gfm: true })
      } catch (e) {
        return '<p style="color:#f56c6c">预览失败: ' + e.message + '</p>'
      }
    },
    format(tab) {
      if (!tab.input.trim()) {
        this.$message.warning('请输入 Markdown')
        return
      }
      try {
        tab.output = this.formatMarkdown(tab, tab.input)
        this.$message.success('格式化成功')
      } catch (error) {
        this.$message.error('格式化失败: ' + error.message)
      }
    },
    formatMarkdown(tab, src) {
      let lines = src.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n')
      const out = []
      let inFence = false
      let fenceToken = ''

      const headingRe = /^(#{1,6})\s*(\S.*?)\s*#*\s*$/
      const orderedRe = /^(\s*)(\d+)([.)])\s+(.*)$/
      const bulletRe = /^(\s*)([-*+])\s+(.*)$/

      for (let i = 0; i < lines.length; i++) {
        let line = lines[i]

        // 处理代码围栏，围栏内部不做任何改动
        const fenceMatch = line.match(/^(\s*)(```|~~~)(.*)$/)
        if (fenceMatch) {
          const token = fenceMatch[2]
          if (!inFence) {
            inFence = true
            fenceToken = token
          } else if (token === fenceToken) {
            inFence = false
            fenceToken = ''
          }
          out.push(line)
          continue
        }
        if (inFence) {
          out.push(line)
          continue
        }

        if (tab.trimTrailing) {
          line = line.replace(/[ \t]+$/, '')
        }

        // 标题规范化：# 后保证一个空格，去掉行尾的 #
        const h = line.match(headingRe)
        if (h) {
          const normalized = h[1] + ' ' + h[2].trim()
          if (tab.blankBeforeHeading && out.length > 0 && out[out.length - 1].trim() !== '') {
            out.push('')
          }
          out.push(normalized)
          // 标题后保证一个空行
          if (i + 1 < lines.length && lines[i + 1].trim() !== '') {
            out.push('')
          }
          continue
        }

        // 无序列表符号统一
        const b = line.match(bulletRe)
        if (b) {
          out.push(b[1] + tab.bulletMarker + ' ' + b[3])
          continue
        }

        // 有序列表点号统一为 .
        const o = line.match(orderedRe)
        if (o) {
          out.push(o[1] + o[2] + '. ' + o[4])
          continue
        }

        out.push(line)
      }

      let result = out.join('\n')

      // 合并多余空行（最多保留一个空行）
      if (tab.collapseBlankLines) {
        result = result.replace(/\n{3,}/g, '\n\n')
      }

      // 去除首尾多余空行，结尾保留一个换行
      result = result.replace(/^\n+/, '').replace(/\n+$/, '') + '\n'

      return result
    },
    copyOutput(tab) {
      if (!tab.output) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(tab.output).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    downloadOutput(tab) {
      if (!tab.output) {
        this.$message.warning('没有可下载的内容')
        return
      }
      const blob = new Blob([tab.output], { type: 'text/markdown;charset=utf-8;' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'formatted.md'
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    loadExample() {
      const tab = this.currentTab()
      if (!tab) return
      tab.input = `#    标题一   ###
这是一段文本。



##二级标题没有空格
*   列表项一
+ 列表项二
-    列表项三

1) 有序项一
2) 有序项二

\`\`\`js
const a = 1;
console.log(a);
\`\`\`

普通段落，行尾有空格   `
      this.format(tab)
    },
    clear() {
      const tab = this.currentTab()
      if (!tab) return
      tab.input = ''
      tab.output = ''
    }
  }
}
</script>

