<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>用户代理解析器</span>
        <el-button size="small" @click="clearAll">清空</el-button>
      </div>

      <el-row :gutter="20">
        <el-col :span="24">
          <el-input
            v-model="userAgent"
            placeholder="输入 User-Agent 字符串，留空则自动获取当前浏览器 UA"
            @input="debouncedParse"
            clearable
          >
            <el-button slot="append" @click="getMyUA">获取我的 UA</el-button>
          </el-input>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 20px" v-if="parsed">
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">浏览器</div>
            <el-descriptions :column="1" border size="small">
              <el-descriptions-item label="名称">{{ parsed.browser.name || '-' }}</el-descriptions-item>
              <el-descriptions-item label="版本">{{ parsed.browser.version || '-' }}</el-descriptions-item>
              <el-descriptions-item label="引擎">{{ parsed.engine.name || '-' }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">操作系统</div>
            <el-descriptions :column="1" border size="small">
              <el-descriptions-item label="名称">{{ parsed.os.name || '-' }}</el-descriptions-item>
              <el-descriptions-item label="版本">{{ parsed.os.version || '-' }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 20px" v-if="parsed">
        <el-col :span="8">
          <el-card shadow="never">
            <div slot="header">设备</div>
            <el-descriptions :column="1" border size="small">
              <el-descriptions-item label="类型">{{ parsed.device.type || '桌面端' }}</el-descriptions-item>
              <el-descriptions-item label="厂商">{{ parsed.device.vendor || '-' }}</el-descriptions-item>
              <el-descriptions-item label="型号">{{ parsed.device.model || '-' }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
        <el-col :span="8">
          <el-card shadow="never">
            <div slot="header">CPU</div>
            <el-descriptions :column="1" border size="small">
              <el-descriptions-item label="架构">{{ parsed.cpu.architecture || '-' }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
        <el-col :span="8">
          <el-card shadow="never">
            <div slot="header">客户端提示</div>
            <el-descriptions :column="1" border size="small">
              <el-descriptions-item label="移动端">{{ parsed.isMobile ? '是' : '否' }}</el-descriptions-item>
              <el-descriptions-item label="平板">{{ parsed.isTablet ? '是' : '否' }}</el-descriptions-item>
              <el-descriptions-item label="机器人">{{ parsed.isBot ? '是' : '否' }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 20px" v-if="parsed">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">
              <span>原始 UA 字符串</span>
              <el-button type="text" size="mini" @click="copyUA">复制</el-button>
            </div>
            <el-input
              :value="parsed.ua"
              type="textarea"
              :rows="3"
              readonly
            />
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'UserAgentParserTool',
  data() {
    return {
      userAgent: '',
      parsed: null,
      parseTimer: null
    }
  },
  mounted() {
    this.getMyUA()
  },
  methods: {
    getMyUA() {
      this.userAgent = navigator.userAgent
      this.parse()
    },
    debouncedParse() {
      if (this.parseTimer) clearTimeout(this.parseTimer)
      this.parseTimer = setTimeout(() => this.parse(), 300)
    },
    parse() {
      const ua = this.userAgent.trim()
      if (!ua) {
        this.parsed = null
        return
      }
      this.parsed = this.parseUA(ua)
    },
    parseUA(ua) {
      const result = {
        ua,
        browser: { name: '', version: '' },
        engine: { name: '' },
        os: { name: '', version: '' },
        device: { type: '', vendor: '', model: '' },
        cpu: { architecture: '' },
        isMobile: false,
        isTablet: false,
        isBot: false
      }

      const lower = ua.toLowerCase()

      // Bot detection
      if (/bot|crawler|spider|crawling/i.test(ua)) {
        result.isBot = true
        result.browser.name = 'Bot/Crawler'
        return result
      }

      // OS detection
      if (/windows nt 10/.test(lower)) { result.os.name = 'Windows'; result.os.version = '10/11' }
      else if (/windows nt 6\.3/.test(lower)) { result.os.name = 'Windows'; result.os.version = '8.1' }
      else if (/windows nt 6\.2/.test(lower)) { result.os.name = 'Windows'; result.os.version = '8' }
      else if (/windows nt 6\.1/.test(lower)) { result.os.name = 'Windows'; result.os.version = '7' }
      else if (/windows/.test(lower)) { result.os.name = 'Windows' }
      else if (/mac os x 15/.test(lower)) { result.os.name = 'macOS'; result.os.version = 'Sequoia (15)' }
      else if (/mac os x 14/.test(lower)) { result.os.name = 'macOS'; result.os.version = 'Sonoma (14)' }
      else if (/mac os x 13/.test(lower)) { result.os.name = 'macOS'; result.os.version = 'Ventura (13)' }
      else if (/mac os x 12/.test(lower)) { result.os.name = 'macOS'; result.os.version = 'Monterey (12)' }
      else if (/mac os x 11/.test(lower)) { result.os.name = 'macOS'; result.os.version = 'Big Sur (11)' }
      else if (/mac os x 10[_.]15/.test(lower)) { result.os.name = 'macOS'; result.os.version = 'Catalina (10.15)' }
      else if (/mac os x 10[_.]14/.test(lower)) { result.os.name = 'macOS'; result.os.version = 'Mojave (10.14)' }
      else if (/mac os x/.test(lower)) { result.os.name = 'macOS' }
      else if (/android (\d+[\d.]*)/.test(lower)) { result.os.name = 'Android'; result.os.version = RegExp.$1 }
      else if (/iphone os (\d+[_\d]*)/.test(lower)) { result.os.name = 'iOS'; result.os.version = RegExp.$1.replace(/_/g, '.') }
      else if (/ipad/.test(lower)) { result.os.name = 'iPadOS' }
      else if (/linux/.test(lower) && !/android/.test(lower)) { result.os.name = 'Linux' }
      else if (/cros/.test(lower)) { result.os.name = 'ChromeOS' }

      // CPU
      if (/x86_64|amd64|x64|win64/.test(lower)) result.cpu.architecture = 'x86_64 (64-bit)'
      else if (/x86|i[3-6]86/.test(lower)) result.cpu.architecture = 'x86 (32-bit)'
      else if (/arm64|aarch64/.test(lower)) result.cpu.architecture = 'ARM64'
      else if (/arm/.test(lower)) result.cpu.architecture = 'ARM'

      // Device
      if (/iphone/.test(lower)) { result.device.type = '手机'; result.device.vendor = 'Apple'; result.device.model = 'iPhone' }
      else if (/ipad/.test(lower)) { result.device.type = '平板'; result.device.vendor = 'Apple'; result.device.model = 'iPad' }
      else if (/android/.test(lower) && /mobile/.test(lower)) { result.device.type = '手机' }
      else if (/android/.test(lower)) { result.device.type = '平板' }
      else if (/windows phone/.test(lower)) { result.device.type = '手机'; result.device.vendor = 'Microsoft' }

      if (/mobile|phone/.test(lower) && !/ipad/.test(lower)) result.isMobile = true
      if (/ipad|tablet/.test(lower)) result.isTablet = true

      // Browser
      if (/edg\//.test(lower)) {
        result.browser.name = 'Edge'
        result.browser.version = (lower.match(/edg\/([\d.]+)/) || [])[1] || ''
        result.engine.name = 'Blink (Chromium)'
      } else if (/firefox\//.test(lower)) {
        result.browser.name = 'Firefox'
        result.browser.version = (lower.match(/firefox\/([\d.]+)/) || [])[1] || ''
        result.engine.name = 'Gecko'
      } else if (/chrome\//.test(lower) && !/edg\//.test(lower)) {
        result.browser.name = 'Chrome'
        result.browser.version = (lower.match(/chrome\/([\d.]+)/) || [])[1] || ''
        result.engine.name = 'Blink'
      } else if (/safari\//.test(lower) && !/chrome/.test(lower)) {
        result.browser.name = 'Safari'
        result.browser.version = (lower.match(/version\/([\d.]+)/) || [])[1] || ''
        result.engine.name = 'WebKit'
      } else if (/opera|opr\//.test(lower)) {
        result.browser.name = 'Opera'
        result.browser.version = (lower.match(/opr\/([\d.]+)/) || lower.match(/opera\/([\d.]+)/) || [])[1] || ''
        result.engine.name = 'Blink'
      } else if (/msie|trident/.test(lower)) {
        result.browser.name = 'Internet Explorer'
        result.browser.version = (lower.match(/msie ([\d.]+)/) || lower.match(/rv:([\d.]+)/) || [])[1] || ''
        result.engine.name = 'Trident'
      }

      return result
    },
    clearAll() {
      this.userAgent = ''
      this.parsed = null
    },
    copyUA() {
      if (this.parsed && this.parsed.ua) {
        navigator.clipboard.writeText(this.parsed.ua).then(() => {
          this.$message.success('已复制到剪贴板')
        })
      }
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  padding: 20px;
}
</style>
