<template>
  <div class="gradient-tool">
    <el-card>
      <div slot="header">
        <span>渐变生成器</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-form :model="gradient" label-width="100px">
            <el-form-item label="渐变类型">
              <el-radio-group v-model="gradient.type">
                <el-radio-button label="linear">线性渐变</el-radio-button>
                <el-radio-button label="radial">径向渐变</el-radio-button>
                <el-radio-button label="conic">圆锥渐变</el-radio-button>
              </el-radio-group>
            </el-form-item>

            <template v-if="gradient.type === 'linear'">
              <el-form-item label="角度">
                <el-slider v-model="gradient.angle" :min="0" :max="360" show-input />
              </el-form-item>
            </template>

            <el-form-item label="颜色节点">
              <div v-for="(stop, index) in gradient.stops" :key="index" class="color-stop">
                <el-color-picker v-model="stop.color" show-alpha />
                <el-slider v-model="stop.position" :min="0" :max="100" style="width: 150px; margin: 0 10px" />
                <span class="stop-position">{{ stop.position }}%</span>
                <el-button type="text" @click="removeStop(index)" v-if="gradient.stops.length > 2">
                  <i class="el-icon-delete"></i>
                </el-button>
              </div>
              <el-button type="text" @click="addStop">+ 添加颜色节点</el-button>
            </el-form-item>

            <el-form-item>
              <el-button type="primary" @click="randomize">随机生成</el-button>
              <el-button @click="copyCss">复制CSS</el-button>
            </el-form-item>
          </el-form>
        </el-col>

        <el-col :span="12">
          <div class="preview-section">
            <div class="preview-box" :style="gradientStyle"></div>
            <div class="css-output">
              <pre><code>{{ cssCode }}</code></pre>
            </div>
          </div>
        </el-col>
      </el-row>

      <el-divider>预设渐变</el-divider>

      <div class="presets">
        <div 
          v-for="(preset, index) in presets" 
          :key="index"
          class="preset-item"
          :style="{ background: preset }"
          @click="applyPreset(preset)"
        ></div>
      </div>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'GradientTool',
  data() {
    return {
      gradient: {
        type: 'linear',
        angle: 45,
        stops: [
          { color: '#667eea', position: 0 },
          { color: '#764ba2', position: 100 }
        ]
      },
      presets: [
        'linear-gradient(45deg, #667eea 0%, #764ba2 100%)',
        'linear-gradient(90deg, #f093fb 0%, #f5576c 100%)',
        'linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)',
        'linear-gradient(180deg, #43e97b 0%, #38f9d7 100%)',
        'linear-gradient(225deg, #fa709a 0%, #fee140 100%)',
        'radial-gradient(circle, #ffecd2 0%, #fcb69f 100%)',
        'linear-gradient(to right, #ff9a9e 0%, #fecfef 50%, #fecfef 100%)',
        'linear-gradient(120deg, #a1c4fd 0%, #c2e9fb 100%)'
      ]
    }
  },
  computed: {
    gradientStyle() {
      const stops = this.gradient.stops
        .sort((a, b) => a.position - b.position)
        .map(s => `${s.color} ${s.position}%`)
        .join(', ')
      
      if (this.gradient.type === 'linear') {
        return { background: `linear-gradient(${this.gradient.angle}deg, ${stops})` }
      } else if (this.gradient.type === 'radial') {
        return { background: `radial-gradient(circle, ${stops})` }
      } else {
        return { background: `conic-gradient(${stops})` }
      }
    },
    cssCode() {
      const stops = this.gradient.stops
        .sort((a, b) => a.position - b.position)
        .map(s => `${s.color} ${s.position}%`)
        .join(', ')
      
      if (this.gradient.type === 'linear') {
        return `background: linear-gradient(${this.gradient.angle}deg, ${stops});`
      } else if (this.gradient.type === 'radial') {
        return `background: radial-gradient(circle, ${stops});`
      } else {
        return `background: conic-gradient(${stops});`
      }
    }
  },
  methods: {
    addStop() {
      const lastStop = this.gradient.stops[this.gradient.stops.length - 1]
      const newPosition = Math.min(100, lastStop.position + 20)
      this.gradient.stops.push({
        color: '#ffffff',
        position: newPosition
      })
    },
    removeStop(index) {
      this.gradient.stops.splice(index, 1)
    },
    randomize() {
      this.gradient.stops = []
      const count = 2 + Math.floor(Math.random() * 3)
      for (let i = 0; i < count; i++) {
        this.gradient.stops.push({
          color: '#' + Math.floor(Math.random() * 16777215).toString(16).padStart(6, '0'),
          position: Math.round((i / (count - 1)) * 100)
        })
      }
      this.gradient.angle = Math.floor(Math.random() * 360)
    },
    copyCss() {
      navigator.clipboard.writeText(this.cssCode).then(() => {
        this.$message.success('CSS已复制')
      })
    },
    applyPreset(css) {
      // Simple preset application
      this.$message.info('已应用预设渐变')
    }
  }
}
</script>

<style scoped>
.gradient-tool {
  padding: 20px;
}

.color-stop {
  display: flex;
  align-items: center;
  margin-bottom: 10px;
}

.stop-position {
  min-width: 40px;
  text-align: right;
}

.preview-section {
  text-align: center;
}

.preview-box {
  width: 100%;
  height: 200px;
  border-radius: 8px;
  margin-bottom: 20px;
}

.css-output {
  background: #f5f7fa;
  padding: 15px;
  border-radius: 4px;
  text-align: left;
}

.css-output pre {
  margin: 0;
  font-family: monospace;
  font-size: 14px;
}

.presets {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 15px;
}

.preset-item {
  height: 80px;
  border-radius: 8px;
  cursor: pointer;
  transition: transform 0.2s;
}

.preset-item:hover {
  transform: scale(1.05);
}
</style>
