<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>SQL 格式化</span>
        <el-button size="small" @click="clear">清空当前</el-button>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ tab.title }}
          </span>

          <el-row :gutter="20">
            <el-col :span="24">
              <div class="input-section">
                <div class="section-header">
                  <span>SQL 内容</span>
                  <el-tag size="mini" type="info">输入或粘贴 SQL，点击按钮格式化</el-tag>
                </div>
                <el-input
                  v-model="tab.sqlText"
                  type="textarea"
                  :rows="15"
                  placeholder="输入 SQL 语句，如: SELECT * FROM users WHERE id = 1"
                />
              </div>
            </el-col>
          </el-row>

          <el-row style="margin-top: 15px">
            <el-col :span="24" class="action-row">
              <el-radio-group v-model="tab.indent" size="small">
                <el-radio-button :label="2">2空格</el-radio-button>
                <el-radio-button :label="4">4空格</el-radio-button>
              </el-radio-group>

              <div class="action-buttons">
                <el-button type="primary" @click="format(tab)">格式化</el-button>
                <el-button type="warning" @click="compress(tab)">压缩</el-button>
                <el-button type="success" @click="toUpper(tab)">大写关键字</el-button>
                <el-button type="info" @click="toLower(tab)">小写关键字</el-button>
                <el-button @click="copy(tab)">复制</el-button>
              </div>
            </el-col>
          </el-row>

          <el-row style="margin-top: 15px" v-if="tab.stats">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">SQL 统计</div>
                <el-descriptions :column="4" border size="small">
                  <el-descriptions-item label="关键字数">{{ tab.stats.keywords }}</el-descriptions-item>
                  <el-descriptions-item label="字符数">{{ tab.stats.chars }}</el-descriptions-item>
                  <el-descriptions-item label="行数">{{ tab.stats.lines }}</el-descriptions-item>
                  <el-descriptions-item label="语句类型">{{ tab.stats.type || '-' }}</el-descriptions-item>
                </el-descriptions>
              </el-card>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
const KEYWORDS = [
  'SELECT', 'FROM', 'WHERE', 'AND', 'OR', 'NOT', 'IN', 'EXISTS',
  'JOIN', 'LEFT', 'RIGHT', 'INNER', 'OUTER', 'ON', 'AS',
  'GROUP', 'BY', 'HAVING', 'ORDER', 'ASC', 'DESC',
  'INSERT', 'INTO', 'VALUES', 'UPDATE', 'SET', 'DELETE',
  'CREATE', 'TABLE', 'DROP', 'ALTER', 'ADD', 'COLUMN',
  'INDEX', 'VIEW', 'DATABASE', 'SCHEMA',
  'UNION', 'ALL', 'DISTINCT', 'LIMIT', 'OFFSET',
  'CASE', 'WHEN', 'THEN', 'ELSE', 'END',
  'NULL', 'IS', 'LIKE', 'BETWEEN', 'TRUE', 'FALSE',
  'PRIMARY', 'KEY', 'FOREIGN', 'REFERENCES', 'CONSTRAINT',
  'DEFAULT', 'AUTO_INCREMENT', 'IDENTITY',
  'BEGIN', 'COMMIT', 'ROLLBACK', 'TRANSACTION',
  'GRANT', 'REVOKE', 'PRIVILEGES', 'TO'
]

const CLAUSE_KEYWORDS = [
  'SELECT', 'FROM', 'WHERE', 'AND', 'OR', 'GROUP BY', 'HAVING', 'ORDER BY',
  'LEFT JOIN', 'RIGHT JOIN', 'INNER JOIN', 'OUTER JOIN', 'JOIN',
  'LEFT OUTER JOIN', 'RIGHT OUTER JOIN',
  'UNION', 'UNION ALL', 'LIMIT', 'OFFSET'
]

export default {
  name: 'SqlTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: 'SQL ' + seq,
        sqlText: '',
        indent: 2,
        stats: null
      }
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clear()
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },
    format(tab) {
      if (!tab.sqlText.trim()) {
        this.$message.warning('请输入 SQL 内容')
        return
      }

      try {
        tab.sqlText = this.formatSql(tab.sqlText, tab.indent)
        this.updateStats(tab)
        this.$message.success('格式化成功')
      } catch (e) {
        this.$message.error('格式化失败: ' + e.message)
      }
    },
    formatSql(sql, indent) {
      const PADDING = ' '.repeat(indent)

      sql = sql.replace(/\s+/g, ' ').trim()

      CLAUSE_KEYWORDS.forEach(keyword => {
        const regex = new RegExp('\\b' + keyword.replace(' ', '\\s+') + '\\b', 'gi')
        sql = sql.replace(regex, '\n' + keyword.toUpperCase())
      })

      sql = sql.replace(/^\n/, '')

      const lines = sql.split('\n')
      let result = []
      let level = 0

      lines.forEach(line => {
        const upperLine = line.toUpperCase().trim()

        if (upperLine.startsWith('FROM') || upperLine.startsWith('WHERE') ||
            upperLine.startsWith('GROUP') || upperLine.startsWith('HAVING') ||
            upperLine.startsWith('ORDER') || upperLine.startsWith('LIMIT')) {
          level = 0
        } else if (upperLine.includes('JOIN')) {
          level = 0
        } else if (upperLine.startsWith('AND') || upperLine.startsWith('OR')) {
          level = 1
        }

        result.push(PADDING.repeat(level) + line.trim())
      })

      return result.join('\n')
    },
    compress(tab) {
      if (!tab.sqlText.trim()) {
        this.$message.warning('请输入 SQL 内容')
        return
      }

      tab.sqlText = tab.sqlText
        .replace(/\n/g, ' ')
        .replace(/\s{2,}/g, ' ')
        .trim()
      this.updateStats(tab)
      this.$message.success('压缩成功')
    },
    toUpper(tab) {
      if (!tab.sqlText.trim()) {
        this.$message.warning('请输入 SQL 内容')
        return
      }

      KEYWORDS.forEach(keyword => {
        const regex = new RegExp('\\b' + keyword + '\\b', 'gi')
        tab.sqlText = tab.sqlText.replace(regex, keyword)
      })
      this.updateStats(tab)
      this.$message.success('已转换为大写')
    },
    toLower(tab) {
      if (!tab.sqlText.trim()) {
        this.$message.warning('请输入 SQL 内容')
        return
      }

      KEYWORDS.forEach(keyword => {
        const regex = new RegExp('\\b' + keyword + '\\b', 'gi')
        tab.sqlText = tab.sqlText.replace(regex, keyword.toLowerCase())
      })
      this.updateStats(tab)
      this.$message.success('已转换为小写')
    },
    updateStats(tab) {
      const upper = tab.sqlText.toUpperCase()

      let keywordCount = 0
      KEYWORDS.forEach(keyword => {
        const regex = new RegExp('\\b' + keyword + '\\b', 'gi')
        const matches = tab.sqlText.match(regex)
        if (matches) keywordCount += matches.length
      })

      let type = ''
      const firstWord = upper.trim().split(/\s+/)[0]
      if (['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'CREATE', 'DROP', 'ALTER'].includes(firstWord)) {
        type = firstWord
      }

      tab.stats = {
        keywords: keywordCount,
        chars: tab.sqlText.length,
        lines: tab.sqlText.split('\n').length,
        type
      }
    },
    copy(tab) {
      if (!tab.sqlText) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(tab.sqlText).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    clear() {
      const tab = this.currentTab()
      if (!tab) return
      tab.sqlText = ''
      tab.stats = null
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .input-section {
    .section-header {
      display: flex;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
      gap: 10px;
    }
  }

  .action-row {
    display: flex;
    justify-content: space-between;
    align-items: center;

    .action-buttons {
      display: flex;
      gap: 10px;
    }
  }
}
</style>
