<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>Mermaid 图表编辑器</span>
        <div>
          <el-dropdown trigger="click" size="small" style="margin-right: 10px">
            <el-button size="small">
              标签操作<i class="el-icon-arrow-down el-icon--right"></i>
            </el-button>
            <el-dropdown-menu slot="dropdown">
              <el-dropdown-item @click.native="closeOtherTabs">关闭其他</el-dropdown-item>
              <el-dropdown-item @click.native="closeAllTabs">关闭全部</el-dropdown-item>
              <el-dropdown-item divided @click.native="closeLeftTabs">关闭左侧</el-dropdown-item>
              <el-dropdown-item @click.native="closeRightTabs">关闭右侧</el-dropdown-item>
            </el-dropdown-menu>
          </el-dropdown>
          <el-button size="small" @click="loadExample('flowchart')">流程图示例</el-button>
          <el-button size="small" @click="loadExample('sequence')">时序图示例</el-button>
          <el-button size="small" @click="loadExample('gantt')">甘特图示例</el-button>
          <el-button size="small" @click="loadExample('class')">类图示例</el-button>
          <el-button
            size="small"
            @click="downloadSVG"
            :disabled="!(activeTabData && activeTabData.svgData)"
          >下载 SVG</el-button>
        </div>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-share" />
            {{ getTabTitle(tab) }}
          </span>

          <el-row :gutter="20">
            <el-col :span="12">
              <div class="editor-header">
                <span>Mermaid 代码</span>
                <el-tag v-if="tab.error" type="danger" size="mini">语法错误</el-tag>
              </div>
              <el-input
                v-model="tab.mermaidCode"
                type="textarea"
                :rows="20"
                placeholder="输入 Mermaid 图表代码..."
                @input="debouncedRender(tab)"
                style="font-family: monospace; font-size: 13px; line-height: 1.6"
              />
              <div class="quick-ref" style="margin-top: 10px">
                <span style="font-size: 12px; color: #909399">快速参考：</span>
                <el-button type="text" size="mini" @click="insertTemplate('flowchart')">流程图</el-button>
                <el-button type="text" size="mini" @click="insertTemplate('sequence')">时序图</el-button>
                <el-button type="text" size="mini" @click="insertTemplate('gantt')">甘特图</el-button>
                <el-button type="text" size="mini" @click="insertTemplate('pie')">饼图</el-button>
                <el-button type="text" size="mini" @click="insertTemplate('state')">状态图</el-button>
              </div>
            </el-col>
            <el-col :span="12">
              <div class="editor-header">
                <span>预览</span>
                <el-button type="text" size="mini" @click="renderDiagram(tab)" :loading="tab.rendering">刷新</el-button>
              </div>
              <div class="preview-container" :id="'mermaid-' + tab.id">
                <div v-if="tab.rendering" class="loading">
                  <i class="el-icon-loading"></i>
                  <span>渲染中...</span>
                </div>
                <div v-else-if="tab.error" class="error-display">
                  <el-alert :title="tab.error" type="error" show-icon :closable="false" />
                </div>
                <div
                  v-else-if="tab.svgData"
                  v-html="tab.svgData"
                  class="mermaid-preview"
                ></div>
                <div v-else class="empty-hint">
                  <i class="el-icon-picture-outline"></i>
                  <p>输入 Mermaid 代码，预览图表将显示在这里</p>
                </div>
              </div>
            </el-col>
          </el-row>

          <el-divider>支持的图表类型</el-divider>
          <el-row :gutter="10">
            <el-col :span="4" v-for="type in chartTypes" :key="type.name">
              <el-card shadow="hover" class="type-card" @click.native="insertTemplate(type.name)">
                <div class="type-icon">{{ type.icon }}</div>
                <div class="type-name">{{ type.label }}</div>
              </el-card>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'MermaidEditorTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)],
      mermaidLoaded: false,
      mermaidLoading: false,  // 防止脚本重复追加
      chartTypes: [
        { name: 'flowchart', label: '流程图', icon: '🔄' },
        { name: 'sequence', label: '时序图', icon: '📊' },
        { name: 'gantt', label: '甘特图', icon: '📅' },
        { name: 'class', label: '类图', icon: '📦' },
        { name: 'pie', label: '饼图', icon: '🥧' },
        { name: 'state', label: '状态图', icon: '🔀' },
      ]
    }
  },
  computed: {
    activeTabData() {
      return this.tabs.find(t => t.id === this.activeTab)
    }
  },
  watch: {
    activeTab() {
      // 切换标签时，只有已有代码但无缓存 SVG 才重新渲染，避免闪烁
      this.$nextTick(() => {
        const tab = this.currentTab()
        if (tab && tab.mermaidCode.trim() && !tab.svgData) {
          this.renderDiagram(tab)
        }
      })
    }
  },
  mounted() {
    this.loadMermaid()
    this.loadExample('flowchart')
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: 'Diagram ' + seq,
        mermaidCode: '',
        svgData: '',
        error: '',
        rendering: false,
        renderTimer: null
      }
    },
    getTabTitle(tab) {
      const content = tab.mermaidCode || ''
      const preview = content.trim().split('\n')[0].slice(0, 15)
      return preview ? `${tab.title}: ${preview}...` : tab.title
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clearTab()
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 清理定时器防止泄漏
      const tab = this.tabs[index]
      if (tab.renderTimer) {
        clearTimeout(tab.renderTimer)
        tab.renderTimer = null
      }

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },
    clearTab() {
      const tab = this.currentTab()
      if (!tab) return
      tab.mermaidCode = ''
      tab.svgData = ''
      tab.error = ''
    },
    loadMermaid() {
      if (window.mermaid) {
        this.mermaidLoaded = true
        return
      }
      // 防止并发调用时重复追加脚本
      if (this.mermaidLoading) return
      this.mermaidLoading = true

      const script = document.createElement('script')
      script.src = 'https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.min.js'
      script.onload = () => {
        window.mermaid.initialize({
          startOnLoad: false,
          theme: 'default',
          securityLevel: 'loose',
        })
        this.mermaidLoaded = true
        this.mermaidLoading = false
        const tab = this.currentTab()
        if (tab) this.renderDiagram(tab)
      }
      script.onerror = () => {
        this.mermaidLoading = false
        this.$message.error('Mermaid 库加载失败，请检查网络')
      }
      document.head.appendChild(script)
    },
    debouncedRender(tab) {
      if (tab.renderTimer) clearTimeout(tab.renderTimer)
      tab.renderTimer = setTimeout(() => this.renderDiagram(tab), 500)
    },
    async renderDiagram(tab) {
      if (!tab || !tab.mermaidCode.trim() || !this.mermaidLoaded) return

      tab.rendering = true
      tab.error = ''
      tab.svgData = ''

      try {
        // 使用 tab.id 保证每个标签的临时渲染 id 唯一，避免相互覆盖
        const { svg } = await window.mermaid.render('mmd-' + tab.id, tab.mermaidCode.trim())
        tab.svgData = svg
      } catch (e) {
        tab.error = e.message || '渲染失败，请检查语法'
      } finally {
        tab.rendering = false
      }
    },
    loadExample(type) {
      const examples = {
        flowchart: `graph TD
    A[开始] --> B{是否登录?}
    B -->|是| C[进入主页]
    B -->|否| D[跳转登录页]
    D --> E[输入用户名密码]
    E --> F{验证通过?}
    F -->|是| C
    F -->|否| G[显示错误提示]
    G --> E
    C --> H[结束]`,

        sequence: `sequenceDiagram
    participant U as 用户
    participant F as 前端
    participant A as API 服务器
    participant D as 数据库

    U->>F: 点击登录按钮
    F->>A: POST /api/login
    A->>D: 查询用户表
    D-->>A: 返回用户信息
    A-->>F: 返回 JWT Token
    F->>F: 存储 Token
    F-->>U: 跳转到首页`,

        gantt: `gantt
    title 项目开发计划
    dateFormat  YYYY-MM-DD
    section 需求阶段
    需求分析           :done, a1, 2024-01-01, 2024-01-10
    需求评审           :done, a2, 2024-01-11, 2024-01-14
    section 开发阶段
    UI设计              :active, b1, 2024-01-15, 2024-01-30
    后端开发            :b2, 2024-01-20, 2024-02-15
    前端开发            :b3, 2024-01-25, 2024-02-20
    section 测试阶段
    单元测试            :c1, 2024-02-15, 2024-02-28
    集成测试            :c2, 2024-03-01, 2024-03-10
    上线发布            :milestone, 2024-03-15`,

        class: `classDiagram
    class User {
      +String name
      +String email
      +login()
      +logout()
    }
    class Order {
      +String orderId
      +Number amount
      +create()
      +cancel()
    }
    class Product {
      +String name
      +Number price
      +Number stock
    }
    User "1" --> "*" Order : 创建
    Order "*" --> "*" Product : 包含`,
      }
      const tab = this.currentTab()
      if (!tab) return
      tab.mermaidCode = examples[type] || examples.flowchart
      this.renderDiagram(tab)
    },
    insertTemplate(type) {
      const templates = {
        flowchart: `graph TD
    A[节点A] --> B[节点B]
    B --> C{条件判断}
    C -->|条件1| D[结果1]
    C -->|条件2| E[结果2]`,
        sequence: `sequenceDiagram
    participant A as 用户A
    participant B as 用户B
    A->>B: 发送请求
    B-->>A: 返回响应`,
        gantt: `gantt
    title 项目计划
    dateFormat YYYY-MM-DD
    section 阶段一
    任务1 :a1, 2024-01-01, 30d
    任务2 :a2, 2024-02-01, 20d`,
        pie: `pie title 技术栈使用比例
    "Vue.js" : 40
    "React" : 30
    "Angular" : 15
    "其他" : 15`,
        state: `stateDiagram-v2
    [*] --> 待处理
    待处理 --> 处理中 : 开始处理
    处理中 --> 已完成 : 处理成功
    处理中 --> 失败 : 处理失败
    失败 --> 处理中 : 重试
    已完成 --> [*]`,
      }
      const tab = this.currentTab()
      if (!tab) return
      tab.mermaidCode = templates[type] || templates.flowchart
      this.renderDiagram(tab)
    },
    downloadSVG() {
      const tab = this.currentTab()
      if (!tab || !tab.svgData) return
      const blob = new Blob([tab.svgData], { type: 'image/svg+xml' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = tab.title.replace(/\s+/g, '-').toLowerCase() + '.svg'
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('SVG 已下载')
    },
    // 标签批量操作
    closeOtherTabs() {
      const current = this.currentTab()
      if (!current) return
      this.tabs = [current]
      this.$message.success('已关闭其他标签')
    },
    closeAllTabs() {
      this.tabs = [this.createTab(++this.tabCounter)]
      this.activeTab = this.tabs[0].id
      this.$message.success('已关闭全部标签并新建空白标签')
    },
    closeLeftTabs() {
      const index = this.tabs.findIndex(t => t.id === this.activeTab)
      if (index <= 0) {
        this.$message.info('当前标签左侧没有其他标签')
        return
      }
      this.tabs = this.tabs.slice(index)
      this.$message.success(`已关闭左侧 ${index} 个标签`)
    },
    closeRightTabs() {
      const index = this.tabs.findIndex(t => t.id === this.activeTab)
      if (index === -1 || index === this.tabs.length - 1) {
        this.$message.info('当前标签右侧没有其他标签')
        return
      }
      const removed = this.tabs.length - index - 1
      this.tabs = this.tabs.slice(0, index + 1)
      this.$message.success(`已关闭右侧 ${removed} 个标签`)
    }
  }
}
</script>

