<template>
  <div class="big-number-tool">
    <el-card>
      <div slot="header">
        <span>大数计算器</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="loadExample">加载示例</el-button>
      </div>

      <el-form label-width="80px">
        <el-row :gutter="20">
          <el-col :span="10">
            <el-form-item label="数值 A">
              <el-input v-model="numA" placeholder="输入第一个数值" />
            </el-form-item>
          </el-col>
          <el-col :span="4">
            <el-form-item label="运算符">
              <el-select v-model="operator" style="width: 100%">
                <el-option label="+" value="+" />
                <el-option label="-" value="-" />
                <el-option label="×" value="*" />
                <el-option label="÷" value="/" />
                <el-option label="^" value="^" />
                <el-option label="%" value="%" />
                <el-option label="GCD" value="gcd" />
                <el-option label="LCM" value="lcm" />
              </el-select>
            </el-form-item>
          </el-col>
          <el-col :span="10">
            <el-form-item label="数值 B">
              <el-input v-model="numB" placeholder="输入第二个数值" />
            </el-form-item>
          </el-col>
        </el-row>
      </el-form>

      <div class="action-buttons">
        <el-button type="primary" @click="calculate">计算</el-button>
        <el-button @click="clear">清空</el-button>
      </div>

      <el-divider>计算结果</el-divider>

      <div v-if="result" class="result-section">
        <div class="result-value">{{ result }}</div>
        <div class="result-details">
          <el-row :gutter="20">
            <el-col :span="8">
              <div class="detail-item">
                <span class="detail-label">科学计数法</span>
                <span class="detail-value">{{ scientificNotation }}</span>
              </div>
            </el-col>
            <el-col :span="8">
              <div class="detail-item">
                <span class="detail-label">位数</span>
                <span class="detail-value">{{ digitCount }} 位</span>
              </div>
            </el-col>
            <el-col :span="8">
              <div class="detail-item">
                <span class="detail-label">是否为质数</span>
                <span class="detail-value">{{ isPrime ? '是' : '否' }}</span>
              </div>
            </el-col>
          </el-row>
        </div>
      </div>

      <el-divider>进制转换</el-divider>

      <el-form label-width="80px" v-if="result">
        <el-row :gutter="20">
          <el-col :span="12">
            <el-form-item label="二进制">
              <el-input v-model="baseConversions.binary" readonly>
                <el-button slot="append" @click="copy(baseConversions.binary)">复制</el-button>
              </el-input>
            </el-form-item>
          </el-col>
          <el-col :span="12">
            <el-form-item label="八进制">
              <el-input v-model="baseConversions.octal" readonly>
                <el-button slot="append" @click="copy(baseConversions.octal)">复制</el-button>
              </el-input>
            </el-form-item>
          </el-col>
          <el-col :span="12">
            <el-form-item label="十进制">
              <el-input v-model="baseConversions.decimal" readonly>
                <el-button slot="append" @click="copy(baseConversions.decimal)">复制</el-button>
              </el-input>
            </el-form-item>
          </el-col>
          <el-col :span="12">
            <el-form-item label="十六进制">
              <el-input v-model="baseConversions.hex" readonly>
                <el-button slot="append" @click="copy(baseConversions.hex)">复制</el-button>
              </el-input>
            </el-form-item>
          </el-col>
        </el-row>
      </el-form>

      <el-divider>常用大数函数</el-divider>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">阶乘</div>
            <el-input-number v-model="factorialInput" :min="0" :max="1000" />
            <el-button type="primary" size="small" @click="calculateFactorial" style="margin-left: 10px">计算</el-button>
            <div v-if="factorialResult" class="function-result">
              {{ factorialInput }}! = {{ factorialResult.substring(0, 50) }}{{ factorialResult.length > 50 ? '...' : '' }}
            </div>
          </el-card>
        </el-col>
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">斐波那契数列</div>
            <el-input-number v-model="fibonacciInput" :min="1" :max="1000" />
            <el-button type="primary" size="small" @click="calculateFibonacci" style="margin-left: 10px">计算</el-button>
            <div v-if="fibonacciResult" class="function-result">
              F({{ fibonacciInput }}) = {{ fibonacciResult.substring(0, 50) }}{{ fibonacciResult.length > 50 ? '...' : '' }}
            </div>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'BigNumberTool',
  data() {
    return {
      numA: '',
      numB: '',
      operator: '+',
      result: '',
      scientificNotation: '',
      digitCount: 0,
      isPrime: false,
      baseConversions: {
        binary: '',
        octal: '',
        decimal: '',
        hex: ''
      },
      factorialInput: 10,
      factorialResult: '',
      fibonacciInput: 10,
      fibonacciResult: ''
    }
  },
  methods: {
    calculate() {
      if (!this.numA || (this.operator !== '!' && !this.numB)) {
        this.$message.warning('请输入数值')
        return
      }

      try {
        const a = this.numA.toString()
        const b = this.numB.toString()
        
        switch (this.operator) {
          case '+':
            this.result = this.bigAdd(a, b)
            break
          case '-':
            this.result = this.bigSubtract(a, b)
            break
          case '*':
            this.result = this.bigMultiply(a, b)
            break
          case '/':
            this.result = this.bigDivide(a, b)
            break
          case '^':
            this.result = this.bigPower(a, parseInt(b))
            break
          case '%':
            this.result = this.bigMod(a, b)
            break
          case 'gcd':
            this.result = this.bigGCD(a, b)
            break
          case 'lcm':
            this.result = this.bigLCM(a, b)
            break
        }
        
        this.updateDetails()
      } catch (error) {
        this.$message.error('计算错误: ' + error.message)
      }
    },
    
    // Big number operations
    bigAdd(a, b) {
      let result = ''
      let carry = 0
      let i = a.length - 1
      let j = b.length - 1
      
      while (i >= 0 || j >= 0 || carry > 0) {
        const digitA = i >= 0 ? parseInt(a[i]) : 0
        const digitB = j >= 0 ? parseInt(b[j]) : 0
        const sum = digitA + digitB + carry
        
        result = (sum % 10) + result
        carry = Math.floor(sum / 10)
        
        i--
        j--
      }
      
      return result
    },
    
    bigSubtract(a, b) {
      if (this.compareBig(a, b) < 0) {
        return '-' + this.bigSubtract(b, a)
      }
      
      let result = ''
      let borrow = 0
      let i = a.length - 1
      let j = b.length - 1
      
      while (i >= 0) {
        const digitA = parseInt(a[i]) - borrow
        const digitB = j >= 0 ? parseInt(b[j]) : 0
        
        if (digitA < digitB) {
          result = (digitA + 10 - digitB) + result
          borrow = 1
        } else {
          result = (digitA - digitB) + result
          borrow = 0
        }
        
        i--
        j--
      }
      
      return result.replace(/^0+/, '') || '0'
    },
    
    bigMultiply(a, b) {
      if (a === '0' || b === '0') return '0'
      
      const result = Array(a.length + b.length).fill(0)
      
      for (let i = a.length - 1; i >= 0; i--) {
        for (let j = b.length - 1; j >= 0; j--) {
          const product = parseInt(a[i]) * parseInt(b[j])
          const sum = product + result[i + j + 1]
          
          result[i + j + 1] = sum % 10
          result[i + j] += Math.floor(sum / 10)
        }
      }
      
      return result.join('').replace(/^0+/, '')
    },
    
    bigDivide(a, b) {
      if (b === '0') throw new Error('除数不能为零')
      if (this.compareBig(a, b) < 0) return '0'
      
      let result = ''
      let remainder = ''
      
      for (let i = 0; i < a.length; i++) {
        remainder += a[i]
        remainder = remainder.replace(/^0+/, '') || '0'
        
        let count = 0
        while (this.compareBig(remainder, b) >= 0) {
          remainder = this.bigSubtract(remainder, b)
          count++
        }
        
        result += count
      }
      
      return result.replace(/^0+/, '') || '0'
    },
    
    bigPower(base, exp) {
      if (exp === 0) return '1'
      if (exp === 1) return base
      
      let result = '1'
      for (let i = 0; i < exp; i++) {
        result = this.bigMultiply(result, base)
      }
      return result
    },
    
    bigMod(a, b) {
      if (b === '0') throw new Error('除数不能为零')
      
      let remainder = ''
      for (let i = 0; i < a.length; i++) {
        remainder += a[i]
        remainder = remainder.replace(/^0+/, '') || '0'
        
        while (this.compareBig(remainder, b) >= 0) {
          remainder = this.bigSubtract(remainder, b)
        }
      }
      
      return remainder || '0'
    },
    
    bigGCD(a, b) {
      a = a.replace(/^0+/, '') || '0'
      b = b.replace(/^0+/, '') || '0'
      
      while (b !== '0') {
        const temp = b
        b = this.bigMod(a, b)
        a = temp
      }
      
      return a
    },
    
    bigLCM(a, b) {
      const gcd = this.bigGCD(a, b)
      return this.bigDivide(this.bigMultiply(a, b), gcd)
    },
    
    compareBig(a, b) {
      a = a.replace(/^0+/, '') || '0'
      b = b.replace(/^0+/, '') || '0'
      
      if (a.length !== b.length) {
        return a.length > b.length ? 1 : -1
      }
      
      for (let i = 0; i < a.length; i++) {
        if (a[i] !== b[i]) {
          return parseInt(a[i]) > parseInt(b[i]) ? 1 : -1
        }
      }
      
      return 0
    },
    
    updateDetails() {
      // Scientific notation
      if (this.result.length > 10) {
        this.scientificNotation = this.result[0] + '.' + this.result.slice(1, 5) + ' × 10^' + (this.result.length - 1)
      } else {
        this.scientificNotation = this.result
      }
      
      // Digit count
      this.digitCount = this.result.replace('-', '').length
      
      // Check prime (only for small numbers)
      this.isPrime = this.result.length <= 10 ? this.checkPrime(parseInt(this.result)) : false
      
      // Base conversions
      const num = parseInt(this.result)
      if (!isNaN(num) && num >= 0) {
        this.baseConversions = {
          binary: num.toString(2),
          octal: num.toString(8),
          decimal: num.toString(10),
          hex: num.toString(16).toUpperCase()
        }
      }
    },
    
    checkPrime(n) {
      if (n < 2) return false
      if (n === 2) return true
      if (n % 2 === 0) return false
      
      for (let i = 3; i <= Math.sqrt(n); i += 2) {
        if (n % i === 0) return false
      }
      return true
    },
    
    calculateFactorial() {
      let result = '1'
      for (let i = 2; i <= this.factorialInput; i++) {
        result = this.bigMultiply(result, i.toString())
      }
      this.factorialResult = result
    },
    
    calculateFibonacci() {
      if (this.fibonacciInput <= 2) {
        this.fibonacciResult = '1'
        return
      }
      
      let a = '1'
      let b = '1'
      
      for (let i = 3; i <= this.fibonacciInput; i++) {
        const temp = this.bigAdd(a, b)
        a = b
        b = temp
      }
      
      this.fibonacciResult = b
    },
    
    copy(text) {
      navigator.clipboard.writeText(text).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    
    clear() {
      this.numA = ''
      this.numB = ''
      this.result = ''
      this.scientificNotation = ''
      this.digitCount = 0
      this.isPrime = false
      this.baseConversions = { binary: '', octal: '', decimal: '', hex: '' }
    },
    
    loadExample() {
      this.numA = '123456789012345678901234567890'
      this.numB = '987654321098765432109876543210'
      this.operator = '*'
      this.calculate()
    }
  }
}
</script>

<style scoped>
.big-number-tool {
  padding: 20px;
}

.action-buttons {
  text-align: center;
  margin: 20px 0;
}

.result-section {
  text-align: center;
  padding: 20px;
  background: #f5f7fa;
  border-radius: 4px;
}

.result-value {
  font-size: 24px;
  font-weight: bold;
  color: #409eff;
  word-break: break-all;
  margin-bottom: 20px;
}

.result-details {
  margin-top: 15px;
}

.detail-item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.detail-label {
  font-size: 12px;
  color: #909399;
  margin-bottom: 5px;
}

.detail-value {
  font-size: 14px;
  color: #606266;
}

.function-result {
  margin-top: 10px;
  padding: 10px;
  background: #f5f7fa;
  border-radius: 4px;
  font-family: monospace;
  word-break: break-all;
}
</style>
