<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>YAML 格式化</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clear">清空当前</el-button>
        </el-button-group>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ tab.title }}
          </span>

          <el-row :gutter="20">
            <el-col :span="12">
              <div class="input-section">
                <div class="section-header">
                  <span>输入</span>
                </div>
                <el-input
                  v-model="tab.input"
                  type="textarea"
                  :rows="20"
                  placeholder="输入 YAML..."
                />
              </div>
            </el-col>

            <el-col :span="12">
              <div class="input-section">
                <div class="section-header">
                  <span>输出</span>
                  <div>
                    <el-button type="text" size="mini" @click="copyOutput(tab)">复制</el-button>
                    <el-button type="text" size="mini" @click="downloadOutput(tab)">下载</el-button>
                  </div>
                </div>
                <el-input
                  v-model="tab.output"
                  type="textarea"
                  :rows="20"
                  readonly
                  placeholder="格式化后的 YAML 将显示在这里..."
                />
              </div>
            </el-col>
          </el-row>

          <el-row style="margin-top: 20px">
            <el-col :span="24">
              <el-form :inline="true" size="small">
                <el-form-item label="缩进">
                  <el-select v-model="tab.indent">
                    <el-option label="2 空格" :value="2" />
                    <el-option label="4 空格" :value="4" />
                  </el-select>
                </el-form-item>
                <el-form-item label="排序">
                  <el-switch v-model="tab.sortKeys" />
                </el-form-item>
                <el-form-item>
                  <el-button type="primary" @click="format(tab)">格式化</el-button>
                  <el-button @click="loadExample(tab)">加载示例</el-button>
                </el-form-item>
              </el-form>
            </el-col>
          </el-row>

          <el-row style="margin-top: 20px">
            <el-col :span="24">
              <el-card shadow="never">
                <div slot="header">
                  <span>信息</span>
                </div>
                <el-descriptions :column="4" border size="small">
                  <el-descriptions-item label="输入行数">{{ inputLines(tab) }}</el-descriptions-item>
                  <el-descriptions-item label="输出行数">{{ outputLines(tab) }}</el-descriptions-item>
                  <el-descriptions-item label="缩进">{{ tab.indent }} 空格</el-descriptions-item>
                  <el-descriptions-item label="排序">{{ tab.sortKeys ? '是' : '否' }}</el-descriptions-item>
                </el-descriptions>
              </el-card>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'YamlTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: 'YAML ' + seq,
        input: '',
        output: '',
        indent: 2,
        sortKeys: false
      }
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clear()
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },
    inputLines(tab) {
      return tab.input.split('\n').length
    },
    outputLines(tab) {
      return tab.output.split('\n').length
    },
    format(tab) {
      if (!tab.input.trim()) {
        this.$message.warning('请输入 YAML')
        return
      }

      try {
        const parsed = this.parseYaml(tab.input)
        tab.output = this.stringifyYaml(parsed, tab.indent, tab.sortKeys)
        this.$message.success('格式化成功')
      } catch (error) {
        this.$message.error('格式化失败: ' + error.message)
      }
    },
    parseYaml(str) {
      const result = {}
      const lines = str.split('\n')
      let stack = [{ level: -1, obj: result }]

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i]
        if (!line.trim() || line.trim().startsWith('#')) continue

        const level = line.search(/\S/)
        const content = line.trim()

        while (stack.length > 1 && stack[stack.length - 1].level >= level) {
          stack.pop()
        }

        let parent = stack[stack.length - 1].obj

        if (content.includes(':')) {
          const [key, ...valueParts] = content.split(':')
          const value = valueParts.join(':').trim()

          if (value === '' || value === '|') {
            const newObj = {}
            parent[key] = newObj
            stack.push({ level, obj: newObj })
          } else if (value.startsWith('|')) {
            const blockValue = this.parseBlockValue(lines, i + 1, level + 1)
            parent[key] = blockValue.value
            i = blockValue.endIndex
          } else {
            parent[key] = this.parseValue(value)
          }
        } else if (content.startsWith('- ')) {
          const value = content.substring(2)
          if (!Array.isArray(parent)) {
            const keys = Object.keys(parent)
            const lastKey = keys[keys.length - 1]
            parent[lastKey] = [parent[lastKey]]
            stack[stack.length - 1].obj = parent[lastKey]
            parent = parent[lastKey] // 更新parent为新的数组
          }
          parent.push(this.parseValue(value))
        }
      }

      return result
    },
    parseValue(value) {
      if (value === 'true') return true
      if (value === 'false') return false
      if (value === 'null') return null
      if (value === '~') return null
      if (!isNaN(value)) return Number(value)
      if (value.startsWith('"') && value.endsWith('"')) return value.slice(1, -1)
      if (value.startsWith("'") && value.endsWith("'")) return value.slice(1, -1)
      return value
    },
    parseBlockValue(lines, startIndex, baseLevel) {
      const values = []
      let i = startIndex

      while (i < lines.length) {
        const line = lines[i]
        const level = line.search(/\S/)

        if (level <= baseLevel && line.trim() !== '') {
          break
        }

        values.push(line.substring(baseLevel))
        i++
      }

      return { value: values.join('\n'), endIndex: i - 1 }
    },
    stringifyYaml(obj, indent, sortKeys) {
      let result = ''

      const process = (value, level = 0) => {
        const spaces = ' '.repeat(level * indent)

        if (value === null) {
          return 'null'
        }

        if (typeof value === 'boolean') {
          return value ? 'true' : 'false'
        }

        if (typeof value === 'number') {
          return String(value)
        }

        if (typeof value === 'string') {
          if (value.includes('\n')) {
            return '|\n' + value.split('\n').map(line => spaces + '  ' + line).join('\n')
          }
          return value
        }

        if (Array.isArray(value)) {
          return value.map(item => {
            const itemStr = process(item, level + 1)
            if (typeof item === 'object' && item !== null) {
              return spaces + '-\n' + itemStr
            }
            return spaces + '- ' + itemStr
          }).join('\n')
        }

        if (typeof value === 'object') {
          const keys = sortKeys ? Object.keys(value).sort() : Object.keys(value)
          return keys.map(key => {
            const itemStr = process(value[key], level + 1)
            if (typeof value[key] === 'object' && value[key] !== null) {
              return spaces + key + ':\n' + itemStr
            }
            return spaces + key + ': ' + itemStr
          }).join('\n')
        }

        return String(value)
      }

      result = process(obj)
      return result
    },
    copyOutput(tab) {
      navigator.clipboard.writeText(tab.output).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    downloadOutput(tab) {
      const blob = new Blob([tab.output], { type: 'text/yaml;charset=utf-8;' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'formatted.yaml'
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    loadExample(tab) {
      tab.input = `name: John Doe
age: 30
address:
  street: 123 Main St
  city: New York
  zip: 10001
hobbies:
  - reading
  - swimming
  - coding
skills:
  - name: JavaScript
    level: advanced
  - name: Python
    level: intermediate
active: true
metadata:
  created: 2024-01-01
  updated: 2024-01-15`
      this.format(tab)
    },
    clear() {
      const tab = this.currentTab()
      if (!tab) return
      tab.input = ''
      tab.output = ''
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .tool-card {
    .header-actions {
      float: right;
    }
  }

  .input-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }
  }
}
</style>
