<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>JSON / YAML 互转</span>
        <el-button size="small" @click="clearAll">清空当前</el-button>
      </div>

      <el-tabs
        v-model="activeTab"
        type="card"
        editable
        @edit="handleTabEdit"
      >
        <el-tab-pane
          v-for="tab in tabs"
          :key="tab.id"
          :name="tab.id"
        >
          <span slot="label">
            <i class="el-icon-document" />
            {{ getTabTitle(tab) }}
          </span>

          <el-row :gutter="20">
            <el-col :span="11">
              <div class="input-section">
                <div class="section-header">
                  <span>JSON</span>
                  <el-tag size="mini" type="primary">输入或输出</el-tag>
                </div>
                <el-input
                  v-model="tab.jsonText"
                  type="textarea"
                  :rows="15"
                  placeholder='输入 JSON，如: {"name": "张三", "age": 25}'
                />
              </div>
            </el-col>

            <el-col :span="2" class="actions-col">
              <div class="action-buttons">
                <el-button type="primary" circle @click="jsonToYaml(tab)" title="JSON → YAML">
                  <i class="el-icon-right"></i>
                </el-button>
                <span class="action-label">JSON转YAML</span>
                <el-button type="success" circle @click="yamlToJson(tab)" title="YAML → JSON">
                  <i class="el-icon-back"></i>
                </el-button>
                <span class="action-label">YAML转JSON</span>
              </div>
            </el-col>

            <el-col :span="11">
              <div class="output-section">
                <div class="section-header">
                  <span>YAML</span>
                  <el-tag size="mini" type="success">输入或输出</el-tag>
                  <el-button type="text" size="mini" @click="copyYaml(tab)">复制</el-button>
                </div>
                <el-input
                  v-model="tab.yamlText"
                  type="textarea"
                  :rows="15"
                  placeholder="输入 YAML，如:\nname: 张三\nage: 25"
                />
              </div>
            </el-col>
          </el-row>

          <el-row style="margin-top: 20px">
            <el-col :span="24">
              <el-alert type="info" :closable="false" show-icon>
                <template slot="title">
                  使用提示：在任意一侧输入内容，点击中间按钮即可转换到另一侧
                </template>
              </el-alert>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'JsonYamlTool',
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: 'JSON⇄YAML ' + seq,
        jsonText: '',
        yamlText: ''
      }
    },
    getTabTitle(tab) {
      const content = tab.jsonText || ''
      const preview = content.trim().split('\n')[0].slice(0, 15)
      return preview ? `${tab.title}: ${preview}...` : tab.title
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅清空内容
        this.clearAll()
        this.$message.info('已清空内容（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    },
    jsonToYaml(tab) {
      if (!tab.jsonText.trim()) {
        this.$message.warning('请输入 JSON 内容')
        return
      }

      try {
        const obj = JSON.parse(tab.jsonText)
        tab.yamlText = this.convertToYaml(obj, 0)
        this.$message.success('转换成功')
      } catch (e) {
        this.$message.error('JSON 格式错误: ' + e.message)
      }
    },
    convertToYaml(obj, indent) {
      const spaces = '  '.repeat(indent)
      let result = ''

      if (obj === null) {
        return 'null'
      }

      if (typeof obj !== 'object') {
        if (typeof obj === 'string') {
          if (obj.includes('\n') || obj.includes(':') || obj.includes('#')) {
            return `"${obj.replace(/"/g, '\\"')}"`
          }
          return obj
        }
        return String(obj)
      }

      if (Array.isArray(obj)) {
        if (obj.length === 0) return '[]'

        obj.forEach(item => {
          if (typeof item === 'object' && item !== null) {
            result += `${spaces}-\n`
            const yaml = this.convertToYaml(item, indent + 1)
            const lines = yaml.split('\n').filter(l => l)
            lines.forEach(line => {
              result += `${spaces}  ${line.trim()}\n`
            })
          } else {
            result += `${spaces}- ${this.convertToYaml(item, 0)}\n`
          }
        })
        return result.trimEnd()
      }

      const keys = Object.keys(obj)
      if (keys.length === 0) return '{}'

      keys.forEach(key => {
        const value = obj[key]

        if (typeof value === 'object' && value !== null) {
          if (Array.isArray(value)) {
            result += `${spaces}${key}:\n`
            if (value.length > 0) {
              result += this.convertToYaml(value, indent + 1) + '\n'
            }
          } else {
            result += `${spaces}${key}:\n`
            const yaml = this.convertToYaml(value, indent + 1)
            if (yaml) {
              result += yaml + '\n'
            }
          }
        } else {
          result += `${spaces}${key}: ${this.convertToYaml(value, 0)}\n`
        }
      })

      return result.trimEnd()
    },
    yamlToJson(tab) {
      if (!tab.yamlText.trim()) {
        this.$message.warning('请输入 YAML 内容')
        return
      }

      try {
        const result = this.parseYaml(tab.yamlText.trim())
        tab.jsonText = JSON.stringify(result, null, 2)
        this.$message.success('转换成功')
      } catch (e) {
        this.$message.error('YAML 解析错误: ' + e.message)
      }
    },
    parseYaml(yaml) {
      const lines = yaml.split('\n')
      const result = {}
      const stack = [{ obj: result, indent: -1 }]

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i]
        if (!line.trim() || line.trim().startsWith('#')) continue

        const indent = line.search(/\S/)
        const content = line.trim()

        while (stack.length > 1 && stack[stack.length - 1].indent >= indent) {
          stack.pop()
        }

        const current = stack[stack.length - 1].obj

        if (content.startsWith('- ')) {
          const value = content.substring(2)
          if (!Array.isArray(current)) {
            const parent = stack[stack.length - 2]
            const key = Object.keys(parent.obj).find(k => parent.obj[k] === current)
            if (key) {
              parent.obj[key] = [current]
              stack[stack.length - 1] = { obj: parent.obj[key], indent: stack[stack.length - 1].indent }
            }
          }

          if (value.includes(':')) {
            const newObj = {}
            const [key, val] = value.split(':').map(s => s.trim())
            if (val) {
              newObj[key] = this.parseValue(val)
            } else {
              newObj[key] = {}
            }
            current.push(newObj)
            if (!val) {
              stack.push({ obj: newObj, indent })
            }
          } else {
            current.push(this.parseValue(value))
          }
        } else if (content.includes(':')) {
          const colonIndex = content.indexOf(':')
          const key = content.substring(0, colonIndex).trim()
          let value = content.substring(colonIndex + 1).trim()

          if (value) {
            current[key] = this.parseValue(value)
          } else {
            current[key] = {}
            stack.push({ obj: current[key], indent })
          }
        }
      }

      return result
    },
    parseValue(value) {
      if (value.startsWith('"') && value.endsWith('"')) {
        return value.slice(1, -1)
      }
      if (value.startsWith("'") && value.endsWith("'")) {
        return value.slice(1, -1)
      }
      if (value === 'true') return true
      if (value === 'false') return false
      if (value === 'null') return null
      if (value === '[]') return []
      if (value === '{}') return {}
      if (!isNaN(value) && value !== '') {
        return Number(value)
      }
      return value
    },
    clearAll() {
      const tab = this.currentTab()
      if (!tab) return
      tab.jsonText = ''
      tab.yamlText = ''
    },
    copyYaml(tab) {
      if (!tab.yamlText) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(tab.yamlText).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    }
  }
}
</script>

