<template>
  <div class="sql-builder-tool">
    <el-card>
      <div slot="header">
        <span>SQL 生成器</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="loadExample">加载示例</el-button>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-form :model="config" label-width="100px">
            <el-form-item label="SQL类型">
              <el-radio-group v-model="config.sqlType">
                <el-radio-button label="insert">INSERT</el-radio-button>
                <el-radio-button label="update">UPDATE</el-radio-button>
                <el-radio-button label="delete">DELETE</el-radio-button>
                <el-radio-button label="select">SELECT</el-radio-button>
                <el-radio-button label="create">CREATE TABLE</el-radio-button>
              </el-radio-group>
            </el-form-item>

            <el-form-item label="表名">
              <el-input v-model="config.tableName" placeholder="输入表名" />
            </el-form-item>

            <template v-if="config.sqlType === 'insert' || config.sqlType === 'update'">
              <el-form-item label="数据来源">
                <el-radio-group v-model="config.dataSource">
                  <el-radio-button label="json">JSON</el-radio-button>
                  <el-radio-button label="csv">CSV</el-radio-button>
                  <el-radio-button label="form">表单</el-radio-button>
                </el-radio-group>
              </el-form-item>
            </template>

            <template v-if="config.sqlType === 'create'">
              <el-form-item label="字段定义">
                <div v-for="(field, index) in config.fields" :key="index" class="field-row">
                  <el-input v-model="field.name" placeholder="字段名" size="small" style="width: 120px" />
                  <el-select v-model="field.type" placeholder="类型" size="small" style="width: 120px; margin: 0 5px">
                    <el-option label="VARCHAR" value="VARCHAR(255)" />
                    <el-option label="INT" value="INT" />
                    <el-option label="BIGINT" value="BIGINT" />
                    <el-option label="DECIMAL" value="DECIMAL(10,2)" />
                    <el-option label="TEXT" value="TEXT" />
                    <el-option label="DATETIME" value="DATETIME" />
                    <el-option label="DATE" value="DATE" />
                    <el-option label="BOOLEAN" value="BOOLEAN" />
                  </el-select>
                  <el-checkbox v-model="field.nullable" size="small">可空</el-checkbox>
                  <el-checkbox v-model="field.primary" size="small">主键</el-checkbox>
                  <el-button type="text" size="small" @click="removeField(index)">删除</el-button>
                </div>
                <el-button type="text" @click="addField">+ 添加字段</el-button>
              </el-form-item>
            </template>

            <template v-if="config.sqlType === 'select'">
              <el-form-item label="查询字段">
                <el-input v-model="config.selectFields" placeholder="* 或 field1, field2" />
              </el-form-item>
              <el-form-item label="WHERE条件">
                <el-input v-model="config.whereClause" type="textarea" :rows="2" placeholder="id = 1 AND name = 'test'" />
              </el-form-item>
              <el-form-item label="排序">
                <el-input v-model="config.orderBy" placeholder="id DESC" />
              </el-form-item>
              <el-form-item label="限制">
                <el-input-number v-model="config.limit" :min="0" :max="10000" />
              </el-form-item>
            </template>
          </el-form>
        </el-col>

        <el-col :span="12">
          <div class="data-input" v-if="config.sqlType === 'insert' || config.sqlType === 'update'">
            <div class="section-title">数据输入</div>
            <el-input
              v-if="config.dataSource === 'json'"
              v-model="dataInput"
              type="textarea"
              :rows="12"
              placeholder='[{"name": "张三", "age": 25}, ...]'
            />
            <el-input
              v-else-if="config.dataSource === 'csv'"
              v-model="dataInput"
              type="textarea"
              :rows="12"
              placeholder="name,age&#10;张三,25&#10;李四,30"
            />
            <div v-else class="form-data">
              <div v-for="(item, index) in formData" :key="index" class="form-row">
                <el-input v-model="item.key" placeholder="字段名" size="small" style="width: 120px" />
                <el-input v-model="item.value" placeholder="值" size="small" style="width: 150px; margin: 0 5px" />
                <el-button type="text" size="small" @click="removeFormItem(index)">删除</el-button>
              </div>
              <el-button type="text" @click="addFormItem">+ 添加字段</el-button>
            </div>
          </div>
        </el-col>
      </el-row>

      <el-divider></el-divider>

      <div class="action-buttons">
        <el-button type="primary" @click="generateSql">生成 SQL</el-button>
        <el-button @click="copySql">复制</el-button>
        <el-button @click="downloadSql">下载</el-button>
        <el-button @click="clear">清空</el-button>
      </div>

      <div class="output-section">
        <div class="section-title">生成的 SQL</div>
        <el-input
          v-model="sqlOutput"
          type="textarea"
          :rows="15"
          readonly
          placeholder="生成的 SQL 语句将显示在这里..."
        />
      </div>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'SqlBuilderTool',
  data() {
    return {
      config: {
        sqlType: 'insert',
        tableName: '',
        dataSource: 'json',
        fields: [{ name: '', type: 'VARCHAR(255)', nullable: true, primary: false }],
        selectFields: '*',
        whereClause: '',
        orderBy: '',
        limit: 0
      },
      dataInput: '',
      formData: [{ key: '', value: '' }],
      sqlOutput: ''
    }
  },
  methods: {
    generateSql() {
      if (!this.config.tableName) {
        this.$message.warning('请输入表名')
        return
      }

      switch (this.config.sqlType) {
        case 'insert':
          this.generateInsert()
          break
        case 'update':
          this.generateUpdate()
          break
        case 'delete':
          this.generateDelete()
          break
        case 'select':
          this.generateSelect()
          break
        case 'create':
          this.generateCreate()
          break
      }
    },
    generateInsert() {
      let data = []
      try {
        if (this.config.dataSource === 'json') {
          data = JSON.parse(this.dataInput)
          if (!Array.isArray(data)) data = [data]
        } else if (this.config.dataSource === 'csv') {
          data = this.parseCsv(this.dataInput)
        } else {
          data = [this.formData.reduce((obj, item) => {
            if (item.key) obj[item.key] = item.value
            return obj
          }, {})]
        }
      } catch (e) {
        this.$message.error('数据格式错误: ' + e.message)
        return
      }

      if (data.length === 0) {
        this.$message.warning('没有数据')
        return
      }

      const columns = Object.keys(data[0])
      const sqls = data.map(row => {
        const values = columns.map(col => this.escapeValue(row[col]))
        return `INSERT INTO ${this.config.tableName} (${columns.join(', ')}) VALUES (${values.join(', ')});`
      })

      this.sqlOutput = sqls.join('\n')
    },
    generateUpdate() {
      let data = []
      try {
        if (this.config.dataSource === 'json') {
          data = JSON.parse(this.dataInput)
          if (!Array.isArray(data)) data = [data]
        } else if (this.config.dataSource === 'csv') {
          data = this.parseCsv(this.dataInput)
        } else {
          data = [this.formData.reduce((obj, item) => {
            if (item.key) obj[item.key] = item.value
            return obj
          }, {})]
        }
      } catch (e) {
        this.$message.error('数据格式错误: ' + e.message)
        return
      }

      const sqls = data.map(row => {
        const sets = Object.entries(row)
          .filter(([key]) => key !== 'id')
          .map(([key, value]) => `${key} = ${this.escapeValue(value)}`)
          .join(', ')
        const where = row.id ? `WHERE id = ${this.escapeValue(row.id)}` : ''
        return `UPDATE ${this.config.tableName} SET ${sets} ${where};`
      })

      this.sqlOutput = sqls.join('\n')
    },
    generateDelete() {
      this.sqlOutput = `DELETE FROM ${this.config.tableName};`
    },
    generateSelect() {
      let sql = `SELECT ${this.config.selectFields || '*'} FROM ${this.config.tableName}`
      if (this.config.whereClause) {
        sql += ` WHERE ${this.config.whereClause}`
      }
      if (this.config.orderBy) {
        sql += ` ORDER BY ${this.config.orderBy}`
      }
      if (this.config.limit > 0) {
        sql += ` LIMIT ${this.config.limit}`
      }
      this.sqlOutput = sql + ';'
    },
    generateCreate() {
      const validFields = this.config.fields.filter(f => f.name)
      if (validFields.length === 0) {
        this.$message.warning('请至少添加一个字段')
        return
      }

      const fieldDefs = validFields.map(f => {
        let def = `  ${f.name} ${f.type}`
        if (!f.nullable) def += ' NOT NULL'
        if (f.primary) def += ' PRIMARY KEY'
        return def
      })

      this.sqlOutput = `CREATE TABLE ${this.config.tableName} (\n${fieldDefs.join(',\n')}\n);`
    },
    parseCsv(csvText) {
      const lines = csvText.trim().split('\n')
      if (lines.length < 2) return []
      
      const headers = lines[0].split(',').map(h => h.trim())
      return lines.slice(1).map(line => {
        const values = line.split(',').map(v => v.trim())
        return headers.reduce((obj, header, index) => {
          obj[header] = values[index] || ''
          return obj
        }, {})
      })
    },
    escapeValue(value) {
      if (value === null || value === undefined) return 'NULL'
      if (typeof value === 'number' || typeof value === 'boolean') return value
      if (typeof value === 'string') {
        return `'${value.replace(/'/g, "''")}'`
      }
      return `'${String(value).replace(/'/g, "''")}'`
    },
    addField() {
      this.config.fields.push({ name: '', type: 'VARCHAR(255)', nullable: true, primary: false })
    },
    removeField(index) {
      this.config.fields.splice(index, 1)
    },
    addFormItem() {
      this.formData.push({ key: '', value: '' })
    },
    removeFormItem(index) {
      this.formData.splice(index, 1)
    },
    copySql() {
      if (!this.sqlOutput) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.sqlOutput).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    downloadSql() {
      if (!this.sqlOutput) {
        this.$message.warning('没有可下载的内容')
        return
      }
      const blob = new Blob([this.sqlOutput], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = `${this.config.tableName || 'query'}.sql`
      link.click()
      URL.revokeObjectURL(url)
    },
    clear() {
      this.dataInput = ''
      this.sqlOutput = ''
      this.formData = [{ key: '', value: '' }]
    },
    loadExample() {
      this.config.sqlType = 'insert'
      this.config.tableName = 'users'
      this.config.dataSource = 'json'
      this.dataInput = JSON.stringify([
        { id: 1, name: '张三', email: 'zhangsan@example.com', age: 25 },
        { id: 2, name: '李四', email: 'lisi@example.com', age: 30 },
        { id: 3, name: '王五', email: 'wangwu@example.com', age: 28 }
      ], null, 2)
      this.generateSql()
    }
  }
}
</script>

<style scoped>
.sql-builder-tool {
  padding: 20px;
}

.field-row, .form-row {
  display: flex;
  align-items: center;
  margin-bottom: 10px;
}

.data-input, .output-section {
  margin-bottom: 20px;
}

.section-title {
  font-weight: bold;
  margin-bottom: 10px;
  color: #606266;
}

.action-buttons {
  text-align: center;
  margin-bottom: 20px;
}

.form-data {
  border: 1px solid #dcdfe6;
  padding: 15px;
  border-radius: 4px;
}
</style>
