<template>
  <div class="regex-toolbox">
    <!-- 外层：文档级多标签，每个标签是一个独立工作区 -->
    <el-tabs
      v-model="activeTab"
      type="card"
      editable
      @edit="handleTabEdit"
    >
      <el-tab-pane
        v-for="tab in tabs"
        :key="tab.id"
        :name="tab.id"
      >
        <span slot="label">
          <i class="el-icon-document" />
          {{ tab.title }}
        </span>

        <!-- 内层：功能分区标签，选中态按文档隔离（tab.innerTab） -->
        <el-tabs v-model="tab.innerTab">
          <el-tab-pane label="正则测试" name="test">
            <!-- key 含文档 id，保证每个工作区拥有独立的组件实例与状态 -->
            <RegexTool :key="tab.id + '-test'" />
          </el-tab-pane>
          <el-tab-pane label="正则生成器" name="builder">
            <RegexBuilderTool :key="tab.id + '-builder'" />
          </el-tab-pane>
        </el-tabs>
      </el-tab-pane>
    </el-tabs>
  </div>
</template>

<script>
import RegexTool from '../generate/RegexTool.vue'
import RegexBuilderTool from '../dev/RegexBuilderTool.vue'

export default {
  name: 'RegexToolbox',
  components: { RegexTool, RegexBuilderTool },
  data() {
    return {
      activeTab: 'tab-1',
      tabCounter: 1,
      tabs: [this.createTab(1)]
    }
  },
  methods: {
    createTab(seq) {
      return {
        id: 'tab-' + seq,
        title: '正则 ' + seq,
        // 每个文档记住自己停在哪个功能分区
        innerTab: 'test'
      }
    },
    handleTabEdit(targetName, action) {
      if (action === 'add') {
        this.addTab()
      } else if (action === 'remove') {
        this.removeTab(targetName)
      }
    },
    addTab() {
      this.tabCounter++
      const tab = this.createTab(this.tabCounter)
      this.tabs.push(tab)
      this.activeTab = tab.id
    },
    removeTab(targetName) {
      if (this.tabs.length === 1) {
        // 只剩一个标签时不关闭，仅重置为一个全新的空白工作区
        this.tabCounter++
        const tab = this.createTab(this.tabCounter)
        this.tabs.splice(0, 1, tab)
        this.activeTab = tab.id
        this.$message.info('已重置工作区（至少保留一个标签）')
        return
      }
      const index = this.tabs.findIndex(t => t.id === targetName)
      if (index === -1) return

      // 关闭的是当前激活标签时，切换到相邻标签
      if (this.activeTab === targetName) {
        const next = this.tabs[index + 1] || this.tabs[index - 1]
        this.activeTab = next.id
      }
      this.tabs.splice(index, 1)
    },
    currentTab() {
      return this.tabs.find(t => t.id === this.activeTab)
    }
  }
}
</script>

<style lang="scss" scoped>
.regex-toolbox {
  width: 100%;
}
</style>
