<template>
  <div class="image-convert-tool">
    <el-card>
      <div slot="header">
        <span>图片格式转换</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-upload
            drag
            action="#"
            :auto-upload="false"
            :show-file-list="false"
            accept="image/*"
            @change="handleFileChange"
          >
            <i class="el-icon-upload"></i>
            <div class="el-upload__text">拖拽图片到此处，或<em>点击选择</em></div>
            <div class="el-upload__tip" slot="tip">支持 PNG、JPG、WebP、GIF、BMP 格式</div>
          </el-upload>

          <div v-if="originalImage" class="image-preview">
            <el-divider>原始图片</el-divider>
            <img :src="originalImage" alt="原始图片" />
            <div class="image-info">
              <p>格式: {{ originalFormat }}</p>
              <p>尺寸: {{ originalWidth }} x {{ originalHeight }}</p>
              <p>大小: {{ formatSize(originalSize) }}</p>
            </div>
          </div>
        </el-col>

        <el-col :span="12">
          <el-form label-width="100px">
            <el-form-item label="输出格式">
              <el-select v-model="outputFormat" style="width: 100%">
                <el-option label="PNG" value="png" />
                <el-option label="JPEG" value="jpeg" />
                <el-option label="WebP" value="webp" />
                <el-option label="BMP" value="bmp" />
              </el-select>
            </el-form-item>

            <el-form-item label="质量" v-if="outputFormat === 'jpeg' || outputFormat === 'webp'">
              <el-slider v-model="quality" :min="0" :max="100" :step="1" />
              <span>{{ quality }}%</span>
            </el-form-item>

            <el-form-item label="调整尺寸">
              <el-checkbox v-model="resize">启用</el-checkbox>
            </el-form-item>

            <el-form-item label="宽度" v-if="resize">
              <el-input-number v-model="newWidth" :min="1" :max="10000" />
            </el-form-item>

            <el-form-item label="高度" v-if="resize">
              <el-input-number v-model="newHeight" :min="1" :max="10000" />
            </el-form-item>

            <el-form-item label="保持比例" v-if="resize">
              <el-checkbox v-model="keepRatio">保持宽高比</el-checkbox>
            </el-form-item>
          </el-form>

          <div v-if="convertedImage" class="image-preview">
            <el-divider>转换结果</el-divider>
            <img :src="convertedImage" alt="转换后图片" />
            <div class="image-info">
              <p>格式: {{ outputFormat.toUpperCase() }}</p>
              <p>大小: {{ formatSize(convertedSize) }}</p>
            </div>
          </div>
        </el-col>
      </el-row>

      <div class="action-buttons">
        <el-button type="primary" @click="convertImage" :disabled="!originalImage">转换</el-button>
        <el-button @click="downloadImage" :disabled="!convertedImage">下载</el-button>
        <el-button @click="clear">清空</el-button>
      </div>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'ImageConvertTool',
  data() {
    return {
      originalImage: null,
      originalFormat: '',
      originalWidth: 0,
      originalHeight: 0,
      originalSize: 0,
      convertedImage: null,
      convertedSize: 0,
      outputFormat: 'png',
      quality: 80,
      resize: false,
      newWidth: 800,
      newHeight: 600,
      keepRatio: true
    }
  },
  methods: {
    handleFileChange(file) {
      const rawFile = file.raw
      if (!rawFile) return

      this.originalSize = rawFile.size
      this.originalFormat = rawFile.type.split('/')[1].toUpperCase()

      const reader = new FileReader()
      reader.onload = (e) => {
        this.originalImage = e.target.result

        const img = new Image()
        img.onload = () => {
          this.originalWidth = img.width
          this.originalHeight = img.height
          this.newWidth = img.width
          this.newHeight = img.height
        }
        img.src = e.target.result
      }
      reader.readAsDataURL(rawFile)
    },
    convertImage() {
      if (!this.originalImage) {
        this.$message.warning('请先选择图片')
        return
      }

      const img = new Image()
      img.onload = () => {
        const canvas = document.createElement('canvas')
        const ctx = canvas.getContext('2d')

        let width = img.width
        let height = img.height

        if (this.resize) {
          width = this.newWidth
          height = this.newHeight
        }

        canvas.width = width
        canvas.height = height

        ctx.drawImage(img, 0, 0, width, height)

        const mimeType = `image/${this.outputFormat}`
        const quality = (this.outputFormat === 'jpeg' || this.outputFormat === 'webp') 
          ? this.quality / 100 
          : undefined

        this.convertedImage = canvas.toDataURL(mimeType, quality)

        const base64Length = this.convertedImage.length - `data:image/${this.outputFormat};base64,`.length
        this.convertedSize = Math.round(base64Length * 0.75)

        this.$message.success('转换完成')
      }
      img.src = this.originalImage
    },
    downloadImage() {
      if (!this.convertedImage) return

      const link = document.createElement('a')
      link.download = `converted.${this.outputFormat}`
      link.href = this.convertedImage
      link.click()
    },
    formatSize(bytes) {
      if (bytes < 1024) return bytes + ' B'
      if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(2) + ' KB'
      return (bytes / (1024 * 1024)).toFixed(2) + ' MB'
    },
    clear() {
      this.originalImage = null
      this.convertedImage = null
      this.originalFormat = ''
      this.originalWidth = 0
      this.originalHeight = 0
      this.originalSize = 0
      this.convertedSize = 0
    }
  }
}
</script>

<style scoped>
.image-convert-tool {
  padding: 20px;
}

.image-preview {
  margin-top: 20px;
  text-align: center;
}

.image-preview img {
  max-width: 100%;
  max-height: 300px;
  border: 1px solid #dcdfe6;
  border-radius: 4px;
}

.image-info {
  margin-top: 10px;
  color: #606266;
  font-size: 14px;
}

.image-info p {
  margin: 5px 0;
}

.action-buttons {
  text-align: center;
  margin-top: 20px;
}
</style>
